INSERT INTO public.ai_models VALUES ('minimax/minimax-m2-her', 'MiniMax M2-her', 'MiniMax M2-her is a dialogue-first large language model built for immersive roleplay, character-driven chat, and expressive multi-turn conversations. Designed to stay consistent in tone and personality, it supports rich message roles (user_system, group, sample_message_user, sample_message_ai) and can learn from example dialogue to better match the style and pacing of your scenario, making it a strong choice for storytelling, companions, and conversational experiences where natural flow and vivid interaction matter most.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.3, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 1.2, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.03, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 32768, 'remote', '2026-01-23', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('writer/palmyra-x5', 'Palmyra X5', 'Palmyra X5 is Writer''s most advanced model, purpose-built for building and scaling AI agents across the enterprise. It delivers industry-leading speed and efficiency on context windows up to 1 million tokens, powered by a novel transformer architecture and hybrid attention mechanisms. This enables faster inference and expanded memory for processing large volumes of enterprise data, critical for scaling AI agents.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.6, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 6, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 1040000, 'remote', '2026-01-21', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('liquid/lfm-2.5-1.2b-thinking:free', 'LFM2.5-1.2B-Thinking (free)', 'LFM2.5-1.2B-Thinking is a lightweight reasoning-focused model optimized for agentic tasks, data extraction, and RAG—while still running comfortably on edge devices. It supports long context (up to 32K tokens) and is designed to provide higher-quality “thinking” responses in a small 1.2B model.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": false}', 32768, 'remote', '2026-01-20', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('openai/gpt-audio', 'GPT Audio', 'The gpt-audio model is OpenAI''s first generally available audio model. The new snapshot features an upgraded decoder for more natural sounding voices and maintains better voice consistency. Audio is priced at $32 per million input tokens and $64 per million output tokens.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 2.5, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 10, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 128000, 'remote', '2026-01-19', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('openai/gpt-audio-mini', 'GPT Audio Mini', 'A cost-efficient version of GPT Audio. The new snapshot features an upgraded decoder for more natural sounding voices and maintains better voice consistency. Input is priced at $0.60 per million tokens and output is priced at $2.40 per million tokens.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.6, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 2.4, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 128000, 'remote', '2026-01-19', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('z-ai/glm-4.7-flash', 'GLM 4.7 Flash', 'As a 30B-class SOTA model, GLM-4.7-Flash offers a new option that balances performance and efficiency. It is further optimized for agentic coding use cases, strengthening coding capabilities, long-horizon task planning, and tool collaboration, and has achieved leading performance among open-source models of the same size on several current public benchmark leaderboards.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.07, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.4, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.01, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": true}', 200000, 'remote', '2026-01-19', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('openai/gpt-5.2-codex', 'GPT-5.2-Codex', 'GPT-5.2-Codex is an upgraded version of GPT-5.1-Codex optimized for software engineering and coding workflows. It is designed for both interactive development sessions and long, independent execution of complex engineering tasks. The model supports building projects from scratch, feature development, debugging, large-scale refactoring, and code review. Compared to GPT-5.1-Codex, 5.2-Codex is more steerable, adheres closely to developer instructions, and produces cleaner, higher-quality code outputs. Reasoning effort can be adjusted with the `reasoning.effort` parameter. Read the [docs here](https://openrouter.ai/docs/use-cases/reasoning-tokens#reasoning-effort-level)

Codex integrates into developer environments including the CLI, IDE extensions, GitHub, and cloud tasks. It adapts reasoning effort dynamically—providing fast responses for small tasks while sustaining extended multi-hour runs for large projects. The model is trained to perform structured code reviews, catching critical flaws by reasoning over dependencies and validating behavior against tests. It also supports multimodal inputs such as images or screenshots for UI development and integrates tool use for search, dependency installation, and environment setup. Codex is intended specifically for agentic coding applications.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 1.75, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 14, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.175, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": true}', 400000, 'remote', '2026-01-14', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('allenai/molmo-2-8b:free', 'Molmo2 8B (free)', 'Molmo2-8B is an open vision-language model developed by the Allen Institute for AI (Ai2) as part of the Molmo2 family, supporting image, video, and multi-image understanding and grounding. It is based on Qwen3-8B and uses SigLIP 2 as its vision backbone, outperforming other open-weight, open-data models on short videos, counting, and captioning, while remaining competitive on long-video tasks.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": false}', 36864, 'remote', '2026-01-09', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('allenai/olmo-3.1-32b-instruct', 'Olmo 3.1 32B Instruct', 'Olmo 3.1 32B Instruct is a large-scale, 32-billion-parameter instruction-tuned language model engineered for high-performance conversational AI, multi-turn dialogue, and practical instruction following. As part of the Olmo 3.1 family, this variant emphasizes responsiveness to complex user directions and robust chat interactions while retaining strong capabilities on reasoning and coding benchmarks. Developed by Ai2 under the Apache 2.0 license, Olmo 3.1 32B Instruct reflects the Olmo initiative’s commitment to openness and transparency.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.2, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.6, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 65536, 'remote', '2026-01-06', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('bytedance-seed/seed-1.6-flash', 'Seed 1.6 Flash', 'Seed 1.6 Flash is an ultra-fast multimodal deep thinking model by ByteDance Seed, supporting both text and visual understanding. It features a 256k context window and can generate outputs of up to 16k tokens.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.075, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.3, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": true}', 262144, 'remote', '2025-12-23', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('bytedance-seed/seed-1.6', 'Seed 1.6', 'Seed 1.6 is a general-purpose model released by the ByteDance Seed team. It incorporates multimodal capabilities and adaptive deep thinking with a 256K context window.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.25, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 2, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": true}', 262144, 'remote', '2025-12-23', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('minimax/minimax-m2.1', 'MiniMax M2.1', 'MiniMax-M2.1 is a lightweight, state-of-the-art large language model optimized for coding, agentic workflows, and modern application development. With only 10 billion activated parameters, it delivers a major jump in real-world capability while maintaining exceptional latency, scalability, and cost efficiency.

Compared to its predecessor, M2.1 delivers cleaner, more concise outputs and faster perceived response times. It shows leading multilingual coding performance across major systems and application languages, achieving 49.4% on Multi-SWE-Bench and 72.5% on SWE-Bench Multilingual, and serves as a versatile agent “brain” for IDEs, coding tools, and general-purpose assistance.

To avoid degrading this model''s performance, MiniMax highly recommends preserving reasoning between turns. Learn more about using reasoning_details to pass back reasoning in our [docs](https://openrouter.ai/docs/use-cases/reasoning-tokens#preserving-reasoning-blocks).', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.27, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 1.1, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": true}', 196608, 'remote', '2025-12-23', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('z-ai/glm-4.7', 'GLM 4.7', 'GLM-4.7 is Z.AI’s latest flagship model, featuring upgrades in two key areas: enhanced programming capabilities and more stable multi-step reasoning/execution. It demonstrates significant improvements in executing complex agent tasks while delivering more natural conversational experiences and superior front-end aesthetics.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.4, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 1.5, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": true}', 202752, 'remote', '2025-12-22', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('mistralai/mistral-small-creative', 'Mistral Small Creative', 'Mistral Small Creative is an experimental small model designed for creative writing, narrative generation, roleplay and character-driven dialogue, general-purpose instruction following, and conversational agents.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.1, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.3, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 32768, 'remote', '2025-12-16', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('allenai/olmo-3.1-32b-think', 'Olmo 3.1 32B Think', 'Olmo 3.1 32B Think is a large-scale, 32-billion-parameter model designed for deep reasoning, complex multi-step logic, and advanced instruction following. Building on the Olmo 3 series, version 3.1 delivers refined reasoning behavior and stronger performance across demanding evaluations and nuanced conversational tasks. Developed by Ai2 under the Apache 2.0 license, Olmo 3.1 32B Think continues the Olmo initiative’s commitment to openness, providing full transparency across model weights, code, and training methodology.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.15, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.5, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": false}', 65536, 'remote', '2025-12-16', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('xiaomi/mimo-v2-flash', 'MiMo-V2-Flash', 'MiMo-V2-Flash is an open-source foundation language model developed by Xiaomi. It is a Mixture-of-Experts model with 309B total parameters and 15B active parameters, adopting hybrid attention architecture. MiMo-V2-Flash supports a hybrid-thinking toggle and a 256K context window, and excels at reasoning, coding, and agent scenarios. On SWE-bench Verified and SWE-bench Multilingual, MiMo-V2-Flash ranks as the top #1 open-source model globally, delivering performance comparable to Claude Sonnet 4.5 while costing only about 3.5% as much.

Users can control the reasoning behaviour with the `reasoning` `enabled` boolean. [Learn more in our docs](https://openrouter.ai/docs/use-cases/reasoning-tokens#enable-reasoning-with-default-config).', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.09, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.29, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": true}', 262144, 'remote', '2025-12-14', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('nvidia/nemotron-3-nano-30b-a3b:free', 'Nemotron 3 Nano 30B A3B (free)', 'NVIDIA Nemotron 3 Nano 30B A3B is a small language MoE model with highest compute efficiency and accuracy for developers to build specialized agentic AI systems.

The model is fully open with open-weights, datasets and recipes so developers can easily
customize, optimize, and deploy the model on their infrastructure for maximum privacy and
security.

Note: For the free endpoint, all prompts and output are logged to improve the provider''s model and its product and services. Please do not upload any personal, confidential, or otherwise sensitive information. This is a trial use only. Do not use for production or business-critical systems.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": true}', 256000, 'remote', '2025-12-14', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('nvidia/nemotron-3-nano-30b-a3b', 'Nemotron 3 Nano 30B A3B', 'NVIDIA Nemotron 3 Nano 30B A3B is a small language MoE model with highest compute efficiency and accuracy for developers to build specialized agentic AI systems.

The model is fully open with open-weights, datasets and recipes so developers can easily
customize, optimize, and deploy the model on their infrastructure for maximum privacy and
security.

Note: For the free endpoint, all prompts and output are logged to improve the provider''s model and its product and services. Please do not upload any personal, confidential, or otherwise sensitive information. This is a trial use only. Do not use for production or business-critical systems.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.06, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.24, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": true}', 262144, 'remote', '2025-12-14', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('openai/gpt-5.2-chat', 'GPT-5.2 Chat', 'GPT-5.2 Chat (AKA Instant) is the fast, lightweight member of the 5.2 family, optimized for low-latency chat while retaining strong general intelligence. It uses adaptive reasoning to selectively “think” on harder queries, improving accuracy on math, coding, and multi-step tasks without slowing down typical conversations. The model is warmer and more conversational by default, with better instruction following and more stable short-form reasoning. GPT-5.2 Chat is designed for high-throughput, interactive workloads where responsiveness and consistency matter more than deep deliberation.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 1.75, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 14, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.175, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": true}', 128000, 'remote', '2025-12-10', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('openai/gpt-5.2-pro', 'GPT-5.2 Pro', 'GPT-5.2 Pro is OpenAI’s most advanced model, offering major improvements in agentic coding and long context performance over GPT-5 Pro. It is optimized for complex tasks that require step-by-step reasoning, instruction following, and accuracy in high-stakes use cases. It supports test-time routing features and advanced prompt understanding, including user-specified intent like "think hard about this." Improvements include reductions in hallucination, sycophancy, and better performance in coding, writing, and health-related tasks.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 21, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 168, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": true}', 400000, 'remote', '2025-12-10', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('openai/gpt-5.2', 'GPT-5.2', 'GPT-5.2 is the latest frontier-grade model in the GPT-5 series, offering stronger agentic and long context perfomance compared to GPT-5.1. It uses adaptive reasoning to allocate computation dynamically, responding quickly to simple queries while spending more depth on complex tasks.

Built for broad task coverage, GPT-5.2 delivers consistent gains across math, coding, sciende, and tool calling workloads, with more coherent long-form answers and improved tool-use reliability.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 1.75, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 14, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.175, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": true}', 400000, 'remote', '2025-12-10', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('mistralai/devstral-2512:free', 'Devstral 2 2512 (free)', 'Devstral 2 is a state-of-the-art open-source model by Mistral AI specializing in agentic coding. It is a 123B-parameter dense transformer model supporting a 256K context window.

Devstral 2 supports exploring codebases and orchestrating changes across multiple files while maintaining architecture-level context. It tracks framework dependencies, detects failures, and retries with corrections—solving challenges like bug fixing and modernizing legacy systems. The model can be fine-tuned to prioritize specific languages or optimize for large enterprise codebases. It is available under a modified MIT license.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 262144, 'remote', '2025-12-09', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('mistralai/devstral-2512', 'Devstral 2 2512', 'Devstral 2 is a state-of-the-art open-source model by Mistral AI specializing in agentic coding. It is a 123B-parameter dense transformer model supporting a 256K context window.

Devstral 2 supports exploring codebases and orchestrating changes across multiple files while maintaining architecture-level context. It tracks framework dependencies, detects failures, and retries with corrections—solving challenges like bug fixing and modernizing legacy systems. The model can be fine-tuned to prioritize specific languages or optimize for large enterprise codebases. It is available under a modified MIT license.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.05, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.22, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 262144, 'remote', '2025-12-09', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('relace/relace-search', 'Relace Search', 'The relace-search model uses 4-12 `view_file` and `grep` tools in parallel to explore a codebase and return relevant files to the user request. 

In contrast to RAG, relace-search performs agentic multi-step reasoning to produce highly precise results 4x faster than any frontier model. It''s designed to serve as a subagent that passes its findings to an "oracle" coding agent, who orchestrates/performs the rest of the coding task.

To use relace-search you need to build an appropriate agent harness, and parse the response for relevant information to hand off to the oracle. Read more about it in the [Relace documentation](https://docs.relace.ai/docs/fast-agentic-search/agent).', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 1, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 3, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": true, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 256000, 'remote', '2025-12-08', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('z-ai/glm-4.6v', 'GLM 4.6V', 'GLM-4.6V is a large multimodal model designed for high-fidelity visual understanding and long-context reasoning across images, documents, and mixed media. It supports up to 128K tokens, processes complex page layouts and charts directly as visual inputs, and integrates native multimodal function calling to connect perception with downstream tool execution. The model also enables interleaved image-text generation and UI reconstruction workflows, including screenshot-to-HTML synthesis and iterative visual editing.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.3, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.9, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": true}', 131072, 'remote', '2025-12-08', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('nex-agi/deepseek-v3.1-nex-n1', 'DeepSeek V3.1 Nex N1', 'DeepSeek V3.1 Nex-N1 is the flagship release of the Nex-N1 series — a post-trained model designed to highlight agent autonomy, tool use, and real-world productivity. 

Nex-N1 demonstrates competitive performance across all evaluation scenarios, showing particularly strong results in practical coding and HTML generation tasks.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.27, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 1, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheWrite", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 131072, 'remote', '2025-12-08', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('essentialai/rnj-1-instruct', 'Rnj 1 Instruct', 'Rnj-1 is an 8B-parameter, dense, open-weight model family developed by Essential AI and trained from scratch with a focus on programming, math, and scientific reasoning. The model demonstrates strong performance across multiple programming languages, tool-use workflows, and agentic execution environments (e.g., mini-SWE-agent). ', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.15, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.15, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 32768, 'remote', '2025-12-07', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('openrouter/bodybuilder', 'Body Builder (beta)', 'Transform your natural language requests into structured OpenRouter API request objects. Describe what you want to accomplish with AI models, and Body Builder will construct the appropriate API calls. Example: "count to 10 using gemini and opus."

This is useful for creating multi-model requests, custom model routers, or programmatic generation of API calls from human descriptions.

**BETA NOTICE**: Body Builder is in beta, and currently free. Pricing and functionality may change in the future.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', NULL, '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 128000, 'remote', '2025-12-05', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('amazon/nova-premier-v1', 'Nova Premier 1.0', 'Amazon Nova Premier is the most capable of Amazon’s multimodal models for complex reasoning tasks and for use as the best teacher for distilling custom models.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 2.5, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 12.5, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.625, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": true}', 1000000, 'remote', '2025-10-31', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('openai/gpt-5.1-codex-max', 'GPT-5.1-Codex-Max', 'GPT-5.1-Codex-Max is OpenAI’s latest agentic coding model, designed for long-running, high-context software development tasks. It is based on an updated version of the 5.1 reasoning stack and trained on agentic workflows spanning software engineering, mathematics, and research. 
GPT-5.1-Codex-Max delivers faster performance, improved reasoning, and higher token efficiency across the development lifecycle. ', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 1.25, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 10, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.125, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": true}', 400000, 'remote', '2025-12-04', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('amazon/nova-2-lite-v1', 'Nova 2 Lite', 'Nova 2 Lite is a fast, cost-effective reasoning model for everyday workloads that can process text, images, and videos to generate text. 

Nova 2 Lite demonstrates standout capabilities in processing documents, extracting information from videos, generating code, providing accurate grounded answers, and automating multi-step agentic workflows.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.3, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 2.5, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": true}', 1000000, 'remote', '2025-12-02', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('mistralai/ministral-14b-2512', 'Ministral 3 14B 2512', 'The largest model in the Ministral 3 family, Ministral 3 14B offers frontier capabilities and performance comparable to its larger Mistral Small 3.2 24B counterpart. A powerful and efficient language model with vision capabilities.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.2, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.2, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": true}', 262144, 'remote', '2025-12-02', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('mistralai/ministral-8b-2512', 'Ministral 3 8B 2512', 'A balanced model in the Ministral 3 family, Ministral 3 8B is a powerful, efficient tiny language model with vision capabilities.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.15, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.15, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": true}', 262144, 'remote', '2025-12-02', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('mistralai/ministral-3b-2512', 'Ministral 3 3B 2512', 'The smallest model in the Ministral 3 family, Ministral 3 3B is a powerful, efficient tiny language model with vision capabilities.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.1, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.1, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": true}', 131072, 'remote', '2025-12-02', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('mistralai/mistral-large-2512', 'Mistral Large 3 2512', 'Mistral Large 3 2512 is Mistral’s most capable model to date, featuring a sparse mixture-of-experts architecture with 41B active parameters (675B total), and released under the Apache 2.0 license.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.5, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 1.5, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": true}', 262144, 'remote', '2025-12-01', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('arcee-ai/trinity-mini:free', 'Trinity Mini (free)', 'Trinity Mini is a 26B-parameter (3B active) sparse mixture-of-experts language model featuring 128 experts with 8 active per token. Engineered for efficient reasoning over long contexts (131k) with robust function calling and multi-step agent workflows.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": true}', 131072, 'remote', '2025-12-01', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('arcee-ai/trinity-mini', 'Trinity Mini', 'Trinity Mini is a 26B-parameter (3B active) sparse mixture-of-experts language model featuring 128 experts with 8 active per token. Engineered for efficient reasoning over long contexts (131k) with robust function calling and multi-step agent workflows.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.045, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.15, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": true}', 131072, 'remote', '2025-12-01', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('deepseek/deepseek-v3.2-speciale', 'DeepSeek V3.2 Speciale', 'DeepSeek-V3.2-Speciale is a high-compute variant of DeepSeek-V3.2 optimized for maximum reasoning and agentic performance. It builds on DeepSeek Sparse Attention (DSA) for efficient long-context processing, then scales post-training reinforcement learning to push capability beyond the base model. Reported evaluations place Speciale ahead of GPT-5 on difficult reasoning workloads, with proficiency comparable to Gemini-3.0-Pro, while retaining strong coding and tool-use reliability. Like V3.2, it benefits from a large-scale agentic task synthesis pipeline that improves compliance and generalization in interactive environments.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.27, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.41, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": false}', 163840, 'remote', '2025-12-01', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('mistralai/mistral-7b-instruct-v0.1', 'Mistral 7B Instruct v0.1', 'A 7.3B parameter model that outperforms Llama 2 13B on all benchmarks, with optimizations for speed and context length.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.11, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.19, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 2824, 'remote', '2023-09-28', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('deepseek/deepseek-v3.2', 'DeepSeek V3.2', 'DeepSeek-V3.2 is a large language model designed to harmonize high computational efficiency with strong reasoning and agentic tool-use performance. It introduces DeepSeek Sparse Attention (DSA), a fine-grained sparse attention mechanism that reduces training and inference cost while preserving quality in long-context scenarios. A scalable reinforcement learning post-training framework further improves reasoning, with reported performance in the GPT-5 class, and the model has demonstrated gold-medal results on the 2025 IMO and IOI. V3.2 also uses a large-scale agentic task synthesis pipeline to better integrate reasoning into tool-use settings, boosting compliance and generalization in interactive environments.

Users can control the reasoning behaviour with the `reasoning` `enabled` boolean. [Learn more in our docs](https://openrouter.ai/docs/use-cases/reasoning-tokens#enable-reasoning-with-default-config)', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.25, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.38, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": true}', 163840, 'remote', '2025-12-01', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('prime-intellect/intellect-3', 'INTELLECT-3', 'INTELLECT-3 is a 106B-parameter Mixture-of-Experts model (12B active) post-trained from GLM-4.5-Air-Base using supervised fine-tuning (SFT) followed by large-scale reinforcement learning (RL). It offers state-of-the-art performance for its size across math, code, science, and general reasoning, consistently outperforming many larger frontier models. Designed for strong multi-step problem solving, it maintains high accuracy on structured tasks while remaining efficient at inference thanks to its MoE architecture.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.2, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 1.1, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": true}', 131072, 'remote', '2025-11-27', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('tngtech/tng-r1t-chimera:free', 'R1T Chimera (free)', 'TNG-R1T-Chimera is an experimental LLM with a faible for creative storytelling and character interaction. It is a derivate of the original TNG/DeepSeek-R1T-Chimera released in April 2025 and is available exclusively via Chutes and OpenRouter.

Characteristics and improvements include:

We think that it has a creative and pleasant personality.
It has a preliminary EQ-Bench3 value of about 1305.
It is quite a bit more intelligent than the original, albeit a slightly slower.
It is much more think-token consistent, i.e. reasoning and answer blocks are properly delineated.
Tool calling is much improved.

TNG Tech, the model authors, ask that users follow the careful guidelines that Microsoft has created for their "MAI-DS-R1" DeepSeek-based model. These guidelines are available on Hugging Face (https://huggingface.co/microsoft/MAI-DS-R1).', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": true}', 163840, 'remote', '2025-11-26', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('tngtech/tng-r1t-chimera', 'R1T Chimera', 'TNG-R1T-Chimera is an experimental LLM with a faible for creative storytelling and character interaction. It is a derivate of the original TNG/DeepSeek-R1T-Chimera released in April 2025 and is available exclusively via Chutes and OpenRouter.

Characteristics and improvements include:

We think that it has a creative and pleasant personality.
It has a preliminary EQ-Bench3 value of about 1305.
It is quite a bit more intelligent than the original, albeit a slightly slower.
It is much more think-token consistent, i.e. reasoning and answer blocks are properly delineated.
Tool calling is much improved.

TNG Tech, the model authors, ask that users follow the careful guidelines that Microsoft has created for their "MAI-DS-R1" DeepSeek-based model. These guidelines are available on Hugging Face (https://huggingface.co/microsoft/MAI-DS-R1).', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.25, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.85, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": true}', 163840, 'remote', '2025-11-26', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('anthropic/claude-opus-4.5', 'Claude Opus 4.5', 'Claude Opus 4.5 is Anthropic’s frontier reasoning model optimized for complex software engineering, agentic workflows, and long-horizon computer use. It offers strong multimodal capabilities, competitive performance across real-world coding and reasoning benchmarks, and improved robustness to prompt injection. The model is designed to operate efficiently across varied effort levels, enabling developers to trade off speed, depth, and token usage depending on task requirements. It comes with a new parameter to control token efficiency, which can be accessed using the OpenRouter Verbosity parameter with low, medium, or high.

Opus 4.5 supports advanced tool use, extended context management, and coordinated multi-agent setups, making it well-suited for autonomous research, debugging, multi-step planning, and spreadsheet/browser manipulation. It delivers substantial gains in structured reasoning, execution reliability, and alignment compared to prior Opus generations, while reducing token overhead and improving performance on long-running tasks.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 5, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 25, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.5, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheWrite", "rate": 6.25, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": true}', 200000, 'remote', '2025-11-24', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('allenai/olmo-3-32b-think', 'Olmo 3 32B Think', 'Olmo 3 32B Think is a large-scale, 32-billion-parameter model purpose-built for deep reasoning, complex logic chains and advanced instruction-following scenarios. Its capacity enables strong performance on demanding evaluation tasks and highly nuanced conversational reasoning. Developed by Ai2 under the Apache 2.0 license, Olmo 3 32B Think embodies the Olmo initiative’s commitment to openness, offering full transparency across weights, code and training methodology.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.15, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.5, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": false}', 65536, 'remote', '2025-11-21', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('allenai/olmo-3-7b-instruct', 'Olmo 3 7B Instruct', 'Olmo 3 7B Instruct is a supervised instruction-fine-tuned variant of the Olmo 3 7B base model, optimized for instruction-following, question-answering, and natural conversational dialogue. By leveraging high-quality instruction data and an open training pipeline, it delivers strong performance across everyday NLP tasks while remaining accessible and easy to integrate. Developed by Ai2 under the Apache 2.0 license, the model offers a transparent, community-friendly option for instruction-driven applications.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.1, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.2, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 65536, 'remote', '2025-11-21', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('allenai/olmo-3-7b-think', 'Olmo 3 7B Think', 'Olmo 3 7B Think is a research-oriented language model in the Olmo family designed for advanced reasoning and instruction-driven tasks. It excels at multi-step problem solving, logical inference, and maintaining coherent conversational context. Developed by Ai2 under the Apache 2.0 license, Olmo 3 7B Think supports transparent, fully open experimentation and provides a lightweight yet capable foundation for academic research and practical NLP workflows.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.12, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.2, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": false}', 65536, 'remote', '2025-11-21', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('google/gemini-3-pro-preview', 'Gemini 3 Pro Preview', 'Gemini 3 Pro is Google’s flagship frontier model for high-precision multimodal reasoning, combining strong performance across text, image, video, audio, and code with a 1M-token context window. Reasoning Details must be preserved when using multi-turn tool calling, see our docs here: https://openrouter.ai/docs/use-cases/reasoning-tokens#preserving-reasoning-blocks. It delivers state-of-the-art benchmark results in general reasoning, STEM problem solving, factual QA, and multimodal understanding, including leading scores on LMArena, GPQA Diamond, MathArena Apex, MMMU-Pro, and Video-MMMU. Interactions emphasize depth and interpretability: the model is designed to infer intent with minimal prompting and produce direct, insight-focused responses.

Built for advanced development and agentic workflows, Gemini 3 Pro provides robust tool-calling, long-horizon planning stability, and strong zero-shot generation for complex UI, visualization, and coding tasks. It excels at agentic coding (SWE-Bench Verified, Terminal-Bench 2.0), multimodal analysis, and structured long-form tasks such as research synthesis, planning, and interactive learning experiences. Suitable applications include autonomous agents, coding assistants, multimodal analytics, scientific reasoning, and high-context information processing.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 2, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 12, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.2, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheWrite", "rate": 0.375, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": true}', 1048576, 'remote', '2025-11-18', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('deepcogito/cogito-v2.1-671b', 'Cogito v2.1 671B', 'Cogito v2.1 671B MoE represents one of the strongest open models globally, matching performance of frontier closed and open models. This model is trained using self play with reinforcement learning to reach state-of-the-art performance on multiple categories (instruction following, coding, longer queries and creative writing). This advanced system demonstrates significant progress toward scalable superintelligence through policy improvement.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 1.25, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 1.25, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": false}', 128000, 'remote', '2025-11-13', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
