INSERT INTO public.ai_models VALUES ('cohere/command-a', 'Command A', 'Command A is an open-weights 111B parameter model with a 256k context window focused on delivering great performance across agentic, multilingual, and coding use cases.
Compared to other leading proprietary and open-weights models Command A delivers maximum performance with minimum hardware costs, excelling on business-critical agentic and multilingual tasks.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 2.5, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 10, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 256000, 'remote', '2025-03-13', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('openai/gpt-4o-mini-search-preview', 'GPT-4o-mini Search Preview', 'GPT-4o mini Search Preview is a specialized model for web search in Chat Completions. It is trained to understand and execute web search queries.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.15, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.6, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": true, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 128000, 'remote', '2025-03-12', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('openai/gpt-4o-search-preview', 'GPT-4o Search Preview', 'GPT-4o Search Previewis a specialized model for web search in Chat Completions. It is trained to understand and execute web search queries.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 2.5, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 10, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": true, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 128000, 'remote', '2025-03-12', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('google/gemma-3-27b-it:free', 'Gemma 3 27B (free)', 'Gemma 3 introduces multimodality, supporting vision-language input and text outputs. It handles context windows up to 128k tokens, understands over 140 languages, and offers improved math, reasoning, and chat capabilities, including structured outputs and function calling. Gemma 3 27B is Google''s latest open source model, successor to [Gemma 2](google/gemma-2-27b-it)', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": true}', 131072, 'remote', '2025-03-12', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('google/gemma-3-27b-it', 'Gemma 3 27B', 'Gemma 3 introduces multimodality, supporting vision-language input and text outputs. It handles context windows up to 128k tokens, understands over 140 languages, and offers improved math, reasoning, and chat capabilities, including structured outputs and function calling. Gemma 3 27B is Google''s latest open source model, successor to [Gemma 2](google/gemma-2-27b-it)', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.04, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.15, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": true}', 96000, 'remote', '2025-03-12', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('thedrummer/skyfall-36b-v2', 'Skyfall 36B V2', 'Skyfall 36B v2 is an enhanced iteration of Mistral Small 2501, specifically fine-tuned for improved creativity, nuanced writing, role-playing, and coherent storytelling.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.55, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.8, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 32768, 'remote', '2025-03-10', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('perplexity/sonar-reasoning-pro', 'Sonar Reasoning Pro', 'Note: Sonar Pro pricing includes Perplexity search pricing. See [details here](https://docs.perplexity.ai/guides/pricing#detailed-pricing-breakdown-for-sonar-reasoning-pro-and-sonar-pro)

Sonar Reasoning Pro is a premier reasoning model powered by DeepSeek R1 with Chain of Thought (CoT). Designed for advanced use cases, it supports in-depth, multi-step queries with a larger context window and can surface more citations per search, enabling more comprehensive and extensible responses.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 2, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 8, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": false}', 128000, 'remote', '2025-03-07', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('perplexity/sonar-pro', 'Sonar Pro', 'Note: Sonar Pro pricing includes Perplexity search pricing. See [details here](https://docs.perplexity.ai/guides/pricing#detailed-pricing-breakdown-for-sonar-reasoning-pro-and-sonar-pro)

For enterprises seeking more advanced capabilities, the Sonar Pro API can handle in-depth, multi-step queries with added extensibility, like double the number of citations per search as Sonar on average. Plus, with a larger context window, it can handle longer and more nuanced searches and follow-up questions. ', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 3, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 15, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": false}', 200000, 'remote', '2025-03-07', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('meta-llama/llama-guard-3-8b', 'Llama Guard 3 8B', 'Llama Guard 3 is a Llama-3.1-8B pretrained model, fine-tuned for content safety classification. Similar to previous versions, it can be used to classify content in both LLM inputs (prompt classification) and in LLM responses (response classification). It acts as an LLM – it generates text in its output that indicates whether a given prompt or response is safe or unsafe, and if unsafe, it also lists the content categories violated.

Llama Guard 3 was aligned to safeguard against the MLCommons standardized hazards taxonomy and designed to support Llama 3.1 capabilities. Specifically, it provides content moderation in 8 languages, and was optimized to support safety and security for search and code interpreter tool calls.
', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.02, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.06, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 131072, 'remote', '2025-02-12', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('perplexity/sonar-deep-research', 'Sonar Deep Research', 'Sonar Deep Research is a research-focused model designed for multi-step retrieval, synthesis, and reasoning across complex topics. It autonomously searches, reads, and evaluates sources, refining its approach as it gathers information. This enables comprehensive report generation across domains like finance, technology, health, and current events.

Notes on Pricing ([Source](https://docs.perplexity.ai/guides/pricing#detailed-pricing-breakdown-for-sonar-deep-research)) 
- Input tokens comprise of Prompt tokens (user prompt) + Citation tokens (these are processed tokens from running searches)
- Deep Research runs multiple searches to conduct exhaustive research. Searches are priced at $5/1000 searches. A request that does 30 searches will cost $0.15 in this step.
- Reasoning is a distinct step in Deep Research since it does extensive automated reasoning through all the material it gathers during its research phase. Reasoning tokens here are a bit different than the CoTs in the answer - these are tokens that we use to reason through the research material prior to generating the outputs via the CoTs. Reasoning tokens are priced at $3/1M tokens', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 2, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 8, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": false}', 128000, 'remote', '2025-03-07', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('qwen/qwq-32b', 'QwQ 32B', 'QwQ is the reasoning model of the Qwen series. Compared with conventional instruction-tuned models, QwQ, which is capable of thinking and reasoning, can achieve significantly enhanced performance in downstream tasks, especially hard problems. QwQ-32B is the medium-sized reasoning model, which is capable of achieving competitive performance against state-of-the-art reasoning models, e.g., DeepSeek-R1, o1-mini.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.15, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.4, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": true}', 32768, 'remote', '2025-03-05', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('google/gemini-2.0-flash-lite-001', 'Gemini 2.0 Flash Lite', 'Gemini 2.0 Flash Lite offers a significantly faster time to first token (TTFT) compared to [Gemini Flash 1.5](/google/gemini-flash-1.5), while maintaining quality on par with larger models like [Gemini Pro 1.5](/google/gemini-pro-1.5), all at extremely economical token prices.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.075, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.3, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": true}', 1048576, 'remote', '2025-02-25', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('anthropic/claude-3.7-sonnet:thinking', 'Claude 3.7 Sonnet (thinking)', 'Claude 3.7 Sonnet is an advanced large language model with improved reasoning, coding, and problem-solving capabilities. It introduces a hybrid reasoning approach, allowing users to choose between rapid responses and extended, step-by-step processing for complex tasks. The model demonstrates notable improvements in coding, particularly in front-end development and full-stack updates, and excels in agentic workflows, where it can autonomously navigate multi-step processes. 

Claude 3.7 Sonnet maintains performance parity with its predecessor in standard mode while offering an extended reasoning mode for enhanced accuracy in math, coding, and instruction-following tasks.

Read more at the [blog post here](https://www.anthropic.com/news/claude-3-7-sonnet)', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 3, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 15, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.3, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheWrite", "rate": 3.75, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": true}', 200000, 'remote', '2025-02-24', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('anthropic/claude-3.7-sonnet', 'Claude 3.7 Sonnet', 'Claude 3.7 Sonnet is an advanced large language model with improved reasoning, coding, and problem-solving capabilities. It introduces a hybrid reasoning approach, allowing users to choose between rapid responses and extended, step-by-step processing for complex tasks. The model demonstrates notable improvements in coding, particularly in front-end development and full-stack updates, and excels in agentic workflows, where it can autonomously navigate multi-step processes. 

Claude 3.7 Sonnet maintains performance parity with its predecessor in standard mode while offering an extended reasoning mode for enhanced accuracy in math, coding, and instruction-following tasks.

Read more at the [blog post here](https://www.anthropic.com/news/claude-3-7-sonnet)', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 3, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 15, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.3, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheWrite", "rate": 3.75, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": true}', 200000, 'remote', '2025-02-24', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('mistralai/mistral-saba', 'Saba', 'Mistral Saba is a 24B-parameter language model specifically designed for the Middle East and South Asia, delivering accurate and contextually relevant responses while maintaining efficient performance. Trained on curated regional datasets, it supports multiple Indian-origin languages—including Tamil and Malayalam—alongside Arabic. This makes it a versatile option for a range of regional and multilingual applications. Read more at the blog post [here](https://mistral.ai/en/news/mistral-saba)', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.2, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.6, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 32768, 'remote', '2025-02-17', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('veo-3.1-fast-generate-preview', 'Veo 3.1 fast', '', NULL, false, 'google', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', NULL, '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 8672, 'remote', NULL, '2026-01-28 05:58:29.484975+00', '2026-01-28 05:58:29.484975+00', '2026-01-28 05:58:29.474+00');
INSERT INTO public.ai_models VALUES ('gemini-2.5-flash-native-audio-latest', 'Gemini 2.5 Flash Native Audio Latest', '', NULL, false, 'google', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', NULL, '{}', NULL, '{"video": true, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": true}', 139264, 'remote', NULL, '2026-01-28 05:58:29.484975+00', '2026-01-28 05:58:29.484975+00', '2026-01-28 05:58:29.474+00');
INSERT INTO public.ai_models VALUES ('openai/o3-mini-high', 'o3 Mini High', 'OpenAI o3-mini-high is the same model as [o3-mini](/openai/o3-mini) with reasoning_effort set to high. 

o3-mini is a cost-efficient language model optimized for STEM reasoning tasks, particularly excelling in science, mathematics, and coding. The model features three adjustable reasoning effort levels and supports key developer capabilities including function calling, structured outputs, and streaming, though it does not include vision processing capabilities.

The model demonstrates significant improvements over its predecessor, with expert testers preferring its responses 56% of the time and noting a 39% reduction in major errors on complex questions. With medium reasoning effort settings, o3-mini matches the performance of the larger o1 model on challenging reasoning evaluations like AIME and GPQA, while maintaining lower latency and cost.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 1.1, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 4.4, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.55, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 200000, 'remote', '2025-02-12', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('google/gemini-2.0-flash-001', 'Gemini 2.0 Flash', 'Gemini Flash 2.0 offers a significantly faster time to first token (TTFT) compared to [Gemini Flash 1.5](/google/gemini-flash-1.5), while maintaining quality on par with larger models like [Gemini Pro 1.5](/google/gemini-pro-1.5). It introduces notable enhancements in multimodal understanding, coding capabilities, complex instruction following, and function calling. These advancements come together to deliver more seamless and robust agentic experiences.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.1, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.4, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.025, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheWrite", "rate": 0.083333, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": true}', 1048576, 'remote', '2025-02-05', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('qwen/qwen-vl-plus', 'Qwen VL Plus', 'Qwen''s Enhanced Large Visual Language Model. Significantly upgraded for detailed recognition capabilities and text recognition abilities, supporting ultra-high pixel resolutions up to millions of pixels and extreme aspect ratios for image input. It delivers significant performance across a broad range of visual tasks.
', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.21, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.63, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": false}', 7500, 'remote', '2025-02-05', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('aion-labs/aion-1.0', 'Aion-1.0', 'Aion-1.0 is a multi-model system designed for high performance across various tasks, including reasoning and coding. It is built on DeepSeek-R1, augmented with additional models and techniques such as Tree of Thoughts (ToT) and Mixture of Experts (MoE). It is Aion Lab''s most powerful reasoning model.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 4, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 8, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": false}', 131072, 'remote', '2025-02-04', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('aion-labs/aion-1.0-mini', 'Aion-1.0-Mini', 'Aion-1.0-Mini 32B parameter model is a distilled version of the DeepSeek-R1 model, designed for strong performance in reasoning domains such as mathematics, coding, and logic. It is a modified variant of a FuseAI model that outperforms R1-Distill-Qwen-32B and R1-Distill-Llama-70B, with benchmark results available on its [Hugging Face page](https://huggingface.co/FuseAI/FuseO1-DeepSeekR1-QwQ-SkyT1-32B-Preview), independently replicated for verification.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.7, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 1.4, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": false}', 131072, 'remote', '2025-02-04', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('aion-labs/aion-rp-llama-3.1-8b', 'Aion-RP 1.0 (8B)', 'Aion-RP-Llama-3.1-8B ranks the highest in the character evaluation portion of the RPBench-Auto benchmark, a roleplaying-specific variant of Arena-Hard-Auto, where LLMs evaluate each other’s responses. It is a fine-tuned base model rather than an instruct model, designed to produce more natural and varied writing.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.8, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 1.6, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 32768, 'remote', '2025-02-04', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('qwen/qwen-vl-max', 'Qwen VL Max', 'Qwen VL Max is a visual understanding model with 7500 tokens context length. It excels in delivering optimal performance for a broader spectrum of complex tasks.
', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.8, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 3.2, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": true}', 131072, 'remote', '2025-02-01', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('qwen/qwen-turbo', 'Qwen-Turbo', 'Qwen-Turbo, based on Qwen2.5, is a 1M context model that provides fast speed and low cost, suitable for simple tasks.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.05, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.2, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.02, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 1000000, 'remote', '2025-02-01', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('gemini-2.5-flash-native-audio-preview-09-2025', 'Gemini 2.5 Flash Native Audio Preview 09-2025', '', NULL, false, 'google', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', NULL, '{}', NULL, '{"video": true, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": true}', 139264, 'remote', NULL, '2026-01-28 05:58:29.484975+00', '2026-01-28 05:58:29.484975+00', '2026-01-28 05:58:29.474+00');
INSERT INTO public.ai_models VALUES ('qwen/qwen2.5-vl-72b-instruct', 'Qwen2.5 VL 72B Instruct', 'Qwen2.5-VL is proficient in recognizing common objects such as flowers, birds, fish, and insects. It is also highly capable of analyzing texts, charts, icons, graphics, and layouts within images.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.15, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.6, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": false}', 32768, 'remote', '2025-02-01', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('qwen/qwen-plus', 'Qwen-Plus', 'Qwen-Plus, based on the Qwen2.5 foundation model, is a 131K context model with a balanced performance, speed, and cost combination.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.4, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 1.2, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.16, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 131072, 'remote', '2025-02-01', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('qwen/qwen-max', 'Qwen-Max', 'Qwen-Max, based on Qwen2.5, provides the best inference performance among [Qwen models](/qwen), especially for complex multi-step tasks. It''s a large-scale MoE model that has been pretrained on over 20 trillion tokens and further post-trained with curated Supervised Fine-Tuning (SFT) and Reinforcement Learning from Human Feedback (RLHF) methodologies. The parameter count is unknown.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 1.6, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 6.4, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.64, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 32768, 'remote', '2025-02-01', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('openai/o3-mini', 'o3 Mini', 'OpenAI o3-mini is a cost-efficient language model optimized for STEM reasoning tasks, particularly excelling in science, mathematics, and coding.

This model supports the `reasoning_effort` parameter, which can be set to "high", "medium", or "low" to control the thinking time of the model. The default is "medium". OpenRouter also offers the model slug `openai/o3-mini-high` to default the parameter to "high".

The model features three adjustable reasoning effort levels and supports key developer capabilities including function calling, structured outputs, and streaming, though it does not include vision processing capabilities.

The model demonstrates significant improvements over its predecessor, with expert testers preferring its responses 56% of the time and noting a 39% reduction in major errors on complex questions. With medium reasoning effort settings, o3-mini matches the performance of the larger o1 model on challenging reasoning evaluations like AIME and GPQA, while maintaining lower latency and cost.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 1.1, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 4.4, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.55, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 200000, 'remote', '2025-01-31', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('mistralai/mistral-small-24b-instruct-2501', 'Mistral Small 3', 'Mistral Small 3 is a 24B-parameter language model optimized for low-latency performance across common AI tasks. Released under the Apache 2.0 license, it features both pre-trained and instruction-tuned versions designed for efficient local deployment.

The model achieves 81% accuracy on the MMLU benchmark and performs competitively with larger models like Llama 3.3 70B and Qwen 32B, while operating at three times the speed on equivalent hardware. [Read the blog post about the model here.](https://mistral.ai/news/mistral-small-3/)', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.03, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.11, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 32768, 'remote', '2025-01-30', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('deepseek/deepseek-r1-distill-qwen-32b', 'DeepSeek: R1 Distill Qwen 32B', 'DeepSeek R1 Distill Qwen 32B is a distilled large language model based on [Qwen 2.5 32B](https://huggingface.co/Qwen/Qwen2.5-32B), using outputs from [DeepSeek R1](/deepseek/deepseek-r1). It outperforms OpenAI''s o1-mini across various benchmarks, achieving new state-of-the-art results for dense models.\n\nOther benchmark results include:\n\n- AIME 2024 pass@1: 72.6\n- MATH-500 pass@1: 94.3\n- CodeForces Rating: 1691\n\nThe model leverages fine-tuning from DeepSeek R1''s outputs, enabling competitive performance comparable to larger frontier models.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.29, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.29, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": false}', 32768, 'remote', '2025-01-29', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('perplexity/sonar', 'Sonar', 'Sonar is lightweight, affordable, fast, and simple to use — now featuring citations and the ability to customize sources. It is designed for companies seeking to integrate lightweight question-and-answer features optimized for speed.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 1, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 1, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": false}', 127072, 'remote', '2025-01-27', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('deepseek/deepseek-r1-distill-llama-70b', 'DeepSeek: R1 Distill Llama 70B', 'DeepSeek R1 Distill Llama 70B is a distilled large language model based on [Llama-3.3-70B-Instruct](/meta-llama/llama-3.3-70b-instruct), using outputs from [DeepSeek R1](/deepseek/deepseek-r1). The model combines advanced distillation techniques to achieve high performance across multiple benchmarks, including:

- AIME 2024 pass@1: 70.0
- MATH-500 pass@1: 94.5
- CodeForces Rating: 1633

The model leverages fine-tuning from DeepSeek R1''s outputs, enabling competitive performance comparable to larger frontier models.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.03, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.11, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": true}', 131072, 'remote', '2025-01-23', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('deepseek/deepseek-r1', 'DeepSeek: R1', 'DeepSeek R1 is here: Performance on par with [OpenAI o1](/openai/o1), but open-sourced and with fully open reasoning tokens. It''s 671B parameters in size, with 37B active in an inference pass.

Fully open-source model & [technical report](https://api-docs.deepseek.com/news/news250120).

MIT licensed: Distill & commercialize freely!', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.7, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 2.5, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": true}', 64000, 'remote', '2025-01-20', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('minimax/minimax-01', 'MiniMax-01', 'MiniMax-01 is a combines MiniMax-Text-01 for text generation and MiniMax-VL-01 for image understanding. It has 456 billion parameters, with 45.9 billion parameters activated per inference, and can handle a context of up to 4 million tokens.

The text model adopts a hybrid architecture that combines Lightning Attention, Softmax Attention, and Mixture-of-Experts (MoE). The image model adopts the “ViT-MLP-LLM” framework and is trained on top of the text model.

To read more about the release, see: https://www.minimaxi.com/en/news/minimax-01-series-2', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.2, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 1.1, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": false}', 1000192, 'remote', '2025-01-15', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('microsoft/phi-4', 'Phi 4', '[Microsoft Research](/microsoft) Phi-4 is designed to perform well in complex reasoning tasks and can operate efficiently in situations with limited memory or where quick responses are needed. 

At 14 billion parameters, it was trained on a mix of high-quality synthetic datasets, data from curated websites, and academic materials. It has undergone careful improvement to follow instructions accurately and maintain strong safety standards. It works best with English language inputs.

For more information, please see [Phi-4 Technical Report](https://arxiv.org/pdf/2412.08905)
', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.06, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.14, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 16384, 'remote', '2025-01-10', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('sao10k/l3.1-70b-hanami-x1', 'Llama 3.1 70B Hanami x1', 'This is [Sao10K](/sao10k)''s experiment over [Euryale v2.2](/sao10k/l3.1-euryale-70b).', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 3, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 3, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 16000, 'remote', '2025-01-08', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('deepseek/deepseek-chat', 'DeepSeek V3', 'DeepSeek-V3 is the latest model from the DeepSeek team, building upon the instruction following and coding abilities of the previous versions. Pre-trained on nearly 15 trillion tokens, the reported evaluations reveal that the model outperforms other open-source models and rivals leading closed-source models.

For model details, please visit [the DeepSeek-V3 repo](https://github.com/deepseek-ai/DeepSeek-V3) for more information, or see the [launch announcement](https://api-docs.deepseek.com/news/news1226).', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.3, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 1.2, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 163840, 'remote', '2024-12-26', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('sao10k/l3.3-euryale-70b', 'Llama 3.3 Euryale 70B', 'Euryale L3.3 70B is a model focused on creative roleplay from [Sao10k](https://ko-fi.com/sao10k). It is the successor of [Euryale L3 70B v2.2](/models/sao10k/l3-euryale-70b).', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.65, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.75, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 131072, 'remote', '2024-12-18', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('openai/o1', 'o1', 'The latest and strongest model family from OpenAI, o1 is designed to spend more time thinking before responding. The o1 model series is trained with large-scale reinforcement learning to reason using chain of thought. 

The o1 models are optimized for math, science, programming, and other STEM-related tasks. They consistently exhibit PhD-level accuracy on benchmarks in physics, chemistry, and biology. Learn more in the [launch announcement](https://openai.com/o1).
', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 15, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 60, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 7.5, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": true}', 200000, 'remote', '2024-12-17', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('cohere/command-r7b-12-2024', 'Command R7B (12-2024)', 'Command R7B (12-2024) is a small, fast update of the Command R+ model, delivered in December 2024. It excels at RAG, tool use, agents, and similar tasks requiring complex reasoning and multiple steps.

Use of this model is subject to Cohere''s [Usage Policy](https://docs.cohere.com/docs/usage-policy) and [SaaS Agreement](https://cohere.com/saas-agreement).', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.0375, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.15, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 128000, 'remote', '2024-12-14', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('thedrummer/rocinante-12b', 'Rocinante 12B', 'Rocinante 12B is designed for engaging storytelling and rich prose.

Early testers have reported:
- Expanded vocabulary with unique and expressive word choices
- Enhanced creativity for vivid narratives
- Adventure-filled and captivating stories', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.17, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.43, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 32768, 'remote', '2024-09-30', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('google/gemini-2.0-flash-exp:free', 'Gemini 2.0 Flash Experimental (free)', 'Gemini Flash 2.0 offers a significantly faster time to first token (TTFT) compared to [Gemini Flash 1.5](/google/gemini-flash-1.5), while maintaining quality on par with larger models like [Gemini Pro 1.5](/google/gemini-pro-1.5). It introduces notable enhancements in multimodal understanding, coding capabilities, complex instruction following, and function calling. These advancements come together to deliver more seamless and robust agentic experiences.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": false, "imageOutput": false, "functionCall": true}', 1048576, 'remote', '2024-12-11', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('meta-llama/llama-3.3-70b-instruct:free', 'Llama 3.3 70B Instruct (free)', 'The Meta Llama 3.3 multilingual large language model (LLM) is a pretrained and instruction tuned generative model in 70B (text in/text out). The Llama 3.3 instruction tuned text only model is optimized for multilingual dialogue use cases and outperforms many of the available open source and closed chat models on common industry benchmarks.

Supported languages: English, German, French, Italian, Portuguese, Hindi, Spanish, and Thai.

[Model Card](https://github.com/meta-llama/llama-models/blob/main/models/llama3_3/MODEL_CARD.md)', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 131072, 'remote', '2024-12-06', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('meta-llama/llama-3.3-70b-instruct', 'Llama 3.3 70B Instruct', 'The Meta Llama 3.3 multilingual large language model (LLM) is a pretrained and instruction tuned generative model in 70B (text in/text out). The Llama 3.3 instruction tuned text only model is optimized for multilingual dialogue use cases and outperforms many of the available open source and closed chat models on common industry benchmarks.

