INSERT INTO public.ai_models VALUES ('google/gemma-2-27b-it', 'Gemma 2 27B', 'Gemma 2 27B by Google is an open model built from the same research and technology used to create the [Gemini models](/models?q=gemini).

Gemma models are well-suited for a variety of text generation tasks, including question answering, summarization, and reasoning.

See the [launch announcement](https://blog.google/technology/developers/google-gemma-2/) for more details. Usage of Gemma is subject to Google''s [Gemma Terms of Use](https://ai.google.dev/gemma/terms).', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0.65, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0.65, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": false}', 8192, 'remote', '2024-07-13', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
INSERT INTO public.ai_models VALUES ('google/gemma-2-9b-it', 'Gemma 2 9B', 'Gemma 2 9B by Google is an advanced, open-source language model that sets a new standard for efficiency and performance in its size class.

