INSERT INTO public.ai_models VALUES ('mistralai/mistral-large', 'Mistral Large', 'This is Mistral AI''s flagship model, Mistral Large 2 (version `mistral-large-2407`). It''s a proprietary weights-available model and excels at reasoning, code, JSON, chat, and more. Read the launch announcement [here](https://mistral.ai/news/mistral-large-2407/).

It supports dozens of languages including French, German, Spanish, Italian, Portuguese, Arabic, Hindi, Russian, Chinese, Japanese, and Korean, along with 80+ coding languages including Python, Java, C, C++, JavaScript, and Bash. Its long context window allows precise information recall from large documents.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 2, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 6, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 128000, 'remote', '2024-02-26', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
