INSERT INTO public.ai_models VALUES ('openai/gpt-3.5-turbo-16k', 'GPT-3.5 Turbo 16k', 'This model offers four times the context length of gpt-3.5-turbo, allowing it to support approximately 20 pages of text in a single request at a higher cost. Training data: up to Sep 2021.', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 3, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 4, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": false, "imageOutput": false, "functionCall": true}', 16385, 'remote', '2023-08-28', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.249579+00', '2026-01-26 16:41:26.231+00');
