INSERT INTO public.ai_models VALUES ('poolside/laguna-xs.2:free', 'Laguna XS.2 (free)', 'Laguna XS.2 is the second-generation model in the XS size class from [Poolside](https://poolside.ai), their efficient coding agent series. It combines tool calling and reasoning capabilities with a compact footprint, offering...', NULL, false, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 0, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": false, "reasoning": true, "imageOutput": false, "functionCall": true}', 131072, 'remote', '2026-04-28', '2026-04-29 08:38:10.879583+00', '2026-04-29 08:38:10.879583+00', '2026-04-29 08:38:10.846+00');
