INSERT INTO public.ai_models VALUES ('anthropic/claude-opus-4.6-fast', 'Claude Opus 4.6 (Fast)', 'Fast-mode variant of [Opus 4.6](/anthropic/claude-opus-4.6) - identical capabilities with higher output speed at premium 6x pricing.

Learn more in Anthropic''s docs: https://platform.claude.com/docs/en/build-with-claude/fast-mode', NULL, true, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 30, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 150, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 3, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheWrite", "rate": 37.5, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": true}', 1000000, 'remote', '2026-04-07', '2026-04-29 08:38:10.879583+00', '2026-04-29 08:38:10.879583+00', '2026-04-29 08:38:31.934+00');
INSERT INTO public.ai_models VALUES ('anthropic/claude-opus-4.6', 'Claude Opus 4.6', 'Opus 4.6 is Anthropic’s strongest model for coding and long-running professional tasks. It is built for agents that operate across entire workflows rather than single prompts, making it especially effective for large codebases, complex refactors, and multi-step debugging that unfolds over time. The model shows deeper contextual understanding, stronger problem decomposition, and greater reliability on hard engineering tasks than prior generations.

Beyond coding, Opus 4.6 excels at sustained knowledge work. It produces near-production-ready documents, plans, and analyses in a single pass, and maintains coherence across very long outputs and extended sessions. This makes it a strong default for tasks that require persistence, judgment, and follow-through, such as technical design, migration planning, and end-to-end project execution.

For users upgrading from earlier Opus versions, see our [official migration guide here](https://openrouter.ai/docs/guides/guides/model-migrations/claude-4-6-opus)
', NULL, true, 'openrouter', 'chat', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', '{"units": [{"name": "textInput", "rate": 5, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textOutput", "rate": 25, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheRead", "rate": 0.5, "unit": "millionTokens", "strategy": "fixed"}, {"name": "textInput_cacheWrite", "rate": 6.25, "unit": "millionTokens", "strategy": "fixed"}]}', '{}', NULL, '{"video": false, "search": false, "vision": true, "reasoning": true, "imageOutput": false, "functionCall": true}', 1000000, 'remote', '2026-02-04', '2026-02-11 07:32:57.223855+00', '2026-02-11 07:32:57.223855+00', '2026-04-29 08:38:39.153+00');
