INSERT INTO public.messages VALUES ('msg_HDO175bmMgRhTE', 'user', 'generate a diagram of this docker compose stack: 

```yaml
services: 
  casdoor: 
    image: casbin/casdoor:v2.13.0
    container_name: casdoor
    ports: 
      - "${CASDOOR_PORT:-47002}:8000" 
    depends_on: 
      postgres: 
        condition: service_healthy
    environment: 
      - RUNNING_IN_DOCKER=true
      - driverName=postgres
      - dataSourceName=user=postgres password=${POSTGRES_PASSWORD:-postgres} host=postgres port=5432 sslmode=disable dbname=casdoor
    volumes: 
      - ./config/init_data.json:/init_data.json:ro
      - ./config/casdoor-app.conf:/conf/app.conf:ro
    command: /bin/sh -c ''./server --createDatabase=true'' 
    restart: unless-stopped

  lobe-chat: 
    image: lobehub/lobe-chat-database
    container_name: lobe-chat
    ports: 
      - "${LOBECHAT_PORT:-47000}:3210" 
    volumes: 
      # HOTFIX: Patch MCP callTool to add session retry logic
      - ./patches/route.js:/app/.next/server/app/(backend)/trpc/tools/[trpc]/route.js:ro
    environment: 
      # App configuration
      - APP_URL=http://${HOST_DOMAIN:-localhost}:${LOBECHAT_PORT:-47000} 
      # Database configuration
      - DATABASE_URL=postgresql://postgres:${POSTGRES_PASSWORD:-postgres}@postgres:5432/lobechat
      # NextAuth SSO configuration
      - NEXT_AUTH_SSO_PROVIDERS=casdoor
      - NEXT_AUTH_SECRET=${NEXT_AUTH_SECRET} 
      - NEXTAUTH_URL=http://${HOST_DOMAIN:-localhost}:${LOBECHAT_PORT:-47000} 
      - AUTH_URL=http://${HOST_DOMAIN:-localhost}:${LOBECHAT_PORT:-47000} 
      # Casdoor configuration
      - AUTH_CASDOOR_ISSUER=http://${HOST_DOMAIN:-localhost}:${CASDOOR_PORT:-47002} 
      - AUTH_CASDOOR_ID=${AUTH_CASDOOR_ID} 
      - AUTH_CASDOOR_SECRET=${AUTH_CASDOOR_SECRET} 
      # Trust custom hostname for NextAuth
      - AUTH_TRUST_HOST=true
      # S3 Storage configuration
      - S3_ENDPOINT=http://${HOST_DOMAIN:-localhost}:${MINIO_PORT:-47005} 
      - S3_BUCKET=${S3_BUCKET:-lobe} 
      - S3_PUBLIC_DOMAIN=http://${HOST_DOMAIN:-localhost}:${MINIO_PORT:-47005} 
      - S3_ACCESS_KEY_ID=${MINIO_ROOT_USER:-minioadmin} 
      - S3_SECRET_ACCESS_KEY=${MINIO_ROOT_PASSWORD:-minioadmin} 
      - S3_ENABLE_PATH_STYLE=1
      - S3_SET_ACL=0
      # Key Vaults Secret
      - KEY_VAULTS_SECRET=${KEY_VAULTS_SECRET} 
      # OpenRouter integration
      - OPENROUTER_API_KEY=${OPENROUTER_API_KEY} 
      - ENABLED_OPENROUTER=1
      # OpenRouter as OpenAI-compatible endpoint (for embeddings) 
      - OPENAI_API_KEY=${OPENROUTER_API_KEY} 
      - OPENAI_PROXY_URL=https://openrouter.ai/api/v1
      # Embedding model configuration
      - DEFAULT_FILES_CONFIG=embedding_model=openai/text-embedding-3-small
      - LLM_VISION_IMAGE_USE_BASE64=1
    restart: unless-stopped
    depends_on: 
      postgres: 
        condition: service_healthy
      casdoor: 
        condition: service_started
      minio: 
        condition: service_healthy
      vllm: 
        condition: service_healthy

  mcphub: 
    build: 
      context: . 
      dockerfile: dockerfiles/mcphub.Dockerfile
    image: lobechat-aws-mcphub:latest
    container_name: mcphub
    ports: 
      - "${MCPHUB_PORT:-47008}:3000" 
    environment: 
      - SSH_HOST=${SSH_HOST} 
      - SSH_PORT=${SSH_PORT:-22} 
      - SSH_USERNAME=${SSH_USERNAME} 
      - SSH_PRIVATE_KEY_FILE=/app/ssh/id_rsa
      - SSH_ALLOWED_COMMANDS=${SSH_ALLOWED_COMMANDS} 
      - SSH_ALLOWED_PATHS=${SSH_ALLOWED_PATHS} 
      - SSH_COMMANDS_BLACKLIST=${SSH_COMMANDS_BLACKLIST} 
      - SSH_ARGUMENTS_BLACKLIST=${SSH_ARGUMENTS_BLACKLIST} 
      # AWS region config (credentials read from mounted ~/.aws) 
      - AWS_REGION=${AWS_REGION:-eu-west-1} 
      - AWS_DEFAULT_REGION=${AWS_DEFAULT_REGION:-eu-west-1} 
      # Notion MCP integration token (Bearer header) 
      - OPENAPI_MCP_HEADERS=${OPENAPI_MCP_HEADERS} 
    volumes: 
      - ./config/mcp_settings.json:/app/mcp_settings.json
      - ./data/mcphub:/app/data
      - ./config/ssh:/app/ssh:ro
      # AWS credentials - mounted so boto3 reads fresh creds without container restart
      - ~/.aws:/root/.aws:ro
      # Docker socket for MCP servers that use docker (aws-resources-operations) 
      - /var/run/docker.sock:/var/run/docker.sock
    restart: unless-stopped

  qdrant: 
    image: qdrant/qdrant:latest
    container_name: qdrant
    ports: 
      - "${QDRANT_PORT:-47010}:6333" 
      - "${QDRANT_GRPC_PORT:-47011}:6334" 
    volumes: 
      - ./data/qdrant:/qdrant/storage
    restart: unless-stopped
    healthcheck: 
      test: ["CMD-SHELL", "bash -c '':> /dev/tcp/127.0.0.1/6333'' || exit 1"] 
      interval: 30s
      timeout: 5s
      retries: 5

  hayhooks: 
    image: deepset/hayhooks:v1.1.0
    container_name: hayhooks
    ports: 
      - "${HAYHOOKS_PORT:-47012}:1416" 
    environment: 
      - HAYHOOKS_HOST=0.0.0.0
      - HAYHOOKS_PORT=1416
      - QDRANT_URL=http://qdrant:6333
    depends_on: 
      qdrant: 
        condition: service_healthy
    restart: unless-stopped

  hayhooks-mcp: 
    image: deepset/hayhooks:v1.1.0
    container_name: hayhooks-mcp
    ports: 
      - "${HAYHOOKS_MCP_PORT:-47013}:1417" 
    environment: 
      - QDRANT_URL=http://qdrant:6333
    entrypoint: ["sh","-c"] 
    command: ["pip install --no-cache-dir ''hayhooks[mcp]==1.1.0'' && exec hayhooks mcp run --host 0.0.0.0 --port 1417 --json-response"] 
    depends_on: 
      qdrant: 
        condition: service_healthy
    restart: unless-stopped

  vllm: 
    image: vllm/vllm-openai:gemma4
    container_name: vllm
    ports: 
      - "${VLLM_PORT:-47007}:8000" 
    environment: 
      - HUGGING_FACE_HUB_TOKEN=${HF_TOKEN} 
    volumes: 
      - ./data/huggingface:/root/.cache/huggingface
    command: >
      --model ${VLLM_MODEL_ID:-google/gemma-4-E4B-it} 
      --trust-remote-code
      --max-model-len 16384
      --dtype bfloat16
      --gpu-memory-utilization 0.9
      --enable-auto-tool-choice
      --tool-call-parser gemma4
      --reasoning-parser gemma4
    deploy: 
      resources: 
        reservations: 
          devices: 
            - driver: nvidia
              count: 1
              capabilities: [gpu] 
    restart: unless-stopped
    healthcheck: 
      test: ["CMD", "curl", "-f", "http://localhost:8000/health"] 
      interval: 30s
      timeout: 10s
      retries: 5
      start_period: 300s

  minio: 
    image: minio/minio:latest
    container_name: minio
    ports: 
      - "${MINIO_PORT:-47005}:9000"      # S3 API
      - "${MINIO_CONSOLE_PORT:-47006}:9001"      # MinIO Console
    volumes: 
      - ./data/minio:/data
    environment: 
      - MINIO_ROOT_USER=${MINIO_ROOT_USER:-minioadmin} 
      - MINIO_ROOT_PASSWORD=${MINIO_ROOT_PASSWORD:-minioadmin} 
      - MINIO_API_CORS_ALLOW_ORIGIN=http://${HOST_DOMAIN:-localhost}:${LOBECHAT_PORT:-47000} 
    command: server /data --console-address ":9001" 
    restart: unless-stopped
    healthcheck: 
      test: ["CMD", "mc", "ready", "local"] 
      interval: 10s
      timeout: 5s
      retries: 5


  postgres: 
    image: pgvector/pgvector:pg16
    container_name: shared-postgres
    ports: 
      - "${POSTGRES_PORT:-47003}:5432" 
    environment: 
      - POSTGRES_USER=postgres
      - POSTGRES_PASSWORD=${POSTGRES_PASSWORD:-postgres} 
      - POSTGRES_INITDB_ARGS=-E UTF8 --locale=C
    volumes: 
      - ./data/postgres:/var/lib/postgresql/data
      - ./config/init-postgres.sql:/docker-entrypoint-initdb.d/01-init.sql:ro
    healthcheck: 
      test: ["CMD-SHELL", "pg_isready -U postgres"] 
      interval: 10s
      timeout: 5s
      retries: 5
    restart: unless-stopped
    shm_size: 128mb

# All data is stored in host folders under ./data/ 
# No Docker volumes needed
``', NULL, NULL, false, NULL, NULL, NULL, NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', 'ssn_DiagMinio01', 'tpc_8wAmtHzpZHN0', NULL, NULL, NULL, '2026-04-29 11:10:11.673781+00', '2026-04-29 11:10:11.673781+00', NULL, '2026-04-29 11:10:11.673781+00', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.messages VALUES ('msg_WhKDFOur2oJfwH', 'user', 'ssh oriol@10.2.0.2 pwd', NULL, NULL, false, NULL, NULL, NULL, NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', 'ssn_9No96MYjOxve', 'tpc_chM8A2k1hERo', NULL, NULL, NULL, '2026-04-29 12:20:50.113292+00', '2026-04-29 12:20:50.113292+00', NULL, '2026-04-29 12:20:50.113292+00', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.messages VALUES ('msg_HW0ZHDPJxYinO6', 'tool', '"### Ran Playwright code\nawait page.goto(''https://oriolrius.me'');\n### Page\n- Page URL: https://oriolrius.me/\n- Page Title: oriolrius.me – Industria 4.0 con pasión\n### Snapshot\n```yaml\n- generic [active] [ref=e1]:\n  - link \"Skip to content\" [ref=e2] [cursor=pointer]:\n    - /url: \"#content\"\n  - banner [ref=e3]:\n    - banner [ref=e4]:\n      - generic [ref=e5]:\n        - link [ref=e10] [cursor=pointer]:\n          - /url: https://oriolrius.me\n        - generic [ref=e14]:\n          - navigation \"Menu\" [ref=e15]:\n            - list [ref=e16]:\n              - listitem [ref=e17]:\n                - link \"Home\" [ref=e18] [cursor=pointer]:\n                  - /url: https://oriolrius.me/\n              - listitem [ref=e19]:\n                - link \"Servicios\" [ref=e20] [cursor=pointer]:\n                  - /url: \"#\"\n                  - text: Servicios\n              - listitem [ref=e22]:\n                - link \"Eventos\" [ref=e23] [cursor=pointer]:\n                  - /url: https://oriolrius.me/eventos/\n              - listitem [ref=e24]:\n                - link \"Blog\" [ref=e25] [cursor=pointer]:\n                  - /url: https://oriolrius.me/blog-2/\n              - listitem [ref=e26]:\n                - link \"Sobre mi\" [ref=e27] [cursor=pointer]:\n                  - /url: https://oriolrius.me/sobre-mi/\n              - listitem [ref=e28]:\n                - link \"Contacto\" [ref=e29] [cursor=pointer]:\n                  - /url: https://oriolrius.me/contacto/\n          - text:  \n  - generic [ref=e34]:\n    - generic [ref=e39]:\n      - heading \"Consultor Industrial IoT (Industria 4.0)\" [level=2] [ref=e43]:\n        - text: Consultor Industrial IoT\n        - text: (Industria 4.0)\n      - heading \"¿Buscas un consultor de Industria 4.0? ¿Necesitas formación para afrontar la cuarta revolución industrial? ¿Buscas un ponente experto y apasionado para tu evento sobre Industria 4.0, Internet of Things, Cloud Computing o Ciberseguridad?\" [level=2] [ref=e46]:\n        - text: ¿Buscas un consultor de Industria 4.0?\n        - text: ¿Necesitas formación para afrontar la cuarta revolución industrial?\n        - text: ¿Buscas un ponente experto y apasionado para tu evento sobre Industria 4.0, Internet of Things, Cloud Computing o Ciberseguridad?\n    - heading \"Si has respondido que sí a alguna de estas preguntas, has llegado a la página adecuada.\" [level=2] [ref=e55]:\n      - text: Si has respondido que sí a alguna de estas preguntas,\n      - text: has llegado a la página adecuada.\n    - generic [ref=e61]:\n      - generic [ref=e66]: \n      - heading \"Únete a la lista de correo\" [level=4] [ref=e69]\n      - heading \"Y recibe un vídeo cada semana para seguir aprendiendo.\" [level=5] [ref=e72]\n      - generic [ref=e76]:\n        - text: Name\n        - textbox \"Name Name\" [ref=e77]\n        - text: Email\n        - textbox \"Email Email\" [ref=e78]\n        - paragraph [ref=e79]:\n          - checkbox [ref=e80]\n          - generic [ref=e81]:\n            - strong [ref=e82]: Marketing permission\n            - text: \": I give my consent to oriolrius.me to be in touch with me via email using the information I have provided in this form for the purpose of news, updates and marketing.\"\n            - strong [ref=e83]: What to expect\n            - text: \": If you wish to withdraw your consent and stop hearing from us, simply click the unsubscribe link at the bottom of every email we send or contact us at oriol+mailing@oriolrius.me. We value and respect your personal data and privacy. To view our privacy policy, please visit our website. By submitting this form, you agree that we may process your information in accordance with these terms.\"\n        - button \"Submit\" [ref=e84] [cursor=pointer]\n    - generic [ref=e92]:\n      - heading \"COMPARTIENDO CONOCIMIENTOS EXPERIENCIA Y CREATIVIDAD\" [level=2] [ref=e95]:\n        - text: COMPARTIENDO\n        - text: CONOCIMIENTOS\n        - text: EXPERIENCIA Y\n        - text: CREATIVIDAD\n      - heading \"Soy Oriol Rius especialista en Industria 4.0 pasión por la tecnología y las personas\" [level=2] [ref=e102]:\n        - text: Soy Oriol Rius\n        - text: especialista en Industria 4.0\n        - text: pasión por la tecnología y las personas\n    - generic [ref=e108]:\n      - heading \"Ya han confiado en mi...\" [level=2] [ref=e111]\n      - generic [ref=e117]:\n        - generic [ref=e121]:\n          - img \"vodafone\"\n        - generic [ref=e125]:\n          - img \"movistar\"\n        - generic [ref=e129]:\n          - img \"orange\"\n        - generic [ref=e133]:\n          - img \"andorra_telecom\"\n        - generic [ref=e137]:\n          - img \"pans-company\"\n        - generic [ref=e141]:\n          - img \"rocah\"\n        - generic [ref=e145]:\n          - img \"seat\"\n        - generic [ref=e149]:\n          - img \"nissan\"\n      - generic [ref=e151]:\n        - generic [ref=e155]:\n          - img \"mitsubishi\"\n        - generic [ref=e159]:\n          - img \"ricoh\"\n        - generic [ref=e163]:\n          - img \"schneider-electric\"\n        - generic [ref=e167]:\n          - img \"mediapro\"\n        - generic [ref=e171]:\n          - img \"eci\"\n        - generic [ref=e175]:\n          - img \"repsonl\"\n        - generic [ref=e179]:\n          - img \"grifols\"\n        - generic [ref=e183]:\n          - img \"ibm\"\n      - generic [ref=e185]:\n        - generic [ref=e189]:\n          - img \"celsa\"\n        - generic [ref=e193]:\n          - img \"gobierno_chile\"\n        - generic [ref=e205]:\n          - img \"dell\"\n        - generic [ref=e213]:\n          - img \"esade\"\n        - generic [ref=e217]:\n          - img \"comission_europea\"\n      - generic [ref=e219]:\n        - generic [ref=e223]:\n          - img \"diputacio_tarragona\"\n        - generic [ref=e231]:\n          - img \"barcelona_turisme\"\n        - generic [ref=e235]:\n          - img \"22atNetwork\"\n        - generic [ref=e243]:\n          - img \"bdt\"\n    - generic [ref=e251]:\n      - heading \"¿Qué dicen de mi?\" [level=4] [ref=e254]\n      - region \"Slides\" [ref=e266]:\n        - generic [ref=e267]:\n          - group \"1 / 11\" [ref=e268]:\n            - generic [ref=e269]:\n              - generic [ref=e271]: Oriol es una persona que considero básicamente brillante. Conecta muy rápidamente las necesidades y conceptos que se le plantean, dando una respuesta creativa, eficiente y puntual. Los retos parecen ser su motor y termina en breve siendo un experto en cualquier aspecto. Desde el primer momento nos sincronizamos para lanzar el mejor master en IoT para businesses. Un placer colaborar juntos y recomiendo 100% que podáis hacerlo, pues con él uno también crece.\n              - generic [ref=e272]:\n                - img \"Marta Riera\" [ref=e274]\n                - generic [ref=e275]:\n                  - generic [ref=e276]: Marta Riera\n                  - generic [ref=e277]: Zigurat\n          - group \"2 / 11\" [ref=e278]:\n            - generic [ref=e279]:\n              - generic [ref=e281]: Oriol es una persona honesta, moral y amigo con ideas frescas e innovadoras. Capaz de extraer la esencia de los procesos para simplificar y mejorar sobretodo, pero no sólo, en el ámbito de la tecnología y de la industria 4.0. Es un honor y un privilegio poder colaborar, aprender y trabajar con él.\n              - generic [ref=e282]:\n                - img \"Manuel Sabat\" [ref=e284]\n                - generic [ref=e285]:\n                  - generic [ref=e286]: Manuel Sabat\n                  - generic [ref=e287]: Lligats Metàl·lics S.L.\n          - group \"3 / 11\" [ref=e288]:\n            - generic [ref=e289]:\n              - generic [ref=e291]: \"Oriol me impresionó desde el minuto 1, lo describiría con las 3 Vs (o V al cubo): Vanguardista, Visionario y Valiente. Desde sus principios como white-hacker en seguridad hasta convertirse en emprendedor, y experto en el mundo del IoT.\"\n              - generic [ref=e292]:\n                - img \"Victor Paradell\" [ref=e294]\n                - generic [ref=e295]:\n                  - generic [ref=e296]: Victor Paradell\n                  - generic [ref=e297]: Ingram Micro\n          - group \"4 / 11\" [ref=e298]:\n            - generic [ref=e299]:\n              - generic [ref=e301]: Conozco a Oriol desde hace casi 15 años, nunca he conocido una persona tan determinada en resolver los retos tecnológicos de clientes. Dirigido por la energía de curiosidad, enfocado gracias a su visión de que la informática tiene que servir al negocio y las personas, y no al revés. Oriol es exigente, compromiso si, pero solo si viene bien preparado.\n              - generic [ref=e302]:\n                - img \"Julian Junge\" [ref=e304]\n                - generic [ref=e305]:\n                  - generic [ref=e306]: Julian Junge\n                  - generic [ref=e307]: Tech Data\n          - group \"5 / 11\" [ref=e308]:\n            - generic [ref=e309]:\n              - generic [ref=e311]: Oriol es una de las personas más brillantes con las que he tenido el placer de trabajar. Sistemático, dedicado y proactivo. Cuando unos empiezan a pensar en ir él ya vuelve. Pionero de internet y de la telemática en España, es de aquellas personas a las que en un ataque (hackers party) a uno le gustaría siempre tener de su lado y no en su contra… Contar con él en el equipo es victoria asegurada en cualquier batalla tecnológica, ¡por dura y completa que sea!\n              - generic [ref=e312]:\n                - img \"Dr. Andreu Veà\" [ref=e314]\n                - generic [ref=e315]:\n                  - generic [ref=e316]: Dr. Andreu Veà\n                  - generic [ref=e317]: Covid Warriors\n          - group \"6 / 11\" [ref=e318]:\n            - generic [ref=e319]:\n              - generic [ref=e321]: Cuando necesitas iniciar nuevos caminos o visualizar nuevas etapas dentro de ese camino hacia la transformación de una empresa industrial a los nuevos retos a que nos somete la revolución de la industria 4.0, necesitas acompañarte de socios que le pongan como mínimo la misma pasión que tu y te iluminen el camino pero también que te digan las cosas que no suele gustar escuchar en estas fases, además de aportarte toda su conocimiento y experiencia sin guardarse nada. Y esos atributos, que considero que son fundamentales en un buen socio, sin duda son los más destables que obtienes colaborando con Oriol.\n              - generic [ref=e322]:\n                - img \"Miguel Angel González\" [ref=e324]\n                - generic [ref=e325]:\n                  - generic [ref=e326]: Miguel Angel González\n                  - generic [ref=e327]: AKO\n          - group \"7 / 11\" [ref=e328]:\n            - generic [ref=e329]:\n              - generic [ref=e331]: Coincidir con Oriol ha sido siempre una experiencia más que enriquecedora. Recibir sus consejos me ha servido para abrir nuevas áreas de conocimiento, tanto en el ámbito técnico como de negocio. De hecho, muchas de las soluciones y estrategias que aplicamos actualmente en Inaudit han sido fruto de alguna de las conversaciones que hemos podido compartir.\n              - generic [ref=e332]:\n                - img \"Manolo Cruces\" [ref=e334]\n                - generic [ref=e335]:\n                  - generic [ref=e336]: Manolo Cruces\n                  - generic [ref=e337]: Inaudit\n          - group \"8 / 11\" [ref=e338]:\n            - generic [ref=e339]:\n              - generic [ref=e341]: Conocer a Oriol fue encontrar un aliado y una inspiración para afrontar y compartir la transformación digital. Su conocimiento y su capacidad para avanzar ayudan a ver más allá de los límites convencionales.\n              - generic [ref=e342]:\n                - img \"Miquel Carrión\" [ref=e344]\n                - generic [ref=e345]:\n                  - generic [ref=e346]: Miquel Carrión\n                  - generic [ref=e347]: Servei d''Ocupació de Catalunya\n          - group \"9 / 11\" [ref=e348]:\n            - generic [ref=e349]:\n              - generic [ref=e351]: Sin duda una de las mentes más brillantes que he conocido. Extremadamente eficaz cuando defines el objetivo a perseguir. Apasionado y locuaz.... No le dejes dominar la conversación o su lógica aplastante te \"con-vencerá\" cada vez.\n              - generic [ref=e352]:\n                - img \"Jaume Rey\" [ref=e354]\n                - generic [ref=e355]:\n                  - generic [ref=e356]: Jaume Rey\n                  - generic [ref=e357]: Nexiona\n          - group \"10 / 11\" [ref=e358]:\n            - generic [ref=e359]:\n              - generic [ref=e361]: No es muy habitual encontrar a un gran profesional como es el caso de Oriol, con criterio, valores y un gran conocimiento de sí mismo, facilitando el trabajo en equipo y el desarrollo de proyectos estratégicos. Nos entendimos desde el primer momento, incluso navegando en órbitas diferentes, pero siempre encontrando puntos de conexión. Si pienso en alianzas y futuro del trabajo. Oriol siempre está entre los mejores profesionales que conozco.\n              - generic [ref=e362]:\n                - img \"Iolanda Triviño\" [ref=e364]\n                - generic [ref=e365]:\n                  - generic [ref=e366]: Iolanda Triviño\n                  - generic [ref=e367]: 22@Network\n          - group \"11 / 11\" [ref=e368]:\n            - generic [ref=e369]:\n              - generic [ref=e371]: Oriol tiene un perfil muy completo. En las iniciativas en las que hemos colaborado, ha sido capaz de combinar la visión estratégica del proyecto con conocimiento técnico de mucha profundidad. Además, destacaría sus grandes habilidades comunicativas.\n              - generic [ref=e372]:\n                - img \"Jordi Arrufí\" [ref=e374]\n                - generic [ref=e375]:\n                  - generic [ref=e376]: Jordi Arrufí\n                  - generic [ref=e377]: Mobile World Capital\n        - generic [ref=e378]:\n          - button \"Go to slide 1\" [ref=e379] [cursor=pointer]\n          - button \"Go to slide 2\" [ref=e380] [cursor=pointer]\n          - button \"Go to slide 3\" [ref=e381] [cursor=pointer]\n          - button \"Go to slide 4\" [ref=e382] [cursor=pointer]\n          - button \"Go to slide 5\" [ref=e383] [cursor=pointer]\n          - button \"Go to slide 6\" [ref=e384] [cursor=pointer]\n          - button \"Go to slide 7\" [ref=e385] [cursor=pointer]\n          - button \"Go to slide 8\" [ref=e386] [cursor=pointer]\n          - button \"Go to slide 9\" [ref=e387] [cursor=pointer]\n          - button \"Go to slide 10\" [ref=e388] [cursor=pointer]\n    - generic [ref=e392]:\n      - heading \"¿Quién soy?\" [level=4] [ref=e395]\n      - generic [ref=e403]:\n        - generic [ref=e405]:\n          - paragraph [ref=e406]: En la era de la cuarta revolución industrial, se redefine el futuro del trabajo y las nuevas tecnologías junto a las personas. Estas son la clave real para el éxito de las empresas.\n          - paragraph [ref=e407]:\n            - strong [ref=e408]: El IoT, Cloud Computing, la ciberseguridad\n            - text: y hasta nueve tecnologías más son la base de esta revolución pero serán las personas las que marcaremos el ritmo de absorción de la revolución que estamos viviendo.\n          - paragraph [ref=e409]:\n            - text: Como\n            - strong [ref=e410]: consultor y mentor\n            - text: \", ayudo a empresas y altos directivos del ámbito del IT a transformar su trabajo en su vocación y a reinventarse utilizando metodologías ágiles.\"\n          - paragraph [ref=e411]: Después de crear varias empresas y de trabajar como técnico en el sector de la informática, he decidido compartir con otros empresarios y directivos todo lo que he aprendido hasta ahora del mundo empresarial.\n          - paragraph [ref=e412]:\n            - text: Como\n            - strong [ref=e413]: directivo de una empresa tecnológica\n            - text: \", es posible que sientas que te faltan conocimientos o experiencia ante la ola de nuevas tecnologías, metodologías y demandas de los nuevos talentos.\"\n          - paragraph [ref=e414]:\n            - text: Gracias a mis múltiples emprendimientos y a mi experiencia y formación en el sector digital, te ayudo a acortar las distancias entre la demanda real de la empresa y lo que se espera de ti. Recuerda los\n            - emphasis [ref=e415]: hardskills\n            - text: son tan importantes como los\n            - emphasis [ref=e416]: softskills\n            - text: .\n        - paragraph [ref=e419]: Reinventa tu negocio, desencalla tu proyecto y trabaja más feliz gracias a mi acompañamiento técnico y emprendedor.\n        - paragraph [ref=e422]:\n          - link \"Descubre más sobre quién soy\" [ref=e423] [cursor=pointer]:\n            - /url: https://oriolrius.me/sobre-mi/\n          - text: \", mi trayectoria y por qué puedo ayudarte a conseguir el equilibrio que buscas entre el trabajo y tu pasión.\"\n    - generic [ref=e428]:\n      - heading \"CHARLAS Y PONENCIAS\" [level=2] [ref=e431]\n      - paragraph [ref=e434]:\n        - text: Gracias a mi experiencia de más de 20 años en la Industria 4.0,\n        - strong [ref=e435]: mi aportación a tu evento puede ser interesante para otros compañeros y líderes del sector.\n        - text: Si buscas un\n        - strong [ref=e436]: experto en Cloud Computing, Ciberseguridad\n        - strong [ref=e437]: o Internet of Things (IoT)\n        - text: para tu próximo evento,\n        - strong [ref=e438]: Comerciales,\n        - strong [ref=e439]: directivos, managers y desarrolladores\n        - text: todos ellos se sentirán\n        - strong [ref=e440]: inspirados\n        - text: por las experiencias que les puedo compartir.\n      - link \"Más información\" [ref=e444] [cursor=pointer]:\n        - /url: https://oriolrius.me/charlas-y-ponencias/\n        - generic [ref=e446]: Más información\n      - paragraph [ref=e449]:\n        - text: ¿Aún no has visto mi charla en\n        - strong [ref=e450]: TEDx Alcoi\n        - text: \"? Te invito a verla\"\n        - link \"aquí\" [ref=e451] [cursor=pointer]:\n          - /url: https://www.youtube.com/watch?v=0nWvXjcxczs&list=PLbx6FpOnJm0CQA63NgCL7i5Cj3g_a_Qsw&index=8\n        - text: .\n    - generic [ref=e455]:\n      - heading \"CONSULTORÍAS Y MENTORÍAS\" [level=2] [ref=e458]\n      - generic [ref=e460]:\n        - paragraph [ref=e461]:\n          - text: Si tienes una\n          - strong [ref=e462]: startup, una pyme o si diriges una empresa consolidada\n          - text: pero no sabéis cómo lanzar vuestro producto o tenéis un problema que no podéis resolver, puedo ayudaros.\n        - paragraph [ref=e463]:\n          - text: Puede que necesites\n          - strong [ref=e464]: conocimientos técnicos\n          - text: (soluciones IoT para vuestra empresa, sistemas de Cloud Computing o ciberseguridad) o quizás buscas\n          - strong [ref=e465]: desarrollar tus habilidades de emprendeduría\n          - text: como parte indispensable de tu crecimiento personal.\n        - paragraph [ref=e466]:\n          - text: Como\n          - strong [ref=e467]: experto en metodologías ágiles como Lean Startup, Scrum y Kanban\n          - text: te ayudaré a poner claridad en tus procesos y a caminar sobre seguro.\n        - paragraph [ref=e468]:\n          - text: Sea cual sea tu caso,\n          - strong [ref=e469]: mi mentoría y consultoría especializada en la Industria 4.0 te ayudarán a ver más claro qué pasos tienes que seguir\n          - text: y cómo poner en práctica lo que vamos trabajando día a día.\n      - link \"Más información\" [ref=e473] [cursor=pointer]:\n        - /url: https://oriolrius.me/consultoria-y-mentoria/\n        - generic [ref=e475]: Más información\n    - generic [ref=e480]:\n      - heading \"TALLERES Y FORMACIÓN\" [level=2] [ref=e483]\n      - generic [ref=e485]:\n        - paragraph [ref=e486]:\n          - text: Si en tu empresa necesitáis una\n          - strong [ref=e487]: formación puntual sobre alguna de mis especialidades\n          - text: y quieres que comparta lo que sé con tu equipo, con tus alumnos o con tus directivos, agendemos una reunión y cuéntame más.\n        - paragraph [ref=e488]: \"Puedo ayudarte a ti y a tu equipo a mejorar vuestros conocimientos y a poner en práctica técnicas de:\"\n        - paragraph [ref=e489]:\n          - strong [ref=e490]: \"Industria 4.0:\"\n          - text: Cloud Computing, soluciones IoT para empresas y ciberseguridad\n          - strong [ref=e491]: Equipos sin oficina\n          - text: y trabajo a distancia, liderazgo, innovación y transformación digital\n          - text: Cómo aplicar\n          - strong [ref=e492]: metodologías agile\n          - text: (Lean Startup, Kanban, Scrum y Digital Product Management)\n          - strong [ref=e493]: \"Desarrollo de software:\"\n          - text: DevOps, software libre (Open Source)\n      - link \"Más información\" [ref=e497] [cursor=pointer]:\n        - /url: https://oriolrius.me/cursos-y-formaciones/\n        - generic [ref=e499]: Más información\n    - heading \"Dime como te puedo ayudar...\" [level=2] [ref=e506]\n    - generic [ref=e508]:\n      - generic [ref=e513]:\n        - generic [ref=e516]: \n        - generic [ref=e517]:\n          - heading \"¿Quieres descubrir todos mis servicios más a fondo?\" [level=3] [ref=e518]\n          - paragraph [ref=e519]:\n            - link \"Charlas y ponéncias\" [ref=e520] [cursor=pointer]:\n              - /url: https://oriolrius.me/charlas-y-ponencias/\n            - link \"Consultoría y mentoría\" [ref=e521] [cursor=pointer]:\n              - /url: https://oriolrius.me/consultoria-y-mentoria/\n            - link \"Cursos y formaciones\" [ref=e522] [cursor=pointer]:\n              - /url: https://oriolrius.me/cursos-y-formaciones/\n      - generic [ref=e524]:\n        - generic [ref=e527]:\n          - generic [ref=e530]: \n          - generic [ref=e531]:\n            - heading \"¿Quieres contarme tu caso?\" [level=3] [ref=e532]\n            - paragraph [ref=e533]: Escríbeme y buscaremos la mejor solución para ti.\n        - link \"Contacto\" [ref=e537] [cursor=pointer]:\n          - /url: https://oriolrius.me/contacto-el/\n          - generic [ref=e539]: Contacto\n      - generic [ref=e541]:\n        - generic [ref=e544]:\n          - generic [ref=e547]: \n          - generic [ref=e548]:\n            - heading \"¿No estás seguro de lo que necesitas?\" [level=3] [ref=e549]\n            - paragraph [ref=e550]: Agendemos una reunión y cuéntamelo todo para que te pueda recomendar la mejor opción para tu caso.\n        - link \"Agendar\" [ref=e554] [cursor=pointer]:\n          - /url: https://www.calendar.com/oriolrius/15''-meeting/\n          - generic [ref=e556]: Agendar\n    - text:  \n  - contentinfo [ref=e558]:\n    - generic [ref=e560]:\n      - generic [ref=e562]:\n        - heading \"Subscribe to my mailing list.\" [level=4] [ref=e565]\n        - paragraph [ref=e568]: \"Do you want to stay up to date with everything I do? Join now:\"\n        - generic [ref=e572]:\n          - text: Name\n          - textbox [ref=e573]\n          - text: Email\n          - textbox [ref=e574]\n          - paragraph [ref=e575]:\n            - checkbox [ref=e576]\n            - generic [ref=e577]:\n              - strong [ref=e578]: Marketing permission\n              - text: \": I give my consent to oriolrius.me to be in touch with me via email using the information I have provided in this form for the purpose of news, updates, and marketing.\"\n              - strong [ref=e579]: What to expect\n              - text: \": If you wish to withdraw your consent and stop hearing from us, simply click the unsubscribe link at the bottom of every email we send or contact us at oriol+mailing@oriolrius.me. We value and respect your personal data and privacy. To view our privacy policy, please visit our website. By submitting this form, you agree that we may process your information in accordance with these terms.\"\n          - button \"Submit\" [ref=e580] [cursor=pointer]\n      - generic [ref=e582]:\n        - heading \"Learn everything you need to know about Industry 4.0 for FREE!\" [level=4] [ref=e585]\n        - generic [ref=e587]:\n          - paragraph [ref=e588]:\n            - text: Join the\n            - link \"YMBI Telegram channel,\" [ref=e589] [cursor=pointer]:\n              - /url: https://url.joor.net/ymbi\n            - text: \"here’s the invitation:\"\n          - paragraph [ref=e590]:\n            - link \"https://url.joor.net/ymbi\" [ref=e591] [cursor=pointer]:\n              - /url: https://url.joor.net/ymbi\n      - generic [ref=e593]:\n        - heading \"Follow me on social media:\" [level=4] [ref=e596]\n        - list [ref=e599]:\n          - listitem [ref=e600]:\n            - link \"Linkedin\" [ref=e601] [cursor=pointer]:\n              - /url: https://www.linkedin.com/in/oriolrius\n              - generic [ref=e602]: Linkedin\n              - generic [ref=e603]: \n          - listitem [ref=e604]:\n            - link \"Youtube\" [ref=e605] [cursor=pointer]:\n              - /url: https://www.youtube.com/channel/UCxDVEpEH-ueEOD5xm4rHsgA\n              - generic [ref=e606]: Youtube\n              - generic [ref=e607]: \n          - listitem [ref=e608]:\n            - link \"Telegram\" [ref=e609] [cursor=pointer]:\n              - /url: https://url.joor.net/ymbi\n              - generic [ref=e610]: Telegram\n              - generic [ref=e611]: \n    - generic [ref=e615]:\n      - heading \"© 2026 - Oriol Rius\" [level=2] [ref=e618]\n      - heading \"Privacy Policy | Legal Notice\" [level=2] [ref=e621]:\n        - link \"Privacy Policy\" [ref=e622] [cursor=pointer]:\n          - /url: https://oriolrius.me/privacy-policy/\n        - text: \"|\"\n        - link \"Legal Notice\" [ref=e623] [cursor=pointer]:\n          - /url: https://oriolrius.me/aviso-legal/\n  - generic [ref=e624]: desktop\n```\n### Events\n- [ERROR] Mixed Content: The page at ''https://oriolr...must be served over HTTPS. @ https://oriolrius.me/:63\n- [ERROR] Mixed Content: The page at ''https://oriolr...must be served over HTTPS. @ https://oriolrius.me/:64\n- [ERROR] Mixed Content: The page at ''https://oriolr...must be served over HTTPS. @ https://oriolrius.me/:65\n- [LOG] JQMIGRATE: Migrate is installed, version 3.4...-includes/js/jquery/jquery-migrate.min.js?ver=3.4.1:1"', NULL, NULL, false, NULL, NULL, NULL, NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', 'ssn_Yq2wIsl3JSgC', 'tpc_a3UjiWXCGWwY', 'msg_ASH3LQZGawi5W4', NULL, NULL, '2026-01-27 10:20:56.879318+00', '2026-01-27 10:20:57.915+00', NULL, '2026-01-27 10:20:56.879318+00', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
