INSERT INTO public.message_plugins VALUES ('msg_dFncDUYJMN4xJm', 'toolu_vrtx_017Vrse4ZaLzgUc6t4MuXvo1', 'builtin', 'python', '{"packages": ["fastapi","uvicorn"], "code": "\nfrom fastapi import FastAPI\nimport asyncio\n\n# Create FastAPI instance\napp = FastAPI(\n    title=\"Hello World API\",\n    description=\"A simple Hello World API with FastAPI\",\n    version=\"1.0.0\"\n)\n\n@app.get(\"/\")\nasync def root():\n    \"\"\"\n    Root endpoint that returns a greeting message\n    \"\"\"\n    return {\"message\": \"Hello World from FastAPI!\"}\n\n@app.get(\"/hello/{name}\")\nasync def say_hello(name: str):\n    \"\"\"\n    Personalized greeting endpoint\n    \n    Args:\n        name (str): Name to greet\n        \n    Returns:\n        dict: Personalized greeting message\n    \"\"\"\n    return {\"message\": f\"Hello {name}!\"}\n\n@app.get(\"/health\")\nasync def health_check():\n    \"\"\"\n    Health check endpoint\n    \"\"\"\n    return {\"status\": \"healthy\", \"service\": \"FastAPI Hello World\"}\n\n# Test the endpoints directly\nprint(\"✅ FastAPI application created successfully!\")\nprint(\"\\n📋 Available endpoints:\")\nprint(\"  - GET /           : Root endpoint\")\nprint(\"  - GET /hello/{name} : Personalized greeting\")\nprint(\"  - GET /health     : Health check\")\n\n# Simulate endpoint calls\nprint(\"\\n🧪 Testing endpoints:\\n\")\n\n# Test root endpoint\nresult1 = await root()\nprint(f\"GET / → {result1}\")\n\n# Test personalized greeting\nresult2 = await say_hello(\"Developer\")\nprint(f\"GET /hello/Developer → {result2}\")\n\n# Test health check\nresult3 = await health_check()\nprint(f\"GET /health → {result3}\")\n\nprint(\"\\n✨ All endpoints working correctly!\")\nprint(\"\\n📝 To run this as a server, save the code to ''main.py'' and run:\")\nprint(\"   uv run uvicorn main:app --reload\")\nprint(\"   or\")\nprint(\"   uvicorn main:app --reload\")\n"}', 'lobe-code-interpreter', '{"error": {"name": "PythonError"}}', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', NULL);
INSERT INTO public.message_plugins VALUES ('msg_X7dMaUdNSYOfqR', 'toolu_016NLTqrxAKcquWybTijuJEx', 'builtin', 'python', '{"packages": ["fastapi","uvicorn"], "code": "\nfrom fastapi import FastAPI\nimport sys\n\n# Create FastAPI instance\napp = FastAPI(\n    title=\"Hello World API\",\n    description=\"A simple Hello World API with FastAPI\",\n    version=\"1.0.0\"\n)\n\n@app.get(\"/\")\nasync def root():\n    \"\"\"\n    Root endpoint that returns a greeting message\n    \"\"\"\n    return {\"message\": \"Hello World from FastAPI!\"}\n\n@app.get(\"/hello/{name}\")\nasync def say_hello(name: str):\n    \"\"\"\n    Personalized greeting endpoint\n    \n    Args:\n        name (str): Name to greet\n        \n    Returns:\n        dict: Personalized greeting message\n    \"\"\"\n    return {\"message\": f\"Hello {name}!\"}\n\n@app.get(\"/health\")\nasync def health_check():\n    \"\"\"\n    Health check endpoint\n    \"\"\"\n    return {\"status\": \"healthy\", \"service\": \"FastAPI Hello World\"}\n\n# Test the application structure\nprint(\"✅ FastAPI application created successfully!\")\nprint(f\"📦 FastAPI version: {FastAPI.__version__}\")\nprint(f\"🐍 Python version: {sys.version.split()[0]}\")\n\nprint(\"\\n📋 Available endpoints:\")\nfor route in app.routes:\n    if hasattr(route, ''methods''):\n        methods = '', ''.join(route.methods)\n        print(f\"  - {methods:6} {route.path:20} : {route.name}\")\n\nprint(\"\\n🧪 Testing endpoint functions directly (without async):\\n\")\n\n# Import asyncio to properly run async functions\nimport asyncio\n\n# Create an async function to test all endpoints\nasync def test_endpoints():\n    # Test root endpoint\n    result1 = await root()\n    print(f\"✓ GET / → {result1}\")\n    \n    # Test personalized greeting\n    result2 = await say_hello(\"Developer\")\n    print(f\"✓ GET /hello/Developer → {result2}\")\n    \n    # Test health check\n    result3 = await health_check()\n    print(f\"✓ GET /health → {result3}\")\n\n# Run the async tests\nasyncio.run(test_endpoints())\n\nprint(\"\\n✨ All endpoints working correctly!\")\nprint(\"\\n\" + \"=\"*60)\nprint(\"📝 NEXT STEPS - To run this as a real server:\")\nprint(\"=\"*60)\nprint(\"\\n1️⃣  Save this code to a file called ''main.py''\")\nprint(\"\\n2️⃣  Run the server using one of these commands:\")\nprint(\"    • With uv:\")\nprint(\"      uv run uvicorn main:app --reload\")\nprint(\"\\n    • With uvicorn directly:\")\nprint(\"      uvicorn main:app --reload\")\nprint(\"\\n3️⃣  Open your browser and visit:\")\nprint(\"    • http://127.0.0.1:8000\")\nprint(\"    • http://127.0.0.1:8000/docs (Interactive API docs)\")\nprint(\"    • http://127.0.0.1:8000/redoc (Alternative docs)\")\nprint(\"\\n\" + \"=\"*60)\n"}', 'lobe-code-interpreter', '{"error": {"name": "PythonError"}}', NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', NULL);
