INSERT INTO public.message_plugins VALUES ('msg_1MTWVudipNENyO', 'tool_mcphub-d2____d2-compile-d2____mcp_heTdwmsrmdBrpeWpBv1y', 'mcp', 'd2-compile-d2', '{"code":"direction: down\n\ntitle: Docker Compose Service Overview {\n  shape: text\n  near: top-center\n  style.font-size: 32\n  style.bold: true\n}\n\n# --- GROUPS ---\n\ngroup: Infrastructure {\n  direction: right\n  style.stroke-dash: 1\n  style.stroke: \"#8e44ad\"\n  \n  postgres: Postgres (pgvector)\n  minio: MinIO (S3)\n  qdrant: Qdrant (Vector DB)\n}\n\ngroup: Core Services {\n  direction: down\n  style.stroke-dash: 1\n  style.stroke: \"#27ae60\"\n  \n  lobe-chat: LobeChat App\n  mcphub: MCP Hub\n}\n\ngroup: Supporting Services {\n  direction: down\n  style.stroke-dash: 1\n  style.stroke: \"#f39c12\"\n  \n  casdoor: Casdoor (Auth/SSO)\n  vllm: VLLM (LLM Inference)\n}\n\ngroup: Hayhooks Services {\n  direction: down\n  style.stroke-dash: 1\n  style.stroke: \"#3498db\"\n  \n  hayhooks\n  hayhooks-mcp: Hayhooks MCP\n}\n\n# --- CONNECTIONS ---\n\n# LobeChat Dependencies\nlobe-chat -> postgres: DATABASE_URL (Postgres)\nlobe-chat -> casdoor: NEXT_AUTH_SSO_PROVIDERS=\"casdoor\"\nlobe-chat -> minio: S3 Config\nlobe-chat -> vllm: LLM/Embedding Endpoint\n\n# Auth Dependencies\ncasdoor -> postgres: Connects/Creates DB\n\n# Hayhooks Dependencies\nhayhooks -> qdrant: QDRANT_URL\nhayhooks-mcp -> qdrant: QDRANT_URL\n\n# MCP Hub Interactions (External/Host Focused)\nmcphub -> vllm: (Implied: Tool Calling/API)\nmcphub -> Infrastructure.postgres: (Implied: DB Access via Docker Socket or Config)\nmcphub -> SupportingServices.casdoor: (Implied: Agent/Tool Setup)\n\n# General Connections (Docker Compose Dependencies)\nlobe-chat -> vllm: depends_on (started)\nlobe-chat -> casdoor: depends_on (started)\nlobe-chat -> minio: depends_on (healthy)\nlobe-chat -> postgres: depends_on (healthy)\n\nhayhooks -> qdrant: depends_on (healthy)\nhayhooks-mcp -> qdrant: depends_on (healthy)\n\n# Explicit Environment Configuration Annotations\ncasdoor.note: Env: driverName=postgres\nvllm.note: Env: HF_TOKEN, via GPU\nminio.note: Port 9000/9001 Exposed\nmcphub.note: Mounts Docker.sock, ~/.aws, Volume: ./data/mcphub\nlobe-chat.note: Patches route.js\n|\n\ntitle: Docker Compose Service Overview {\n  shape: text\n  near: top-center\n  style.font-size: 32\n  style.bold: true\n}"}', 'mcphub-d2', NULL, NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', NULL);
INSERT INTO public.message_plugins VALUES ('msg_hDmYUC87IaqDZq', 'tool_mcphub-d2____d2-fetch_d2_cheat_sheet____mcp_OkVK2fWDMGCErg2GuY8k', 'mcp', 'd2-fetch_d2_cheat_sheet', '{}', 'mcphub-d2', NULL, NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', NULL);
INSERT INTO public.message_plugins VALUES ('msg_5VfvKP439OdOs7', 'tool_mcphub-d2____d2-compile-d2____mcp_rvVz3eHSgDHuOIxf4Qye', 'mcp', 'd2-compile-d2', '{"code":"direction: down\n\ntitle: Docker Compose Stack Diagram {\n  shape: text\n  near: top-center\n  style.font-size: 32\n  style.bold: true\n}\n\n# --- SHAPES ---\n\n# Application Layer\nlobe-chat: {\n  shape: rectangle\n  label: LobeChat App\n  style.fill: \"#a8e6cf\"\n}\nmcphub: {\n  shape: rectangle\n  label: MCP Hub\n  style.fill: \"#dcedc1\"\n}\n\n# Identity & Auth\ncasdoor: {\n  shape: diamond\n  label: Casdoor (Auth/SSO)\n  style.fill: \"#ff8b94\"\n}\n\n# Data Stores\npostgres: {\n  shape: cylinder\n  label: Postgres (pgvector)\n  style.fill: \"#a4c3b2\"\n}\nqdrant: {\n  shape: queue\n  label: Qdrant (Vector DB)\n  style.fill: \"#98d8c8\"\n}\nminio: {\n  shape: package\n  label: MinIO (S3 Storage)\n  style.fill: \"#c8e6c9\"\n}\n\n# Model/Inference\nvllm: {\n  shape: rectangle\n  label: VLLM (LLM Inference)\n  style.fill: \"#f2f2f2\"\n  style.stroke: \"#333\"\n}\n\n# Hayhooks Integrations\nhayhooks: {\n  shape: rectangle\n  label: Hayhooks (Standard)\n  style.fill: \"#ffcc5c\"\n}\nhayhooks-mcp: {\n  shape: rectangle\n  label: Hayhooks (MCP Mode)\n  style.fill: \"#ffc857\"\n}\n\n# --- GROUPS (Containers for visual segregation) ---\n\ngroup: Application_Layer {\n  style.stroke: \"#27ae60\"\n  style.stroke-dash: 2\n  style.3d: true\n  lobe-chat\n  mcphub\n \n  # Notes on App Layer\n  lobe-chat.note: |\n    - Configures SSO via Casdoor\n    - Connects to VLLM, MinIO, Postgres\n  | {near: bottom-left}\n  \n  mcphub.note: |\n    - Mounts /var/run/docker.sock\n    - Interface for MCP tools\n  | {near: bottom-right}\n}\n\ngroup: Identity_Auth {\n  style.stroke: \"#e74c3c\"\n  style.stroke-dash: 1\n  casdoor\n  \n  casdoor.note: |\n    - Relies on Postgres for user data\n    - Used by LobeChat for external auth\n  | {near: bottom}\n}\n\ngroup: Data_Storage {\n  style.stroke: \"#3498db\"\n  style.stroke-dash: 1\n  postgres\n  qdrant\n  minio\n  \n  postgres.note: Used by Casdoor, LobeChat, Qdrant\n}\n\ngroup: AI_Services {\n  style.stroke: \"#9b59b6\"\n  style.stroke-dash: 1\n  vllm\n  vllm.note: GPU Optimized (CUDA)\n}\n\ngroup: Integration_Adapters {\n  style.stroke: \"#f39c12\"\n  style.stroke-dash: 1\n  hayhooks\n  hayhooks-mcp\n  \n  hayhooks.note: Standard webhook service\n  hayhooks-mcp.note: Runs `hayhooks mcp run`\n}\n\n# --- DEPENDENCIES & FLOW ---\n\n# 1. Identity Flow\ncasdoor -> postgres: Reads/Writes User Data\n\n# 2. Core App Dependencies\nlobe-chat -> postgres: DATABASE_URL\nlobe-chat -> casdoor: AUTH_CASDOOR_ISSUER (SSO)\nlobe-chat -> minio: S3_ENDPOINT\nlobe-chat -> vllm: OpenAI Compatible API\n\n# 3. Vector DB Flow\nhayhooks -> qdrant: HTTP/gRPC\nhayhooks-mcp -> qdrant: HTTP/gRPC\n\n# 4. Wait Conditions (Service Health)\nlobe-chat -> postgres: depends_on(healthy)\nlobe-chat -> casdoor: depends_on(started)\nlobe-chat -> minio: depends_on(healthy)\nlobe-chat -> vllm: depends_on(healthy)\n\nhayhooks -> qdrant: depends_on(healthy)\nhayhooks-mcp -> qdrant: depends_on(healthy)\ncasdoor -> postgres: depends_on(service_healthy)\n\n# 5. Orchestrator/Adapters pointing to Core\nmcphub -> vllm: (Implied: Calls LLMs/Tools)\nmcphub -> hayhooks-mcp: (Implied: Orchestrates MCP commands)\n\n# Styling service connections based on role\nlobe-chat -> casdoor: Authenticates via {\n  target-arrowhead: {shape: diamond, style.filled: true}\n  style.stroke: \"#e74c3c\"\n  style.stroke-width: 2\n}\nlobe-chat -> vllm: Calls LLM {\n  target-arrowhead: {shape: arrow}\n  style.stroke: \"#9b59b6\"\n}\n\n# Data store access\nlobe-chat -> qdrant: (via LobeChat''s vector store if configured but not explicit here, Qdrant is only used by Hayhooks in the ENV list)\nlobe-chat -> postgres: Writes records\n\n# Hayhooks use of Qdrant\nhayhooks -> qdrant: Reads/Writes Vectors\nhayhooks-mcp -> qdrant: Reads/Writes Vectors {\n  style.stroke: \"#3498db\"\n  style.stroke-dash: 3\n}\n|\ncompile_result: ok"}', 'mcphub-d2', NULL, NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', NULL);
