INSERT INTO public.message_plugins VALUES ('msg_Sj990hcrAQkOmj', 'chatcmpl-tool-8ac4b091b9886dae', 'builtin', 'python', '{"code": "def say_hello(name: str) -> dict:\n    \"\"\"\n    Simulates the logic of the /hello/{name} endpoint.\n    \"\"\"\n    return {\"greeting\": f\"Hello, {name}! Thanks for using the API.\"}\n\n# Test case 1: Hello World\nresult_world = say_hello(\"world\")\nprint(f\"Test Case ''world'': {result_world}\")\n\n# Test case 2: Hello AI Specialist\nresult_ai = say_hello(\"AI Specialist\")\nprint(f\"Test Case ''AI Specialist'': {result_ai}\")", "packages": []}', 'lobe-code-interpreter', NULL, NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', NULL);
