INSERT INTO public.message_plugins VALUES ('msg_84K0l9VyigUD5F', 'call_95724500', 'mcp', 'aws-resources-operations-aws_resources_query_or_modify', '{"code_snippet":"import boto3\ncfn = boto3.client(''cloudformation'', region_name=''eu-west-1'')\nstack_id = ''arn:aws:cloudformation:eu-west-1:142333318038:stack/hello-world/51bb7460-fb8f-11f0-8713-066dbed0caa5''\nresponse = cfn.describe_stacks(StackName=stack_id)\nresult = response[''Stacks''][0][''Outputs''] if ''Stacks'' in response and response[''Stacks''] else []"}', 'mcphub-aws', NULL, NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', NULL);
