INSERT INTO public.message_plugins VALUES ('msg_fkLDgFCwxz4sER', 'call_92732577', 'mcp', 'aws-resources-operations-aws_resources_query_or_modify', '{"code_snippet":"import boto3\ncfn = boto3.client(''cloudformation'', region_name=''eu-west-1'')\ntry:\n    response = cfn.describe_stacks(StackName=''postgres-rds-stack'')\n    if ''Stacks'' in response and len(response[''Stacks'']) > 0:\n        stack = response[''Stacks''][0]\n        result = {\n            ''StackName'': stack[''StackName''],\n            ''StackStatus'': stack[''StackStatus''],\n            ''StackStatusReason'': stack.get(''StackStatusReason'', ''N/A''),\n            ''CreationTime'': str(stack[''CreationTime'']) if ''CreationTime'' in stack else ''N/A'',\n            ''LastUpdatedTime'': str(stack.get(''LastUpdatedTime'', ''N/A''))\n        }\n    else:\n        result = {''error'': ''No stack found with name postgres-rds-stack''}\nexcept Exception as e:\n    result = {''error'': str(e)}\nprint(result)"}', 'mcphub-aws', NULL, NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', NULL);
INSERT INTO public.message_plugins VALUES ('msg_JXLtKtRQB8Dpfx', 'call_09670806', 'mcp', 'aws-resources-operations-aws_resources_query_or_modify', '{"code_snippet":"import boto3\ncfn = boto3.client(''cloudformation'', region_name=''eu-west-1'')\ntry:\n    response = cfn.describe_stacks(StackName=''postgres-rds-stack'')\n    if ''Stacks'' in response and len(response[''Stacks'']) > 0:\n        stack = response[''Stacks''][0]\n        result = {\n            ''StackName'': stack[''StackName''],\n            ''StackStatus'': stack[''StackStatus''],\n            ''StackStatusReason'': stack.get(''StackStatusReason'', ''N/A''),\n            ''CreationTime'': str(stack[''CreationTime'']) if ''CreationTime'' in stack else ''N/A'',\n            ''LastUpdatedTime'': str(stack.get(''LastUpdatedTime'', ''N/A''))\n        }\n    else:\n        result = {''error'': ''No stack found with name postgres-rds-stack''}\nexcept Exception as e:\n    result = {''error'': str(e)}\nprint(result)"}', 'mcphub-aws', NULL, NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', NULL);
