INSERT INTO public.message_plugins VALUES ('msg_Ifcy7AcylTTs7R', 'tool_mcphub-d2____d2-compile-d2____mcp_bbgZ4iPmIRxx36QQaIVN', 'mcp', 'd2-compile-d2', '{"code":"direction: down\n\ntitle: Docker Compose Stack Diagram {\n  shape: text\n  near: top-center\n  style.font-size: 32\n  style.bold: true\n}\n\n# --- SHAPES ---\n\n# Application Layer\nlobe-chat: {\n  shape: rectangle\n  label: LobeChat App\n  style.fill: \"#a8e6cf\"\n}\nmcphub: {\n  shape: rectangle\n  label: MCP Hub\n  style.fill: \"#dcedc1\"\n}\n\n# Identity & Auth\ncasdoor: {\n  shape: diamond\n  label: Casdoor (Auth/SSO)\n  style.fill: \"#ff8b94\"\n}\n\n# Data Stores\npostgres: {\n  shape: cylinder\n  label: Postgres (pgvector)\n  style.fill: \"#a4c3b2\"\n}\nqdrant: {\n  shape: queue\n  label: Qdrant (Vector DB)\n  style.fill: \"#98d8c8\"\n}\nminio: {\n  shape: package\n  label: MinIO (S3 Storage)\n  style.fill: \"#c8e6c9\"\n}\n\n# Model/Inference\nvllm: {\n  shape: rectangle\n  label: VLLM (LLM Inference)\n  style.fill: \"#f2f2f2\"\n  style.stroke: \"#333\"\n}\n\n# Hayhooks Integrations\nhayhooks: {\n  shape: rectangle\n  label: Hayhooks (Standard)\n  style.fill: \"#ffcc5c\"\n}\nhayhooks-mcp: {\n  shape: rectangle\n  label: Hayhooks (MCP Mode)\n  style.fill: \"#ffc857\"\n}\n\n# --- GROUPS ---\n\ngroup: Application_Layer {\n  style.stroke: \"#27ae60\"\n  style.stroke-width: 2\n  \n  lobe-chat\n  mcphub\n \n  lobe-chat.tooltip: \"SSO via Casdoor; Connects to VLLM, MinIO, Postgres\"\n  mcphub.tooltip: \"Mounts docker.sock; Interface for MCP tools\"\n}\n\ngroup: Identity_Auth {\n  style.stroke: \"#e74c3c\"\n  style.stroke-width: 2\n  casdoor\n  \n  casdoor.tooltip: \"External Auth; Relies on Postgres\"\n}\n\ngroup: Data_Storage {\n  style.stroke: \"#3498db\"\n  style.stroke-width: 2\n  postgres\n  qdrant\n  minio\n  \n  postgres.tooltip: \"Used by Casdoor, LobeChat, Qdrant\"\n}\n\ngroup: AI_Services {\n  style.stroke: \"#9b59b6\"\n  style.stroke-width: 2\n  vllm\n  vllm.tooltip: \"GPU Optimized LLM Inference\"\n}\n\ngroup: Integration_Adapters {\n  style.stroke: \"#f39c12\"\n  style.stroke-width: 2\n  hayhooks\n  hayhooks-mcp\n  \n  hayhooks.tooltip: \"Standard webhook\"\n  hayhooks-mcp.tooltip: \"Runs `hayhooks mcp run`\"\n}\n\n# --- DEPENDENCIES & FLOW ---\n\n# Data Store Internal Dependencies\ncasdoor -> postgres: Connects to Auth DB\nhayhooks -> qdrant: Vector Access\nhayhooks-mcp -> qdrant: Vector Access\n\n# Application Dependencies (LobeChat)\nlobe-chat -> postgres: DATABASE_URL\nlobe-chat -> casdoor: AUTH_CASDOOR_ISSUER (SSO)\nlobe-chat -> minio: S3_ENDPOINT\nlobe-chat -> vllm: LLM/Embedding Endpoint\n\n# Key Data/Auth Flows (Using style blocks for properties)\nlobe-chat -> casdoor: Authenticates via SSO {\n  target-arrowhead: {shape: diamond, style.filled: true}\n  style.stroke: \"#e74c3c\"\n  style.stroke-width: 2\n}\nlobe-chat -> vllm: Calls LLM {\n  target-arrowhead: {shape: arrow}\n  style.stroke: \"#9b59b6\"\n  style.stroke-width: 2\n}\nlobe-chat -> postgres: Stores Data {\n  style.stroke: \"#1e8449\"\n}\n\n# Orchestration/Tooling flows\nmcphub -> hayhooks-mcp: Orchestrates MCP Tasks\nmcphub -> vllm: Tool Execution (Implied)\n\n# Service Dependencies (Conceptual Wait-for)\nlobe-chat -> postgres: waits for ready\nlobe-chat -> vllm: waits for ready\nhayhooks -> qdrant: waits for ready\ncasdoor -> postgres: waits for ready\n|\ncompile_result: ok"}', 'mcphub-d2', NULL, NULL, '4ee2c53f-bbd1-4a47-bb39-98f018730d41', NULL);
