INSERT INTO public.user_installed_plugins VALUES ('4ee2c53f-bbd1-4a47-bb39-98f018730d41', 'mcphub-playwright', 'customPlugin', '{"api": [{"name": "playwright-browser_close", "parameters": {"type": "object", "properties": {}, "additionalProperties": false}, "description": "Close the page"}, {"name": "playwright-browser_resize", "parameters": {"type": "object", "required": ["width", "height"], "properties": {"width": {"type": "number", "description": "Width of the browser window"}, "height": {"type": "number", "description": "Height of the browser window"}}, "additionalProperties": false}, "description": "Resize the browser window"}, {"name": "playwright-browser_console_messages", "parameters": {"type": "object", "required": ["level"], "properties": {"level": {"enum": ["error", "warning", "info", "debug"], "type": "string", "default": "info", "description": "Level of the console messages to return. Each level includes the messages of more severe levels. Defaults to \"info\"."}, "filename": {"type": "string", "description": "Filename to save the console messages to. If not provided, messages are returned as text."}}, "additionalProperties": false}, "description": "Returns all console messages"}, {"name": "playwright-browser_handle_dialog", "parameters": {"type": "object", "required": ["accept"], "properties": {"accept": {"type": "boolean", "description": "Whether to accept the dialog."}, "promptText": {"type": "string", "description": "The text of the prompt in case of a prompt dialog."}}, "additionalProperties": false}, "description": "Handle a dialog"}, {"name": "playwright-browser_evaluate", "parameters": {"type": "object", "required": ["function"], "properties": {"ref": {"type": "string", "description": "Exact target element reference from the page snapshot"}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}, "function": {"type": "string", "description": "() => { /* code */ } or (element) => { /* code */ } when element is provided"}}, "additionalProperties": false}, "description": "Evaluate JavaScript expression on page or element"}, {"name": "playwright-browser_file_upload", "parameters": {"type": "object", "properties": {"paths": {"type": "array", "items": {"type": "string"}, "description": "The absolute paths to the files to upload. Can be single file or multiple files. If omitted, file chooser is cancelled."}}, "additionalProperties": false}, "description": "Upload one or multiple files"}, {"name": "playwright-browser_fill_form", "parameters": {"type": "object", "required": ["fields"], "properties": {"fields": {"type": "array", "items": {"type": "object", "required": ["name", "type", "ref", "value"], "properties": {"ref": {"type": "string", "description": "Exact target field reference from the page snapshot"}, "name": {"type": "string", "description": "Human-readable field name"}, "type": {"enum": ["textbox", "checkbox", "radio", "combobox", "slider"], "type": "string", "description": "Type of the field"}, "value": {"type": "string", "description": "Value to fill in the field. If the field is a checkbox, the value should be `true` or `false`. If the field is a combobox, the value should be the text of the option."}}, "additionalProperties": false}, "description": "Fields to fill in"}}, "additionalProperties": false}, "description": "Fill multiple form fields"}, {"name": "playwright-browser_install", "parameters": {"type": "object", "properties": {}, "additionalProperties": false}, "description": "Install the browser specified in the config. Call this if you get an error about the browser not being installed."}, {"name": "playwright-browser_press_key", "parameters": {"type": "object", "required": ["key"], "properties": {"key": {"type": "string", "description": "Name of the key to press or a character to generate, such as `ArrowLeft` or `a`"}}, "additionalProperties": false}, "description": "Press a key on the keyboard"}, {"name": "playwright-browser_type", "parameters": {"type": "object", "required": ["ref", "text"], "properties": {"ref": {"type": "string", "description": "Exact target element reference from the page snapshot"}, "text": {"type": "string", "description": "Text to type into the element"}, "slowly": {"type": "boolean", "description": "Whether to type one character at a time. Useful for triggering key handlers in the page. By default entire text is filled in at once."}, "submit": {"type": "boolean", "description": "Whether to submit entered text (press Enter after)"}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}}, "additionalProperties": false}, "description": "Type text into editable element"}, {"name": "playwright-browser_navigate", "parameters": {"type": "object", "required": ["url"], "properties": {"url": {"type": "string", "description": "The URL to navigate to"}}, "additionalProperties": false}, "description": "Navigate to a URL"}, {"name": "playwright-browser_navigate_back", "parameters": {"type": "object", "properties": {}, "additionalProperties": false}, "description": "Go back to the previous page in the history"}, {"name": "playwright-browser_network_requests", "parameters": {"type": "object", "required": ["includeStatic"], "properties": {"filename": {"type": "string", "description": "Filename to save the network requests to. If not provided, requests are returned as text."}, "includeStatic": {"type": "boolean", "default": false, "description": "Whether to include successful static resources like images, fonts, scripts, etc. Defaults to false."}}, "additionalProperties": false}, "description": "Returns all network requests since loading the page"}, {"name": "playwright-browser_run_code", "parameters": {"type": "object", "required": ["code"], "properties": {"code": {"type": "string", "description": "A JavaScript function containing Playwright code to execute. It will be invoked with a single argument, page, which you can use for any page interaction. For example: `async (page) => { await page.getByRole(''button'', { name: ''Submit'' }).click(); return await page.title(); }`"}}, "additionalProperties": false}, "description": "Run Playwright code snippet"}, {"name": "playwright-browser_take_screenshot", "parameters": {"type": "object", "required": ["type"], "properties": {"ref": {"type": "string", "description": "Exact target element reference from the page snapshot. If not provided, the screenshot will be taken of viewport. If ref is provided, element must be provided too."}, "type": {"enum": ["png", "jpeg"], "type": "string", "default": "png", "description": "Image format for the screenshot. Default is png."}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to screenshot the element. If not provided, the screenshot will be taken of viewport. If element is provided, ref must be provided too."}, "filename": {"type": "string", "description": "File name to save the screenshot to. Defaults to `page-{timestamp}.{png|jpeg}` if not specified. Prefer relative file names to stay within the output directory."}, "fullPage": {"type": "boolean", "description": "When true, takes a screenshot of the full scrollable page, instead of the currently visible viewport. Cannot be used with element screenshots."}}, "additionalProperties": false}, "description": "Take a screenshot of the current page. You can''t perform actions based on the screenshot, use browser_snapshot for actions."}, {"name": "playwright-browser_snapshot", "parameters": {"type": "object", "properties": {"filename": {"type": "string", "description": "Save snapshot to markdown file instead of returning it in the response."}}, "additionalProperties": false}, "description": "Capture accessibility snapshot of the current page, this is better than screenshot"}, {"name": "playwright-browser_click", "parameters": {"type": "object", "required": ["ref"], "properties": {"ref": {"type": "string", "description": "Exact target element reference from the page snapshot"}, "button": {"enum": ["left", "right", "middle"], "type": "string", "description": "Button to click, defaults to left"}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}, "modifiers": {"type": "array", "items": {"enum": ["Alt", "Control", "ControlOrMeta", "Meta", "Shift"], "type": "string"}, "description": "Modifier keys to press"}, "doubleClick": {"type": "boolean", "description": "Whether to perform a double click instead of a single click"}}, "additionalProperties": false}, "description": "Perform click on a web page"}, {"name": "playwright-browser_drag", "parameters": {"type": "object", "required": ["startElement", "startRef", "endElement", "endRef"], "properties": {"endRef": {"type": "string", "description": "Exact target element reference from the page snapshot"}, "startRef": {"type": "string", "description": "Exact source element reference from the page snapshot"}, "endElement": {"type": "string", "description": "Human-readable target element description used to obtain the permission to interact with the element"}, "startElement": {"type": "string", "description": "Human-readable source element description used to obtain the permission to interact with the element"}}, "additionalProperties": false}, "description": "Perform drag and drop between two elements"}, {"name": "playwright-browser_hover", "parameters": {"type": "object", "required": ["ref"], "properties": {"ref": {"type": "string", "description": "Exact target element reference from the page snapshot"}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}}, "additionalProperties": false}, "description": "Hover over element on page"}, {"name": "playwright-browser_select_option", "parameters": {"type": "object", "required": ["ref", "values"], "properties": {"ref": {"type": "string", "description": "Exact target element reference from the page snapshot"}, "values": {"type": "array", "items": {"type": "string"}, "description": "Array of values to select in the dropdown. This can be a single value or multiple values."}, "element": {"type": "string", "description": "Human-readable element description used to obtain permission to interact with the element"}}, "additionalProperties": false}, "description": "Select an option in a dropdown"}, {"name": "playwright-browser_tabs", "parameters": {"type": "object", "required": ["action"], "properties": {"index": {"type": "number", "description": "Tab index, used for close/select. If omitted for close, current tab is closed."}, "action": {"enum": ["list", "new", "close", "select"], "type": "string", "description": "Operation to perform"}}, "additionalProperties": false}, "description": "List, create, close, or select a browser tab."}, {"name": "playwright-browser_wait_for", "parameters": {"type": "object", "properties": {"text": {"type": "string", "description": "The text to wait for"}, "time": {"type": "number", "description": "The time to wait in seconds"}, "textGone": {"type": "string", "description": "The text to wait for to disappear"}}, "additionalProperties": false}, "description": "Wait for text to appear or disappear or a specified time to pass"}], "meta": {"title": "mcphub-playwright", "avatar": "MCP_AVATAR", "description": "mcphub-playwright MCP server has 22 tools, like \"playwright-browser_close\""}, "type": "mcp", "identifier": "mcphub-playwright"}', NULL, '{"mcp": {"url": "http://mcphub:3000/mcp/playwright", "auth": {"type": "none"}, "type": "http"}}', '2026-01-27 09:04:05.669851+00', '2026-01-27 09:04:05.669851+00', '2026-01-27 09:04:05.669851+00');
INSERT INTO public.user_installed_plugins VALUES ('4ee2c53f-bbd1-4a47-bb39-98f018730d41', 'mcphub-fs', 'customPlugin', '{"api": [{"name": "filesystem-read_file", "parameters": {"type": "object", "required": ["path"], "properties": {"head": {"type": "number", "description": "If provided, returns only the first N lines of the file"}, "path": {"type": "string"}, "tail": {"type": "number", "description": "If provided, returns only the last N lines of the file"}}}, "description": "Read the complete contents of a file as text. DEPRECATED: Use read_text_file instead."}, {"name": "filesystem-read_text_file", "parameters": {"type": "object", "required": ["path"], "properties": {"head": {"type": "number", "description": "If provided, returns only the first N lines of the file"}, "path": {"type": "string"}, "tail": {"type": "number", "description": "If provided, returns only the last N lines of the file"}}}, "description": "Read the complete contents of a file from the file system as text. Handles various text encodings and provides detailed error messages if the file cannot be read. Use this tool when you need to examine the contents of a single file. Use the ''head'' parameter to read only the first N lines of a file, or the ''tail'' parameter to read only the last N lines of a file. Operates on the file as text regardless of extension. Only works within allowed directories."}, {"name": "filesystem-read_media_file", "parameters": {"type": "object", "required": ["path"], "properties": {"path": {"type": "string"}}}, "description": "Read an image or audio file. Returns the base64 encoded data and MIME type. Only works within allowed directories."}, {"name": "filesystem-read_multiple_files", "parameters": {"type": "object", "required": ["paths"], "properties": {"paths": {"type": "array", "items": {"type": "string"}, "minItems": 1, "description": "Array of file paths to read. Each path must be a string pointing to a valid file within allowed directories."}}}, "description": "Read the contents of multiple files simultaneously. This is more efficient than reading files one by one when you need to analyze or compare multiple files. Each file''s content is returned with its path as a reference. Failed reads for individual files won''t stop the entire operation. Only works within allowed directories."}, {"name": "filesystem-write_file", "parameters": {"type": "object", "required": ["path", "content"], "properties": {"path": {"type": "string"}, "content": {"type": "string"}}}, "description": "Create a new file or completely overwrite an existing file with new content. Use with caution as it will overwrite existing files without warning. Handles text content with proper encoding. Only works within allowed directories."}, {"name": "filesystem-edit_file", "parameters": {"type": "object", "required": ["path", "edits"], "properties": {"path": {"type": "string"}, "edits": {"type": "array", "items": {"type": "object", "required": ["oldText", "newText"], "properties": {"newText": {"type": "string", "description": "Text to replace with"}, "oldText": {"type": "string", "description": "Text to search for - must match exactly"}}}}, "dryRun": {"type": "boolean", "default": false, "description": "Preview changes using git-style diff format"}}}, "description": "Make line-based edits to a text file. Each edit replaces exact line sequences with new content. Returns a git-style diff showing the changes made. Only works within allowed directories."}, {"name": "filesystem-create_directory", "parameters": {"type": "object", "required": ["path"], "properties": {"path": {"type": "string"}}}, "description": "Create a new directory or ensure a directory exists. Can create multiple nested directories in one operation. If the directory already exists, this operation will succeed silently. Perfect for setting up directory structures for projects or ensuring required paths exist. Only works within allowed directories."}, {"name": "filesystem-list_directory", "parameters": {"type": "object", "required": ["path"], "properties": {"path": {"type": "string"}}}, "description": "Get a detailed listing of all files and directories in a specified path. Results clearly distinguish between files and directories with [FILE] and [DIR] prefixes. This tool is essential for understanding directory structure and finding specific files within a directory. Only works within allowed directories."}, {"name": "filesystem-list_directory_with_sizes", "parameters": {"type": "object", "required": ["path"], "properties": {"path": {"type": "string"}, "sortBy": {"enum": ["name", "size"], "type": "string", "default": "name", "description": "Sort entries by name or size"}}}, "description": "Get a detailed listing of all files and directories in a specified path, including sizes. Results clearly distinguish between files and directories with [FILE] and [DIR] prefixes. This tool is useful for understanding directory structure and finding specific files within a directory. Only works within allowed directories."}, {"name": "filesystem-directory_tree", "parameters": {"type": "object", "required": ["path"], "properties": {"path": {"type": "string"}, "excludePatterns": {"type": "array", "items": {"type": "string"}, "default": []}}}, "description": "Get a recursive tree view of files and directories as a JSON structure. Each entry includes ''name'', ''type'' (file/directory), and ''children'' for directories. Files have no children array, while directories always have a children array (which may be empty). The output is formatted with 2-space indentation for readability. Only works within allowed directories."}, {"name": "filesystem-move_file", "parameters": {"type": "object", "required": ["source", "destination"], "properties": {"source": {"type": "string"}, "destination": {"type": "string"}}}, "description": "Move or rename files and directories. Can move files between directories and rename them in a single operation. If the destination exists, the operation will fail. Works across different directories and can be used for simple renaming within the same directory. Both source and destination must be within allowed directories."}, {"name": "filesystem-search_files", "parameters": {"type": "object", "required": ["path", "pattern"], "properties": {"path": {"type": "string"}, "pattern": {"type": "string"}, "excludePatterns": {"type": "array", "items": {"type": "string"}, "default": []}}}, "description": "Recursively search for files and directories matching a pattern. The patterns should be glob-style patterns that match paths relative to the working directory. Use pattern like ''*.ext'' to match files in current directory, and ''**/*.ext'' to match files in all subdirectories. Returns full paths to all matching items. Great for finding files when you don''t know their exact location. Only searches within allowed directories."}, {"name": "filesystem-get_file_info", "parameters": {"type": "object", "required": ["path"], "properties": {"path": {"type": "string"}}}, "description": "Retrieve detailed metadata about a file or directory. Returns comprehensive information including size, creation time, last modified time, permissions, and type. This tool is perfect for understanding file characteristics without reading the actual content. Only works within allowed directories."}, {"name": "filesystem-list_allowed_directories", "parameters": {"type": "object", "properties": {}}, "description": "Returns the list of directories that this server is allowed to access. Subdirectories within these allowed directories are also accessible. Use this to understand which directories and their nested paths are available before trying to access files."}], "meta": {"title": "mcphub-fs", "avatar": "MCP_AVATAR", "description": "mcphub-fs MCP server has 14 tools, like \"filesystem-read_file\""}, "type": "mcp", "identifier": "mcphub-fs"}', NULL, '{"mcp": {"url": "http://mcphub:3000/mcp/filesystem", "auth": {"type": "none"}, "type": "http"}}', '2026-01-27 09:05:24.748277+00', '2026-01-27 09:05:24.748277+00', '2026-01-27 09:05:24.748277+00');
INSERT INTO public.user_installed_plugins VALUES ('4ee2c53f-bbd1-4a47-bb39-98f018730d41', 'mcphub-minio', 'customPlugin', '{"api": [{"name": "pickstar-2002-minio-mcp-connect_minio", "parameters": {"type": "object", "required": ["endPoint", "port", "accessKey", "secretKey"], "properties": {"port": {"type": "number", "description": "MinIO服务器端口"}, "region": {"type": "string", "description": "区域设置（可选）"}, "useSSL": {"type": "boolean", "default": false, "description": "是否使用SSL连接"}, "endPoint": {"type": "string", "description": "MinIO服务器地址"}, "accessKey": {"type": "string", "description": "访问密钥"}, "secretKey": {"type": "string", "description": "秘密密钥"}}}, "description": "连接到MinIO服务器"}, {"name": "pickstar-2002-minio-mcp-list_buckets", "parameters": {"type": "object", "properties": {}}, "description": "列出所有存储桶"}, {"name": "pickstar-2002-minio-mcp-create_bucket", "parameters": {"type": "object", "required": ["bucketName"], "properties": {"region": {"type": "string", "description": "区域设置（可选）"}, "bucketName": {"type": "string", "description": "存储桶名称"}}}, "description": "创建存储桶"}, {"name": "pickstar-2002-minio-mcp-delete_bucket", "parameters": {"type": "object", "required": ["bucketName"], "properties": {"bucketName": {"type": "string", "description": "存储桶名称"}}}, "description": "删除存储桶"}, {"name": "pickstar-2002-minio-mcp-bucket_exists", "parameters": {"type": "object", "required": ["bucketName"], "properties": {"bucketName": {"type": "string", "description": "存储桶名称"}}}, "description": "检查存储桶是否存在"}, {"name": "pickstar-2002-minio-mcp-list_objects", "parameters": {"type": "object", "required": ["bucketName"], "properties": {"prefix": {"type": "string", "description": "对象名前缀（可选）"}, "recursive": {"type": "boolean", "default": false, "description": "是否递归列出"}, "bucketName": {"type": "string", "description": "存储桶名称"}}}, "description": "列出存储桶中的对象"}, {"name": "pickstar-2002-minio-mcp-upload_file", "parameters": {"type": "object", "required": ["bucketName", "objectName", "filePath"], "properties": {"filePath": {"type": "string", "description": "本地文件路径"}, "metadata": {"type": "object", "description": "文件元数据（可选）"}, "bucketName": {"type": "string", "description": "存储桶名称"}, "objectName": {"type": "string", "description": "对象名称"}}}, "description": "上传文件到存储桶"}, {"name": "pickstar-2002-minio-mcp-download_file", "parameters": {"type": "object", "required": ["bucketName", "objectName", "filePath"], "properties": {"filePath": {"type": "string", "description": "本地保存路径"}, "bucketName": {"type": "string", "description": "存储桶名称"}, "objectName": {"type": "string", "description": "对象名称"}}}, "description": "从存储桶下载文件"}, {"name": "pickstar-2002-minio-mcp-delete_object", "parameters": {"type": "object", "required": ["bucketName", "objectName"], "properties": {"bucketName": {"type": "string", "description": "存储桶名称"}, "objectName": {"type": "string", "description": "对象名称"}}}, "description": "删除存储桶中的对象"}, {"name": "pickstar-2002-minio-mcp-delete_objects", "parameters": {"type": "object", "required": ["bucketName", "objectNames"], "properties": {"bucketName": {"type": "string", "description": "存储桶名称"}, "objectNames": {"type": "array", "items": {"type": "string"}, "description": "对象名称列表"}}}, "description": "批量删除存储桶中的对象"}, {"name": "pickstar-2002-minio-mcp-copy_object", "parameters": {"type": "object", "required": ["sourceBucket", "sourceObject", "destBucket", "destObject"], "properties": {"destBucket": {"type": "string", "description": "目标存储桶名称"}, "destObject": {"type": "string", "description": "目标对象名称"}, "sourceBucket": {"type": "string", "description": "源存储桶名称"}, "sourceObject": {"type": "string", "description": "源对象名称"}}}, "description": "复制对象"}, {"name": "pickstar-2002-minio-mcp-get_object_info", "parameters": {"type": "object", "required": ["bucketName", "objectName"], "properties": {"bucketName": {"type": "string", "description": "存储桶名称"}, "objectName": {"type": "string", "description": "对象名称"}}}, "description": "获取对象信息"}, {"name": "pickstar-2002-minio-mcp-generate_presigned_url", "parameters": {"type": "object", "required": ["bucketName", "objectName"], "properties": {"method": {"enum": ["GET", "PUT", "DELETE"], "type": "string", "default": "GET", "description": "HTTP方法"}, "expires": {"type": "number", "default": 3600, "description": "过期时间（秒）"}, "bucketName": {"type": "string", "description": "存储桶名称"}, "objectName": {"type": "string", "description": "对象名称"}}}, "description": "生成预签名URL"}, {"name": "pickstar-2002-minio-mcp-get_storage_stats", "parameters": {"type": "object", "properties": {}}, "description": "获取存储统计信息"}, {"name": "pickstar-2002-minio-mcp-upload_files", "parameters": {"type": "object", "required": ["bucketName", "files"], "properties": {"files": {"type": "array", "items": {"type": "object", "required": ["localPath", "objectName"], "properties": {"metadata": {"type": "object", "description": "文件元数据（可选）"}, "localPath": {"type": "string", "description": "本地文件路径"}, "objectName": {"type": "string", "description": "对象名称"}}}, "description": "文件列表"}, "bucketName": {"type": "string", "description": "存储桶名称"}}}, "description": "批量上传文件"}, {"name": "pickstar-2002-minio-mcp-download_files", "parameters": {"type": "object", "required": ["bucketName", "files"], "properties": {"files": {"type": "array", "items": {"type": "object", "required": ["objectName", "localPath"], "properties": {"localPath": {"type": "string", "description": "本地保存路径"}, "objectName": {"type": "string", "description": "对象名称"}}}, "description": "文件列表"}, "bucketName": {"type": "string", "description": "存储桶名称"}}}, "description": "批量下载文件"}, {"name": "pickstar-2002-minio-mcp-set_bucket_policy", "parameters": {"type": "object", "required": ["bucketName", "policy"], "properties": {"policy": {"type": "string", "description": "JSON格式的策略"}, "bucketName": {"type": "string", "description": "存储桶名称"}}}, "description": "设置存储桶策略"}, {"name": "pickstar-2002-minio-mcp-get_bucket_policy", "parameters": {"type": "object", "required": ["bucketName"], "properties": {"bucketName": {"type": "string", "description": "存储桶名称"}}}, "description": "获取存储桶策略"}, {"name": "pickstar-2002-minio-mcp-delete_bucket_policy", "parameters": {"type": "object", "required": ["bucketName"], "properties": {"bucketName": {"type": "string", "description": "存储桶名称"}}}, "description": "删除存储桶策略"}], "meta": {"title": "mcphub-minio", "avatar": "MCP_AVATAR", "description": "mcphub-minio MCP server has 19 tools, like \"pickstar-2002-minio-mcp-connect_minio\""}, "type": "mcp", "identifier": "mcphub-minio"}', NULL, '{"mcp": {"url": "http://mcphub:3000/mcp/pickstar-2002-minio-mcp", "auth": {"type": "none"}, "type": "http"}}', '2026-01-27 09:30:03.490933+00', '2026-01-27 09:30:03.490933+00', '2026-01-27 09:30:03.490933+00');
INSERT INTO public.user_installed_plugins VALUES ('4ee2c53f-bbd1-4a47-bb39-98f018730d41', 'mcphub-aws', 'customPlugin', '{"api": [{"name": "aws-resources-operations-aws_resources_query_or_modify", "parameters": {"type": "object", "required": ["code_snippet"], "properties": {"code_snippet": {"type": "string", "description": "Python code using boto3 to query or modify AWS resources. The code should have default execution setting variable named ''result''. Example code: ''result = boto3.client(''s3'').list_buckets()''"}}}, "description": "Execute a boto3 code snippet to query or modify AWS resources"}], "meta": {"title": "mcphub-aws", "avatar": "MCP_AVATAR", "description": "mcphub-aws MCP server has 1 tools, like \"aws-resources-operations-aws_resources_query_or_modify\""}, "type": "mcp", "identifier": "mcphub-aws"}', NULL, '{"mcp": {"url": "http://mcphub:3000/mcp/aws-resources-operations", "auth": {"type": "none"}, "type": "http"}}', '2026-01-27 14:50:09.338845+00', '2026-01-27 14:50:09.338845+00', '2026-01-27 14:50:09.338845+00');
INSERT INTO public.user_installed_plugins VALUES ('4ee2c53f-bbd1-4a47-bb39-98f018730d41', 'mcphub-haystack', 'customPlugin', '{"api": [{"name": "haystack-mcp-get_all_pipeline_statuses", "parameters": {"type": "object"}, "description": "Get the status of all pipelines and list available pipeline names."}, {"name": "haystack-mcp-get_pipeline_status", "parameters": {"type": "object", "required": ["pipeline_name"], "properties": {"pipeline_name": {"type": "string", "description": "Name of the pipeline"}}}, "description": "Get status of a specific pipeline."}, {"name": "haystack-mcp-undeploy_pipeline", "parameters": {"type": "object", "required": ["pipeline_name"], "properties": {"pipeline_name": {"type": "string", "description": "Name of the pipeline"}}}, "description": "Undeploy a pipeline. Removes a pipeline from the registry, its API routes, and deletes its files."}, {"name": "haystack-mcp-deploy_pipeline", "parameters": {"type": "object", "title": "PipelineFilesRequest", "examples": [{"name": "my_pipeline", "files": {"other_file.py": "{python code}", "other_file.txt": "{text content}", "pipeline_wrapper.py": "{python code}"}, "overwrite": false, "save_files": true}], "required": ["name", "files"], "properties": {"name": {"type": "string", "title": "Name", "description": "Name of the pipeline to deploy"}, "files": {"type": "object", "title": "Files", "examples": [{"requirements.txt": "pandas==1.3.5\nnumpy==1.21.0", "pipeline_wrapper.py": "from typing import Dict, Any\n\ndef process(data: Dict[str, Any]) -> Dict[str, Any]:\n    :# Your processing logic here\n    return data"}], "description": "Dictionary of files required for the pipeline, must include pipeline_wrapper.py", "additionalProperties": {"type": "string"}}, "overwrite": {"type": "boolean", "title": "Overwrite", "default": false, "description": "Whether to overwrite an existing pipeline with the same name"}, "save_files": {"type": "boolean", "title": "Save Files", "default": true, "description": "Whether to save the pipeline files to disk"}}, "description": "Request model for deploying a pipeline with a pipeline_wrapper.py and other files"}, "description": "Deploy a pipeline from files (pipeline_wrapper.py and other files)."}], "meta": {"title": "mcphub-haystack", "avatar": "MCP_AVATAR", "description": "mcphub-haystack MCP server has 4 tools"}, "type": "mcp", "identifier": "mcphub-haystack"}', NULL, '{"mcp": {"url": "http://mcphub:3000/mcp/haystack-mcp", "auth": {"type": "none"}, "type": "http"}}', '2026-04-29 09:43:02.40171+00', '2026-04-29 09:43:02.40171+00', '2026-04-29 09:43:02.40171+00');
INSERT INTO public.user_installed_plugins VALUES ('4ee2c53f-bbd1-4a47-bb39-98f018730d41', 'mcphub-aws-docs', 'customPlugin', '{"api": [{"name": "aws-documentation-read_documentation", "parameters": {"type": "object", "title": "read_documentationArguments", "required": ["url"], "properties": {"url": {"type": "string", "title": "Url", "description": "URL of the AWS documentation page to read"}, "max_length": {"type": "integer", "title": "Max Length", "default": 5000, "description": "Maximum number of characters to return.", "exclusiveMaximum": 1000000, "exclusiveMinimum": 0}, "start_index": {"type": "integer", "title": "Start Index", "default": 0, "minimum": 0, "description": "On return output starting at this character index, useful if a previous fetch was truncated and more content is required."}}}, "description": "Fetch and convert an AWS documentation page to markdown format.\n\n## Usage\n\nThis tool retrieves the content of an AWS documentation page and converts it to markdown format.\nFor long documents, you can make multiple calls with different start_index values to retrieve\nthe entire content in chunks.\n\n## URL Requirements\n\n- Must be from the docs.aws.amazon.com domain\n- Must end with .html\n\n## Example URLs\n\n- https://docs.aws.amazon.com/AmazonS3/latest/userguide/bucketnamingrules.html\n- https://docs.aws.amazon.com/lambda/latest/dg/lambda-invocation.html\n\n## Output Format\n\nThe output is formatted as markdown text with:\n- Preserved headings and structure\n- Code blocks for examples\n- Lists and tables converted to markdown format\n\n## Handling Long Documents\n\nIf the response indicates the document was truncated, you have several options:\n\n1. **Continue Reading**: Make another call with start_index set to the end of the previous response\n2. **Stop Early**: For very long documents (>30,000 characters), if you''ve already found the specific information needed, you can stop reading\n\nArgs:\n    ctx: MCP context for logging and error handling\n    url: URL of the AWS documentation page to read\n    max_length: Maximum number of characters to return\n    start_index: On return output starting at this character index\n\nReturns:\n    Markdown content of the AWS documentation\n"}, {"name": "aws-documentation-read_sections", "parameters": {"type": "object", "title": "read_sectionsArguments", "required": ["url", "section_titles"], "properties": {"url": {"type": "string", "title": "Url", "description": "URL of the AWS documentation page to read"}, "section_titles": {"type": "array", "items": {"type": "string"}, "title": "Section Titles", "description": "List of section titles to extract from the documentation"}}}, "description": "Extract specific sections from AWS documentation pages by title.\n\nRetrieves a page, converts to markdown, and returns only matching sections.\nSection matching is case-insensitive and handles whitespace differences.\n\n## URL Requirements\n- Must end with .html\n\n## Read Sections Tips\n\n- Use exact section titles from search results ''sections'' field when available\n- Section matching is case-insensitive and handles whitespace differences\n- Include multiple related sections in one call for comprehensive coverage\n\n## Example Usage\n\n```\n# If query is about S3 bucket naming rules:\n# Available sections: [''General purpose buckets naming rules'', ''Example general purpose bucket names'', ''Best practices'', ''Creating a bucket that uses a GUID in the bucket name'']\n# Read these specific sections:\nread_sections(\n    url=''https://docs.aws.amazon.com/s3/latest/userguide/bucketnamingrules.html'',\n    section_titles=[''General purpose buckets naming rules'', ''Best practices''],\n)\n\n# If query is about Python Lambda function examples:\n# Available sections: [''Example Python Lambda function code'', ''Handler naming conventions'', ''Using the Lambda event object'', ''Accessing and using the Lambda context object''. ''Valid handler signatures for Python handlers'', ''Returning a value'', ''Using the AWS SDK for Python (Boto3) in your handler'', ''Accessing environment variables, ''Code best practices for Python Lambda functions'']\n# Read these specific sections:\nread_sections(\n    url=''https://docs.aws.amazon.com/lambda/latest/dg/python-handler.html'',\n    section_titles=[\n        ''Example Python Lambda function code'',\n        ''Code best practices for Python Lambda functions'',\n    ],\n)\n```\n\nArgs:\n    ctx: MCP context for logging and error handling\n    url: URL of the AWS documentation page to read\n    section_titles: List of section titles to extract\n\nReturns:\n    Filtered markdown content containing only the requested sections\n"}, {"name": "aws-documentation-search_documentation", "parameters": {"type": "object", "title": "search_documentationArguments", "required": ["search_phrase"], "properties": {"limit": {"type": "integer", "title": "Limit", "default": 10, "maximum": 50, "minimum": 1, "description": "Maximum number of results to return"}, "guide_types": {"anyOf": [{"type": "array", "items": {"type": "string"}}, {"type": "null"}], "title": "Guide Types", "default": null, "description": "Filter results by guide type (e.g., [\"User Guide\", \"API Reference\", \"Developer Guide\"])"}, "product_types": {"anyOf": [{"type": "array", "items": {"type": "string"}}, {"type": "null"}], "title": "Product Types", "default": null, "description": "Filter results by AWS product/service (e.g., [\"Amazon Simple Storage Service\"])"}, "search_intent": {"type": "string", "title": "Search Intent", "default": "", "description": "For the search_phrase parameter, describe the search intent of the user. CRITICAL: Do not include any PII or customer data, describe only the AWS-related intent for search."}, "search_phrase": {"type": "string", "title": "Search Phrase", "description": "Search phrase to use"}}}, "description": "Search AWS documentation using the official AWS Documentation Search API.\n\n## Usage\n\nThis tool searches across all AWS documentation for pages matching your search phrase.\nUse it to find relevant documentation when you don''t have a specific URL.\n\n## Search Tips\n\n- Use specific technical terms rather than general phrases\n- Include service names to narrow results (e.g., \"S3 bucket versioning\" instead of just \"versioning\")\n- Use quotes for exact phrase matching (e.g., \"AWS Lambda function URLs\")\n- Include abbreviations and alternative terms to improve results\n- Use guide_type and product_type filters found from a SearchResponse''s \"facets\" property:\n    - Filter only for broad search queries with patterns:\n        - \"What is [service]?\" -> product_types: [\"Amazon Simple Storage Service\"]\n        - \"How to use <service 1> with <service 2>?\" -> product_types: [<service 1>, <service 2>]\n        - \"[service] getting started\" -> product_types: [<service>] + guide_types: [\"User Guide, \"Developer Guide\"]\n        - \"API reference for [service]\" -> product_types: [<service>] + guide_types: [\"API Reference\"]\n\n## Result Interpretation\n\nEach SearchResponse includes:\n- search_results: List of documentation pages, each with:\n    - rank_order: The relevance ranking (lower is more relevant)\n    - url: The documentation page URL\n    - title: The page title\n    - context: A brief excerpt or summary (if available)\n    - sections: Table of contents (when available) - these section titles can be used with the read_sections tool for targeted content extraction\n- facets: Available filters (product_types, guide_types) for refining searches\n- query_id: Unique identifier for this search session\n\n\nArgs:\n    ctx: MCP context for logging and error handling\n    search_phrase: Search phrase to use\n    search_intent: The intent behind the search requested by the user\n    limit: Maximum number of results to return\n    product_types: Filter by AWS product/service\n    guide_types: Filter by guide type\n\nReturns:\n    List of search results with URLs, titles, query ID, context snippets, and facets for filtering\n"}, {"name": "aws-documentation-recommend", "parameters": {"type": "object", "title": "recommendArguments", "required": ["url"], "properties": {"url": {"type": "string", "title": "Url", "description": "URL of the AWS documentation page to get recommendations for"}}}, "description": "Get content recommendations for an AWS documentation page.\n\n## Usage\n\nThis tool provides recommendations for related AWS documentation pages based on a given URL.\nUse it to discover additional relevant content that might not appear in search results.\n\n## Recommendation Types\n\nThe recommendations include four categories:\n\n1. **Highly Rated**: Popular pages within the same AWS service\n2. **New**: Recently added pages within the same AWS service - useful for finding newly released features\n3. **Similar**: Pages covering similar topics to the current page\n4. **Journey**: Pages commonly viewed next by other users\n\n## When to Use\n\n- After reading a documentation page to find related content\n- When exploring a new AWS service to discover important pages\n- To find alternative explanations of complex concepts\n- To discover the most popular pages for a service\n- To find newly released information by using a service''s welcome page URL and checking the **New** recommendations\n\n## Finding New Features\n\nTo find newly released information about a service:\n1. Find any page belong to that service, typically you can try the welcome page\n2. Call this tool with that URL\n3. Look specifically at the **New** recommendation type in the results\n\n## Result Interpretation\n\nEach recommendation includes:\n- url: The documentation page URL\n- title: The page title\n- context: A brief description (if available)\n\nArgs:\n    ctx: MCP context for logging and error handling\n    url: URL of the AWS documentation page to get recommendations for\n\nReturns:\n    List of recommended pages with URLs, titles, and context\n"}], "meta": {"title": "mcphub-aws-docs", "avatar": "MCP_AVATAR", "description": "mcphub-aws-docs MCP server has 4 tools"}, "type": "mcp", "identifier": "mcphub-aws-docs"}', NULL, '{"mcp": {"url": "http://mcphub:3000/mcp/aws-documentation", "auth": {"type": "none"}, "type": "http"}}', '2026-04-29 09:43:02.430759+00', '2026-04-29 09:43:02.430759+00', '2026-04-29 09:43:02.430759+00');
INSERT INTO public.user_installed_plugins VALUES ('4ee2c53f-bbd1-4a47-bb39-98f018730d41', 'WeatherGPT', 'plugin', '{"api": [{"name": "checkWeatherUsingGET", "parameters": {"type": "object", "required": ["location"], "properties": {"location": {"type": "string"}}}, "description": "Get current weather information"}], "meta": {"title": "WeatherGPT", "avatar": "https://openai-collections.chat-plugin.lobehub.com/weather-gpt/logo.webp", "description": "Get current weather information for a specific location."}, "type": "default", "openapi": "https://openai-collections.chat-plugin.lobehub.com/weather-gpt/openapi.json", "version": "1", "homepage": "https://weathergpt.vercel.app/legal", "settings": {"type": "object", "properties": {}}, "identifier": "WeatherGPT", "systemRole": "Use the WeatherGPT plugin to automatically fetch current weather information for a specific location when it''s being generated by the ChatGPT assistant. The plugin will return weather data, including temperature, wind speed, humidity, and other relevant information, as well as a link to a page that has all the information. Links will always be returned and should be shown to the user. The weather data can be used to provide users with up-to-date and accurate weather information for their desired location."}', NULL, NULL, '2026-01-27 05:24:56.028332+00', '2026-04-29 11:26:24.126+00', '2026-01-27 05:24:56.028332+00');
INSERT INTO public.user_installed_plugins VALUES ('4ee2c53f-bbd1-4a47-bb39-98f018730d41', 'mcphub-linux-sandbox', 'customPlugin', '{"api": [{"name": "linux-sandbox-get_config", "parameters": {"type": "object", "properties": {}, "additionalProperties": false}, "description": "\n                        Get the complete server configuration as JSON. Config includes fields for:\n                        - blockedCommands (array of blocked shell commands)\n                        - defaultShell (shell to use for commands)\n                        - allowedDirectories (paths the server can access)\n                        - fileReadLineLimit (max lines for read_file, default 1000)\n                        - fileWriteLineLimit (max lines per write_file call, default 50)\n                        - telemetryEnabled (boolean for telemetry opt-in/out)\n                        - currentClient (information about the currently connected MCP client)\n                        - clientHistory (history of all clients that have connected)\n                        - version (version of the DesktopCommander)\n                        - systemInfo (operating system and environment details)\n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-set_config_value", "parameters": {"type": "object", "required": ["key", "value"], "properties": {"key": {"type": "string"}, "value": {"anyOf": [{"type": "string"}, {"type": "number"}, {"type": "boolean"}, {"type": "array", "items": {"type": "string"}}, {"type": "null"}]}, "origin": {"enum": ["ui", "llm"], "type": "string"}}, "additionalProperties": false}, "description": "\n                        Set a specific configuration value by key.\n                        \n                        WARNING: Should be used in a separate chat from file operations and \n                        command execution to prevent security issues.\n                        \n                        Config keys include:\n                        - blockedCommands (array)\n                        - defaultShell (string)\n                        - allowedDirectories (array of paths)\n                        - fileReadLineLimit (number, max lines for read_file)\n                        - fileWriteLineLimit (number, max lines per write_file call)\n                        - telemetryEnabled (boolean)\n                        \n                        IMPORTANT: Setting allowedDirectories to an empty array ([]) allows full access \n                        to the entire file system, regardless of the operating system.\n                        \n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-read_file", "parameters": {"type": "object", "required": ["path"], "properties": {"path": {"type": "string"}, "isUrl": {"type": "boolean", "default": false}, "range": {"type": "string"}, "sheet": {"type": "string"}, "length": {"type": "number", "default": 1000}, "offset": {"type": "number", "default": 0}, "options": {"type": "object", "additionalProperties": {}}}, "additionalProperties": false}, "description": "\n                        Read contents from files and URLs.\n                        Read PDF files and extract content as markdown and images.\n                        \n                        Prefer this over ''execute_command'' with cat/type for viewing files.\n                        \n                        Supports partial file reading with:\n                        - ''offset'' (start line, default: 0)\n                          * Positive: Start from line N (0-based indexing)\n                          * Negative: Read last N lines from end (tail behavior)\n                        - ''length'' (max lines to read, default: configurable via ''fileReadLineLimit'' setting, initially 1000)\n                          * Used with positive offsets for range reading\n                          * Ignored when offset is negative (reads all requested tail lines)\n                        \n                        Examples:\n                        - offset: 0, length: 10     → First 10 lines\n                        - offset: 100, length: 5    → Lines 100-104\n                        - offset: -20               → Last 20 lines  \n                        - offset: -5, length: 10    → Last 5 lines (length ignored)\n                        \n                        Performance optimizations:\n                        - Large files with negative offsets use reverse reading for efficiency\n                        - Large files with deep positive offsets use byte estimation\n                        - Small files use fast readline streaming\n                        \n                        When reading from the file system, only works within allowed directories.\n                        Can fetch content from URLs when isUrl parameter is set to true\n                        (URLs are always read in full regardless of offset/length).\n                        \n                        FORMAT HANDLING (by extension):\n                        - Text: Uses offset/length for line-based pagination\n                        - Excel (.xlsx, .xls, .xlsm): Returns JSON 2D array\n                          * sheet: \"Sheet1\" (name) or \"0\" (index as string, 0-based)\n                          * range: ALWAYS use FROM:TO format (e.g., \"A1:D100\", \"C1:C1\", \"B2:B50\")\n                          * offset/length work as row pagination (optional fallback)\n                        - Images (PNG, JPEG, GIF, WebP): Base64 encoded viewable content\n                        - PDF: Extracts text content as markdown with page structure\n                          * offset/length work as page pagination (0-based)\n                          * Includes embedded images when available\n                        - DOCX (.docx): Two modes depending on parameters:\n                          * DEFAULT (no offset/length): Returns a text-bearing outline — shows paragraphs with text,\n                            tables with cell content, styles, image refs. Skips shapes/drawings/SVG noise.\n                            Each element shows its body index [0], [1], etc.\n                          * WITH offset/length: Returns raw pretty-printed XML with line pagination.\n                            Use this to drill into specific sections or see the actual XML for editing.\n                          * EDITING WORKFLOW: 1) read_file to get outline, 2) read_file with offset/length\n                            to see raw XML around what you want to edit, 3) edit_block with old_string/new_string\n                            using XML fragments copied from the read output.\n                          * IMPORTANT: offset MUST be non-zero to get raw XML (use offset=1 to start from line 1).\n                            offset=0 always returns the outline regardless of length.\n                          * For BULK changes (translation, mass replacements): use start_process with Python\n                            zipfile module to find/replace all <w:t> elements at once.\n\n                        IMPORTANT: Always use absolute paths for reliability. Paths are automatically normalized regardless of slash direction. \n\n🐳 DOCKER: Prefer paths within mounted directories: /home/ubuntu.\nWhen users ask about file locations, check these mounted paths first. Relative paths may fail as they depend on the current working directory. Tilde paths (~/...) might not work in all contexts. Unless the user explicitly asks for relative paths, use absolute paths.\n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-read_multiple_files", "parameters": {"type": "object", "required": ["paths"], "properties": {"paths": {"type": "array", "items": {"type": "string"}}}, "additionalProperties": false}, "description": "\n                        Read the contents of multiple files simultaneously.\n                        \n                        Each file''s content is returned with its path as a reference.\n                        Handles text files normally and renders images as viewable content.\n                        Recognized image types: PNG, JPEG, GIF, WebP.\n                        \n                        Failed reads for individual files won''t stop the entire operation.\n                        Only works within allowed directories.\n                        \n                        IMPORTANT: Always use absolute paths for reliability. Paths are automatically normalized regardless of slash direction. \n\n🐳 DOCKER: Prefer paths within mounted directories: /home/ubuntu.\nWhen users ask about file locations, check these mounted paths first. Relative paths may fail as they depend on the current working directory. Tilde paths (~/...) might not work in all contexts. Unless the user explicitly asks for relative paths, use absolute paths.\n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-write_file", "parameters": {"type": "object", "required": ["path", "content"], "properties": {"mode": {"enum": ["rewrite", "append"], "type": "string", "default": "rewrite"}, "path": {"type": "string"}, "content": {"type": "string"}}, "additionalProperties": false}, "description": "\n                        Write or append to file contents.\n\n                        IMPORTANT: DO NOT use this tool to create PDF files. Use ''write_pdf'' for all PDF creation tasks.\n                        DO NOT use this tool to edit DOCX files. Use ''edit_block'' with old_string/new_string instead.\n                        To CREATE a new DOCX, use write_file with .docx extension — text content with markdown headings (#, ##, ###) is converted to styled DOCX paragraphs.\n\n                        CHUNKING IS STANDARD PRACTICE: Always write files in chunks of 25-30 lines maximum.\n                        This is the normal, recommended way to write files - not an emergency measure.\n\n                        STANDARD PROCESS FOR ANY FILE:\n                        1. FIRST → write_file(filePath, firstChunk, {mode: ''rewrite''})  [≤30 lines]\n                        2. THEN → write_file(filePath, secondChunk, {mode: ''append''})   [≤30 lines]\n                        3. CONTINUE → write_file(filePath, nextChunk, {mode: ''append''}) [≤30 lines]\n\n                        ALWAYS CHUNK PROACTIVELY - don''t wait for performance warnings!\n\n                        WHEN TO CHUNK (always be proactive):\n                        1. Any file expected to be longer than 25-30 lines\n                        2. When writing multiple files in sequence\n                        3. When creating documentation, code files, or configuration files\n\n                        HANDLING CONTINUATION (\"Continue\" prompts):\n                        If user asks to \"Continue\" after an incomplete operation:\n                        1. Read the file to see what was successfully written\n                        2. Continue writing ONLY the remaining content using {mode: ''append''}\n                        3. Keep chunks to 25-30 lines each\n\n                        FORMAT HANDLING (by extension):\n                        - Text files: String content\n                        - Excel (.xlsx, .xls, .xlsm): JSON 2D array or {\"SheetName\": [[...]]}\n                          Example: ''[[\"Name\",\"Age\"],[\"Alice\",30]]''\n\n                        Files over 50 lines will generate performance notes but are still written successfully.\n                        Only works within allowed directories.\n\n                        IMPORTANT: Always use absolute paths for reliability. Paths are automatically normalized regardless of slash direction. \n\n🐳 DOCKER: Prefer paths within mounted directories: /home/ubuntu.\nWhen users ask about file locations, check these mounted paths first. Relative paths may fail as they depend on the current working directory. Tilde paths (~/...) might not work in all contexts. Unless the user explicitly asks for relative paths, use absolute paths.\n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-write_pdf", "parameters": {"type": "object", "required": ["path", "content"], "properties": {"path": {"type": "string"}, "content": {"anyOf": [{"type": "string"}, {"type": "array", "items": {"anyOf": [{"type": "object", "required": ["type", "pageIndex"], "properties": {"type": {"type": "string", "const": "insert"}, "markdown": {"type": "string"}, "pageIndex": {"type": "number"}, "pdfOptions": {"type": "object", "properties": {}, "additionalProperties": true}, "sourcePdfPath": {"type": "string"}}, "additionalProperties": false}, {"type": "object", "required": ["type", "pageIndexes"], "properties": {"type": {"type": "string", "const": "delete"}, "pageIndexes": {"type": "array", "items": {"type": "number"}}}, "additionalProperties": false}]}}]}, "options": {"type": "object", "properties": {}, "additionalProperties": true}, "outputPath": {"type": "string"}}, "additionalProperties": false}, "description": "\n                        Create a new PDF file or modify an existing one.\n\n                        THIS IS THE ONLY TOOL FOR CREATING AND MODIFYING PDF FILES.\n\n                        RULES ABOUT FILENAMES:\n                        - When creating a new PDF, ''outputPath'' MUST be provided and MUST use a new unique filename (e.g., \"result_01.pdf\", \"analysis_2025_01.pdf\", etc.).\n\n                        MODES:\n                        1. CREATE NEW PDF:\n                           - Pass a markdown string as ''content''.\n                           write_pdf(path=\"doc.pdf\", content=\"# Title\\n\\nBody text...\")\n\n                        2. MODIFY EXISTING PDF:\n                           - Pass array of operations as ''content''.\n                           - NEVER overwrite the original file.\n                           - ALWAYS provide a new filename in ''outputPath''.\n                           - After modifying, show original file path and new file path to user.\n\n                           write_pdf(path=\"doc.pdf\", content=[\n                               { type: \"delete\", pageIndexes: [0, 2] },\n                               { type: \"insert\", pageIndex: 1, markdown: \"# New Page\" }\n                           ])\n\n                        OPERATIONS:\n                        - delete: Remove pages by 0-based index.\n                          { type: \"delete\", pageIndexes: [0, 1, 5] }\n\n                        - insert: Add pages at a specific 0-based index.\n                          { type: \"insert\", pageIndex: 0, markdown: \"...\" }\n                          { type: \"insert\", pageIndex: 5, sourcePdfPath: \"/path/to/source.pdf\" }\n\n                        PAGE BREAKS:\n                        To force a page break, use this HTML element:\n                        <div style=\"page-break-before: always;\"></div>\n                        \n                        Example:\n                        \"# Page 1\\n\\n<div style=\\\"page-break-before: always;\\\"></div>\\n\\n# Page 2\"\n\n                        ADVANCED STYLING:\n                        HTML/CSS and inline SVG are supported for:\n                        - Text styling: colors, sizes, alignment, highlights\n                        - Boxes: borders, backgrounds, padding, rounded corners\n                        - SVG graphics: charts, diagrams, icons, shapes\n                        - Images: <img src=\"/absolute/path/image.jpg\" width=\"300\" /> or ![alt](/path/image.jpg)\n\n                        Supports standard markdown features including headers, lists, code blocks, tables, and basic formatting.\n\n                        Only works within allowed directories.\n\n                        IMPORTANT: Always use absolute paths for reliability. Paths are automatically normalized regardless of slash direction. \n\n🐳 DOCKER: Prefer paths within mounted directories: /home/ubuntu.\nWhen users ask about file locations, check these mounted paths first. Relative paths may fail as they depend on the current working directory. Tilde paths (~/...) might not work in all contexts. Unless the user explicitly asks for relative paths, use absolute paths.\n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-create_directory", "parameters": {"type": "object", "required": ["path"], "properties": {"path": {"type": "string"}}, "additionalProperties": false}, "description": "\n                        Create a new directory or ensure a directory exists.\n                        \n                        Can create multiple nested directories in one operation.\n                        Only works within allowed directories.\n                        \n                        IMPORTANT: Always use absolute paths for reliability. Paths are automatically normalized regardless of slash direction. \n\n🐳 DOCKER: Prefer paths within mounted directories: /home/ubuntu.\nWhen users ask about file locations, check these mounted paths first. Relative paths may fail as they depend on the current working directory. Tilde paths (~/...) might not work in all contexts. Unless the user explicitly asks for relative paths, use absolute paths.\n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-list_directory", "parameters": {"type": "object", "required": ["path"], "properties": {"path": {"type": "string"}, "depth": {"type": "number", "default": 2}}, "additionalProperties": false}, "description": "\n                        Get a detailed listing of all files and directories in a specified path.\n                        \n                        Use this instead of ''execute_command'' with ls/dir commands.\n                        Results distinguish between files and directories with [FILE] and [DIR] prefixes.\n                        \n                        Supports recursive listing with the ''depth'' parameter (default: 2):\n                        - depth=1: Only direct contents of the directory\n                        - depth=2: Contents plus one level of subdirectories\n                        - depth=3+: Multiple levels deep\n                        \n                        CONTEXT OVERFLOW PROTECTION:\n                        - Top-level directory shows ALL items\n                        - Nested directories are limited to 100 items maximum per directory\n                        - When a nested directory has more than 100 items, you''ll see a warning like:\n                          [WARNING] node_modules: 500 items hidden (showing first 100 of 600 total)\n                        - This prevents overwhelming the context with large directories like node_modules\n                        \n                        Results show full relative paths from the root directory being listed.\n                        Example output with depth=2:\n                        [DIR] src\n                        [FILE] src/index.ts\n                        [DIR] src/tools\n                        [FILE] src/tools/filesystem.ts\n                        \n                        If a directory cannot be accessed, it will show [DENIED] instead.\n                        Only works within allowed directories.\n                        \n                        IMPORTANT: Always use absolute paths for reliability. Paths are automatically normalized regardless of slash direction. \n\n🐳 DOCKER: Prefer paths within mounted directories: /home/ubuntu.\nWhen users ask about file locations, check these mounted paths first. Relative paths may fail as they depend on the current working directory. Tilde paths (~/...) might not work in all contexts. Unless the user explicitly asks for relative paths, use absolute paths.\n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-move_file", "parameters": {"type": "object", "required": ["source", "destination"], "properties": {"source": {"type": "string"}, "destination": {"type": "string"}}, "additionalProperties": false}, "description": "\n                        Move or rename files and directories.\n                        \n                        Can move files between directories and rename them in a single operation.\n                        Both source and destination must be within allowed directories.\n                        \n                        IMPORTANT: Always use absolute paths for reliability. Paths are automatically normalized regardless of slash direction. \n\n🐳 DOCKER: Prefer paths within mounted directories: /home/ubuntu.\nWhen users ask about file locations, check these mounted paths first. Relative paths may fail as they depend on the current working directory. Tilde paths (~/...) might not work in all contexts. Unless the user explicitly asks for relative paths, use absolute paths.\n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-start_search", "parameters": {"type": "object", "required": ["path", "pattern"], "properties": {"path": {"type": "string"}, "pattern": {"type": "string"}, "ignoreCase": {"type": "boolean", "default": true}, "maxResults": {"type": "number"}, "searchType": {"enum": ["files", "content"], "type": "string", "default": "files"}, "timeout_ms": {"type": "number"}, "filePattern": {"type": "string"}, "contextLines": {"type": "number", "default": 5}, "includeHidden": {"type": "boolean", "default": false}, "literalSearch": {"type": "boolean", "default": false}, "earlyTermination": {"type": "boolean"}}, "additionalProperties": false}, "description": "\n                        Start a streaming search that can return results progressively.\n                        \n                        SEARCH STRATEGY GUIDE:\n                        Choose the right search type based on what the user is looking for:\n                        \n                        USE searchType=\"files\" WHEN:\n                        - User asks for specific files: \"find package.json\", \"locate config files\"\n                        - Pattern looks like a filename: \"*.js\", \"README.md\", \"test-*.tsx\" \n                        - User wants to find files by name/extension: \"all TypeScript files\", \"Python scripts\"\n                        - Looking for configuration/setup files: \".env\", \"dockerfile\", \"tsconfig.json\"\n                        \n                        USE searchType=\"content\" WHEN:\n                        - User asks about code/logic: \"authentication logic\", \"error handling\", \"API calls\"\n                        - Looking for functions/variables: \"getUserData function\", \"useState hook\"\n                        - Searching for text/comments: \"TODO items\", \"FIXME comments\", \"documentation\"\n                        - Finding patterns in code: \"console.log statements\", \"import statements\"\n                        - User describes functionality: \"components that handle login\", \"files with database queries\"\n                        \n                        WHEN UNSURE OR USER REQUEST IS AMBIGUOUS:\n                        Run TWO searches in parallel - one for files and one for content:\n                        \n                        Example approach for ambiguous queries like \"find authentication stuff\":\n                        1. Start file search: searchType=\"files\", pattern=\"auth\"\n                        2. Simultaneously start content search: searchType=\"content\", pattern=\"authentication\"  \n                        3. Present combined results: \"Found 3 auth-related files and 8 files containing authentication code\"\n                        \n                        SEARCH TYPES:\n                        - searchType=\"files\": Find files by name (pattern matches file names)\n                        - searchType=\"content\": Search inside files for text patterns\n                        \n                        PATTERN MATCHING MODES:\n                        - Default (literalSearch=false): Patterns are treated as regular expressions\n                        - Literal (literalSearch=true): Patterns are treated as exact strings\n                        \n                        WHEN TO USE literalSearch=true:\n                        Use literal search when searching for code patterns with special characters:\n                        - Function calls with parentheses and quotes\n                        - Array access with brackets\n                        - Object methods with dots and parentheses\n                        - File paths with backslashes\n                        - Any pattern containing: . * + ? ^ $ { } [ ] | \\ ( )\n                        \n                        IMPORTANT PARAMETERS:\n                        - pattern: What to search for (file names OR content text)\n                        - literalSearch: Use exact string matching instead of regex (default: false)\n                        - filePattern: Optional filter to limit search to specific file types (e.g., \"*.js\", \"package.json\")\n                        - ignoreCase: Case-insensitive search (default: true). Works for both file names and content.\n                        - earlyTermination: Stop search early when exact filename match is found (optional: defaults to true for file searches, false for content searches)\n                        \n                        DECISION EXAMPLES:\n                        - \"find package.json\" → searchType=\"files\", pattern=\"package.json\" (specific file)\n                        - \"find authentication components\" → searchType=\"content\", pattern=\"authentication\" (looking for functionality)\n                        - \"locate all React components\" → searchType=\"files\", pattern=\"*.tsx\" or \"*.jsx\" (file pattern)\n                        - \"find TODO comments\" → searchType=\"content\", pattern=\"TODO\" (text in files)\n                        - \"show me login files\" → AMBIGUOUS → run both: files with \"login\" AND content with \"login\"\n                        - \"find config\" → AMBIGUOUS → run both: config files AND files containing config code\n                        \n                        COMPREHENSIVE SEARCH EXAMPLES:\n                        - Find package.json files: searchType=\"files\", pattern=\"package.json\"\n                        - Find all JS files: searchType=\"files\", pattern=\"*.js\"\n                        - Search for TODO in code: searchType=\"content\", pattern=\"TODO\", filePattern=\"*.js|*.ts\"\n                        - Search for exact code: searchType=\"content\", pattern=\"toast.error(''test'')\", literalSearch=true\n                        - Ambiguous request \"find auth stuff\": Run two searches:\n                          1. searchType=\"files\", pattern=\"auth\"\n                          2. searchType=\"content\", pattern=\"authentication\"\n                        \n                        PRO TIP: When user requests are ambiguous about whether they want files or content,\n                        run both searches concurrently and combine results for comprehensive coverage.\n                        \n                        Unlike regular search tools, this starts a background search process and returns\n                        immediately with a session ID. Use get_more_search_results to get results as they\n                        come in, and stop_search to stop the search early if needed.\n                        \n                        Perfect for large directories where you want to see results immediately and\n                        have the option to cancel if the search takes too long or you find what you need.\n                        \n                        IMPORTANT: Always use absolute paths for reliability. Paths are automatically normalized regardless of slash direction. \n\n🐳 DOCKER: Prefer paths within mounted directories: /home/ubuntu.\nWhen users ask about file locations, check these mounted paths first. Relative paths may fail as they depend on the current working directory. Tilde paths (~/...) might not work in all contexts. Unless the user explicitly asks for relative paths, use absolute paths.\n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-get_more_search_results", "parameters": {"type": "object", "required": ["sessionId"], "properties": {"length": {"type": "number", "default": 100}, "offset": {"type": "number", "default": 0}, "sessionId": {"type": "string"}}, "additionalProperties": false}, "description": "\n                        Get more results from an active search with offset-based pagination.\n                        \n                        Supports partial result reading with:\n                        - ''offset'' (start result index, default: 0)\n                          * Positive: Start from result N (0-based indexing)\n                          * Negative: Read last N results from end (tail behavior)\n                        - ''length'' (max results to read, default: 100)\n                          * Used with positive offsets for range reading\n                          * Ignored when offset is negative (reads all requested tail results)\n                        \n                        Examples:\n                        - offset: 0, length: 100     → First 100 results\n                        - offset: 200, length: 50    → Results 200-249\n                        - offset: -20                → Last 20 results\n                        - offset: -5, length: 10     → Last 5 results (length ignored)\n                        \n                        Returns only results in the specified range, along with search status.\n                        Works like read_process_output - call this repeatedly to get progressive\n                        results from a search started with start_search.\n                        \n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-stop_search", "parameters": {"type": "object", "required": ["sessionId"], "properties": {"sessionId": {"type": "string"}}, "additionalProperties": false}, "description": "\n                        Stop an active search.\n                        \n                        Stops the background search process gracefully. Use this when you''ve found\n                        what you need or if a search is taking too long. Similar to force_terminate\n                        for terminal processes.\n                        \n                        The search will still be available for reading final results until it''s\n                        automatically cleaned up after 5 minutes.\n                        \n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-list_searches", "parameters": {"type": "object", "properties": {}, "additionalProperties": false}, "description": "\n                        List all active searches.\n                        \n                        Shows search IDs, search types, patterns, status, and runtime.\n                        Similar to list_sessions for terminal processes. Useful for managing\n                        multiple concurrent searches.\n                        \n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-get_file_info", "parameters": {"type": "object", "required": ["path"], "properties": {"path": {"type": "string"}}, "additionalProperties": false}, "description": "\n                        Retrieve detailed metadata about a file or directory including:\n                        - size\n                        - creation time\n                        - last modified time\n                        - permissions\n                        - type\n                        - lineCount (for text files)\n                        - lastLine (zero-indexed number of last line, for text files)\n                        - appendPosition (line number for appending, for text files)\n                        - sheets (for Excel files - array of {name, rowCount, colCount})\n\n                        Only works within allowed directories.\n                        \n                        IMPORTANT: Always use absolute paths for reliability. Paths are automatically normalized regardless of slash direction. \n\n🐳 DOCKER: Prefer paths within mounted directories: /home/ubuntu.\nWhen users ask about file locations, check these mounted paths first. Relative paths may fail as they depend on the current working directory. Tilde paths (~/...) might not work in all contexts. Unless the user explicitly asks for relative paths, use absolute paths.\n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-edit_block", "parameters": {"type": "object", "required": ["file_path"], "properties": {"range": {"type": "string"}, "content": {}, "options": {"type": "object", "additionalProperties": {}}, "file_path": {"type": "string"}, "new_string": {"type": "string"}, "old_string": {"type": "string"}, "expected_replacements": {"type": "number", "default": 1}}, "additionalProperties": false}, "description": "\n                        Apply surgical edits to files.\n\n                        BEST PRACTICE: Make multiple small, focused edits rather than one large edit.\n                        Each edit_block call should change only what needs to be changed - include just enough\n                        context to uniquely identify the text being modified.\n\n                        FORMAT HANDLING (by extension):\n\n                        EXCEL FILES (.xlsx, .xls, .xlsm) - Range Update mode:\n                        Takes:\n                        - file_path: Path to the Excel file\n                        - range: ALWAYS use FROM:TO format - \"SheetName!A1:C10\" or \"SheetName!C1:C1\"\n                        - content: 2D array, e.g., [[\"H1\",\"H2\"],[\"R1\",\"R2\"]]\n\n                        TEXT FILES - Find/Replace mode:\n                        Takes:\n                        - file_path: Path to the file to edit\n                        - old_string: Text to replace\n                        - new_string: Replacement text\n                        - expected_replacements: Optional number of replacements (default: 1)\n\n                        DOCX FILES (.docx) - XML Find/Replace mode:\n                        Takes same parameters as text files (old_string, new_string, expected_replacements).\n                        Operates on the pretty-printed XML inside the DOCX — the same XML you see from\n                        read_file with offset/length. Copy XML fragments from read output as old_string.\n                        After editing, the XML is repacked into a valid DOCX.\n                        Also searches headers/footers if not found in document body.\n                        Examples:\n                        - Replace text: old_string=\"<w:t>Old Text</w:t>\" new_string=\"<w:t>New Text</w:t>\"\n                        - Change style: old_string=''<w:pStyle w:val=\"Normal\"/>'' new_string=''<w:pStyle w:val=\"Heading1\"/>''\n                        - Add content: include surrounding XML context in old_string, add new elements in new_string\n\n                        By default, replaces only ONE occurrence of the search text.\n                        To replace multiple occurrences, provide expected_replacements with\n                        the exact number of matches expected.\n\n                        UNIQUENESS REQUIREMENT: When expected_replacements=1 (default), include the minimal\n                        amount of context necessary (typically 1-3 lines) before and after the change point,\n                        with exact whitespace and indentation.\n\n                        When editing multiple sections, make separate edit_block calls for each distinct change\n                        rather than one large replacement.\n\n                        When a close but non-exact match is found, a character-level diff is shown in the format:\n                        common_prefix{-removed-}{+added+}common_suffix to help you identify what''s different.\n\n                        Similar to write_file, there is a configurable line limit (fileWriteLineLimit) that warns\n                        if the edited file exceeds this limit. If this happens, consider breaking your edits into\n                        smaller, more focused changes.\n\n                        IMPORTANT: Always use absolute paths for reliability. Paths are automatically normalized regardless of slash direction. \n\n🐳 DOCKER: Prefer paths within mounted directories: /home/ubuntu.\nWhen users ask about file locations, check these mounted paths first. Relative paths may fail as they depend on the current working directory. Tilde paths (~/...) might not work in all contexts. Unless the user explicitly asks for relative paths, use absolute paths.\n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-start_process", "parameters": {"type": "object", "required": ["command", "timeout_ms"], "properties": {"shell": {"type": "string"}, "command": {"type": "string"}, "timeout_ms": {"type": "number"}, "verbose_timing": {"type": "boolean"}}, "additionalProperties": false}, "description": "\n                        Start a new terminal process with intelligent state detection.\n                        \n                        PRIMARY TOOL FOR FILE ANALYSIS AND DATA PROCESSING\n                        This is the ONLY correct tool for analyzing local files (CSV, JSON, logs, etc.).\n                        The analysis tool CANNOT access local files and WILL FAIL - always use processes for file-based work.\n                        \n                        CRITICAL RULE: For ANY local file work, ALWAYS use this tool + interact_with_process, NEVER use analysis/REPL tool.\n                        \n                        Running on Linux (Docker). Default shell: bash.\n\n🐳 DOCKER CONTAINER ENVIRONMENT DETECTED:\nThis Desktop Commander instance is running inside a Docker container.\n\nAVAILABLE MOUNTED DIRECTORIES:\n- /home/ubuntu (read-write) - Host folder: ubuntu\n\nIMPORTANT: When users ask about files, FIRST check mounted directories above.\nFiles outside these paths will be lost when the container stops.\nAlways suggest using mounted directories for file operations.\n\nPATH TRANSLATION IN DOCKER:\nWhen users provide host paths, translate to container paths:\n\nWindows: \"C:\\projects\\data\\file.txt\" → \"/home/projects/data/file.txt\"\nLinux/Mac: \"/Users/john/projects/data/file.txt\" → \"/home/projects/data/file.txt\"\n\nRules: Remove drive letter/user prefix, keep full folder structure, mount to /home/\n\nNOTE: Desktop Commander Docker installer mounts host folders to /home/[folder-name].\nContainer: 345a45789e7c\n        \nLINUX-SPECIFIC NOTES:\n- Package managers vary by distro: apt, yum, dnf, pacman, zypper\n- Python 3 might be ''python3'' command, not ''python''\n- Standard Unix shell tools available (grep, awk, sed, etc.)\n- File permissions and ownership important for many operations\n- Systemd services common on modern distributions\n                        \n                        REQUIRED WORKFLOW FOR LOCAL FILES:\n                        1. start_process(\"python3 -i\") - Start Python REPL for data analysis\n                        2. interact_with_process(pid, \"import pandas as pd, numpy as np\")\n                        3. interact_with_process(pid, \"df = pd.read_csv(''/absolute/path/file.csv'')\")\n                        4. interact_with_process(pid, \"print(df.describe())\")\n                        5. Continue analysis with pandas, matplotlib, seaborn, etc.\n                        \n                        COMMON FILE ANALYSIS PATTERNS:\n                        • start_process(\"python3 -i\") → Python REPL for data analysis (RECOMMENDED)\n                        • start_process(\"node -i\") → Node.js REPL for JSON processing\n                        • start_process(\"node:local\") → Node.js on MCP server (stateless, ES imports, all code in one call)\n                        • start_process(\"cut -d'','' -f1 file.csv | sort | uniq -c\") → Quick CSV analysis\n                        • start_process(\"wc -l /path/file.csv\") → Line counting\n                        • start_process(\"head -10 /path/file.csv\") → File preview\n                        \n                        BINARY FILE SUPPORT:\n                        For PDF, Excel, Word, archives, databases, and other binary formats, use process tools with appropriate libraries or command-line utilities.\n                        \n                        INTERACTIVE PROCESSES FOR DATA ANALYSIS:\n                        For code/calculations, use in this priority order:\n                        1. start_process(\"python3 -i\") - Python REPL (preferred)\n                        2. start_process(\"node -i\") - Node.js REPL (when Python unavailable)\n                        3. start_process(\"node:local\") - Node.js fallback (when node -i fails)\n                        4. Use interact_with_process() to send commands\n                        5. Use read_process_output() to get responses\n                        When Python is unavailable, prefer Node.js over shell for calculations.\n                        Node.js: Always use ES import syntax (import x from ''y''), not require().\n\n                        SMART DETECTION:\n                        - Detects REPL prompts (>>>, >, $, etc.)\n                        - Identifies when process is waiting for input\n                        - Recognizes process completion vs timeout\n                        - Early exit prevents unnecessary waiting\n                        \n                        STATES DETECTED:\n                        Process waiting for input (shows prompt)\n                        Process finished execution\n                        Process running (use read_process_output)\n\n                        PERFORMANCE DEBUGGING (verbose_timing parameter):\n                        Set verbose_timing: true to get detailed timing information including:\n                        - Exit reason (early_exit_quick_pattern, early_exit_periodic_check, process_exit, timeout)\n                        - Total duration and time to first output\n                        - Complete timeline of all output events with timestamps\n                        - Which detection mechanism triggered early exit\n                        Use this to identify missed optimization opportunities and improve detection patterns.\n\n                        ALWAYS USE FOR: Local file analysis, CSV processing, data exploration, system commands\n                        NEVER USE ANALYSIS TOOL FOR: Local file access (analysis tool is browser-only and WILL FAIL)\n\n                        IMPORTANT: Always use absolute paths for reliability. Paths are automatically normalized regardless of slash direction. \n\n🐳 DOCKER: Prefer paths within mounted directories: /home/ubuntu.\nWhen users ask about file locations, check these mounted paths first. Relative paths may fail as they depend on the current working directory. Tilde paths (~/...) might not work in all contexts. Unless the user explicitly asks for relative paths, use absolute paths.\n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-read_process_output", "parameters": {"type": "object", "required": ["pid"], "properties": {"pid": {"type": "number"}, "length": {"type": "number"}, "offset": {"type": "number"}, "timeout_ms": {"type": "number"}, "verbose_timing": {"type": "boolean"}}, "additionalProperties": false}, "description": "\n                        Read output from a running process with file-like pagination support.\n                        \n                        Supports partial output reading with offset and length parameters (like read_file):\n                        - ''offset'' (start line, default: 0)\n                          * offset=0: Read NEW output since last read (default, like old behavior)\n                          * Positive: Read from absolute line position\n                          * Negative: Read last N lines from end (tail behavior)\n                        - ''length'' (max lines to read, default: configurable via ''fileReadLineLimit'' setting)\n                        \n                        Examples:\n                        - offset: 0, length: 100     → First 100 NEW lines since last read\n                        - offset: 0                  → All new lines (respects config limit)\n                        - offset: 500, length: 50    → Lines 500-549 (absolute position)\n                        - offset: -20                → Last 20 lines (tail)\n                        - offset: -50, length: 10    → Start 50 from end, read 10 lines\n                        \n                        OUTPUT PROTECTION:\n                        - Uses same fileReadLineLimit as read_file (default: 1000 lines)\n                        - Returns status like: [Reading 100 lines from line 0 (total: 5000 lines, 4900 remaining)]\n                        - Prevents context overflow from verbose processes\n                        \n                        SMART FEATURES:\n                        - For offset=0, waits up to timeout_ms for new output to arrive\n                        - Detects REPL prompts and process completion\n                        - Shows process state (waiting for input, finished, etc.)\n                        \n                        DETECTION STATES:\n                        Process waiting for input (ready for interact_with_process)\n                        Process finished execution\n                        Timeout reached (may still be running)\n\n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-interact_with_process", "parameters": {"type": "object", "required": ["pid", "input"], "properties": {"pid": {"type": "number"}, "input": {"type": "string"}, "timeout_ms": {"type": "number"}, "verbose_timing": {"type": "boolean"}, "wait_for_prompt": {"type": "boolean"}}, "additionalProperties": false}, "description": "\n                        Send input to a running process and automatically receive the response.\n                        \n                        CRITICAL: THIS IS THE PRIMARY TOOL FOR ALL LOCAL FILE ANALYSIS\n                        For ANY local file analysis (CSV, JSON, data processing), ALWAYS use this instead of the analysis tool.\n                        The analysis tool CANNOT access local files and WILL FAIL - use processes for ALL file-based work.\n                        \n                        FILE ANALYSIS PRIORITY ORDER (MANDATORY):\n                        1. ALWAYS FIRST: Use this tool (start_process + interact_with_process) for local data analysis\n                        2. ALTERNATIVE: Use command-line tools (cut, awk, grep) for quick processing  \n                        3. NEVER EVER: Use analysis tool for local file access (IT WILL FAIL)\n                        \n                        REQUIRED INTERACTIVE WORKFLOW FOR FILE ANALYSIS:\n                        1. Start REPL: start_process(\"python3 -i\")\n                        2. Load libraries: interact_with_process(pid, \"import pandas as pd, numpy as np\")\n                        3. Read file: interact_with_process(pid, \"df = pd.read_csv(''/absolute/path/file.csv'')\")\n                        4. Analyze: interact_with_process(pid, \"print(df.describe())\")\n                        5. Continue: interact_with_process(pid, \"df.groupby(''column'').size()\")\n                        \n                        BINARY FILE PROCESSING WORKFLOWS:\n                        Use appropriate Python libraries (PyPDF2, pandas, docx2txt, etc.) or command-line tools for binary file analysis.\n                        \n                        SMART DETECTION:\n                        - Automatically waits for REPL prompt (>>>, >, etc.)\n                        - Detects errors and completion states\n                        - Early exit prevents timeout delays\n                        - Clean output formatting (removes prompts)\n                        \n                        SUPPORTED REPLs:\n                        - Python: python3 -i (RECOMMENDED for data analysis)\n                        - Node.js: node -i\n                        - R: R\n                        - Julia: julia\n                        - Shell: bash, zsh\n                        - Database: mysql, postgres\n                        \n                        PARAMETERS:\n                        - pid: Process ID from start_process\n                        - input: Code/command to execute\n                        - timeout_ms: Max wait (default: 8000ms)\n                        - wait_for_prompt: Auto-wait for response (default: true)\n                        - verbose_timing: Enable detailed performance telemetry (default: false)\n\n                        Returns execution result with status indicators.\n\n                        PERFORMANCE DEBUGGING (verbose_timing parameter):\n                        Set verbose_timing: true to get detailed timing information including:\n                        - Exit reason (early_exit_quick_pattern, early_exit_periodic_check, process_finished, timeout, no_wait)\n                        - Total duration and time to first output\n                        - Complete timeline of all output events with timestamps\n                        - Which detection mechanism triggered early exit\n                        Use this to identify slow interactions and optimize detection patterns.\n\n                        ALWAYS USE FOR: CSV analysis, JSON processing, file statistics, data visualization prep, ANY local file work\n                        NEVER USE ANALYSIS TOOL FOR: Local file access (it cannot read files from disk and WILL FAIL)\n\n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-force_terminate", "parameters": {"type": "object", "required": ["pid"], "properties": {"pid": {"type": "number"}}, "additionalProperties": false}, "description": "\n                        Force terminate a running terminal session.\n                        \n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-list_sessions", "parameters": {"type": "object", "properties": {}, "additionalProperties": false}, "description": "\n                        List all active terminal sessions.\n                        \n                        Shows session status including:\n                        - PID: Process identifier  \n                        - Blocked: Whether session is waiting for input\n                        - Runtime: How long the session has been running\n                        \n                        DEBUGGING REPLs:\n                        - \"Blocked: true\" often means REPL is waiting for input\n                        - Use this to verify sessions are running before sending input\n                        - Long runtime with blocked status may indicate stuck process\n                        \n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-list_processes", "parameters": {"type": "object", "properties": {}, "additionalProperties": false}, "description": "\n                        List all running processes.\n                        \n                        Returns process information including PID, command name, CPU usage, and memory usage.\n                        \n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-kill_process", "parameters": {"type": "object", "required": ["pid"], "properties": {"pid": {"type": "number"}}, "additionalProperties": false}, "description": "\n                        Terminate a running process by PID.\n\n                        Use with caution as this will forcefully terminate the specified process.\n\n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-get_usage_stats", "parameters": {"type": "object", "properties": {}, "additionalProperties": false}, "description": "\n                        Get usage statistics for debugging and analysis.\n                        \n                        Returns summary of tool usage, success/failure rates, and performance metrics.\n                        \n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-get_recent_tool_calls", "parameters": {"type": "object", "properties": {"since": {"type": "string", "format": "date-time"}, "toolName": {"type": "string"}, "maxResults": {"type": "number", "default": 50, "maximum": 1000, "minimum": 1}}, "additionalProperties": false}, "description": "\n                        Get recent tool call history with their arguments and outputs.\n                        Returns chronological list of tool calls made during this session.\n                        \n                        Useful for:\n                        - Onboarding new chats about work already done\n                        - Recovering context after chat history loss\n                        - Debugging tool call sequences\n                        \n                        Note: Does not track its own calls or other meta/query tools.\n                        History kept in memory (last 1000 calls, lost on restart).\n                        \n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-give_feedback_to_desktop_commander", "parameters": {"type": "object", "properties": {}, "additionalProperties": false}, "description": "\n                        Open feedback form in browser to provide feedback about Desktop Commander.\n                        \n                        IMPORTANT: This tool simply opens the feedback form - no pre-filling available.\n                        The user will fill out the form manually in their browser.\n                        \n                        WORKFLOW:\n                        1. When user agrees to give feedback, just call this tool immediately\n                        2. No need to ask questions or collect information\n                        3. Tool opens form with only usage statistics pre-filled automatically:\n                           - tool_call_count: Number of commands they''ve made\n                           - days_using: How many days they''ve used Desktop Commander\n                           - platform: Their operating system (Mac/Windows/Linux)\n                           - client_id: Analytics identifier\n                        \n                        All survey questions will be answered directly in the form:\n                        - Job title and technical comfort level\n                        - Company URL for industry context\n                        - Other AI tools they use\n                        - Desktop Commander''s biggest advantage\n                        - How they typically use it\n                        - Recommendation likelihood (0-10)\n                        - User study participation interest\n                        - Email and any additional feedback\n                        \n                        EXAMPLE INTERACTION:\n                        User: \"sure, I''ll give feedback\"\n                        Claude: \"Perfect! Let me open the feedback form for you.\"\n                        [calls tool immediately]\n                        \n                        No parameters are needed - just call the tool to open the form.\n                        \n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}, {"name": "linux-sandbox-get_prompts", "parameters": {"type": "object", "required": ["action", "promptId"], "properties": {"action": {"enum": ["get_prompt"], "type": "string"}, "promptId": {"type": "string"}}, "additionalProperties": false}, "description": "\n                        Retrieve a specific Desktop Commander onboarding prompt by ID and execute it.\n                        \n                        SIMPLIFIED ONBOARDING V2: This tool only supports direct prompt retrieval.\n                        The onboarding system presents 5 options as a simple numbered list:\n                        \n                        1. Organize my Downloads folder (promptId: ''onb2_01'')\n                        2. Explain a codebase or repository (promptId: ''onb2_02'')\n                        3. Create organized knowledge base (promptId: ''onb2_03'')\n                        4. Analyze a data file (promptId: ''onb2_04'')\n                        5. Check system health and resources (promptId: ''onb2_05'')\n                        \n                        USAGE:\n                        When user says \"1\", \"2\", \"3\", \"4\", or \"5\" from onboarding:\n                        - \"1\" → get_prompts(action=''get_prompt'', promptId=''onb2_01'')\n                        - \"2\" → get_prompts(action=''get_prompt'', promptId=''onb2_02'')\n                        - \"3\" → get_prompts(action=''get_prompt'', promptId=''onb2_03'')\n                        - \"4\" → get_prompts(action=''get_prompt'', promptId=''onb2_04'')\n                        - \"5\" → get_prompts(action=''get_prompt'', promptId=''onb2_05'')\n                        \n                        The prompt content will be injected and execution begins immediately.\n\n                        This command can be referenced as \"DC: ...\" or \"use Desktop Commander to ...\" in your instructions."}], "meta": {"title": "mcphub-linux-sandbox", "avatar": "🐧", "description": "mcphub-linux-sandbox MCP server has 26 tools"}, "type": "mcp", "identifier": "mcphub-linux-sandbox"}', NULL, '{"mcp": {"url": "http://mcphub:3000/mcp/linux-sandbox", "auth": {"type": "none"}, "type": "http"}}', '2026-04-29 11:45:18.045506+00', '2026-04-29 11:45:18.045506+00', '2026-04-29 11:45:18.045506+00');
INSERT INTO public.user_installed_plugins VALUES ('4ee2c53f-bbd1-4a47-bb39-98f018730d41', 'mcphub-diagrams', 'customPlugin', '{"api": [{"name": "infrastructure-diagrams-generate_diagram", "parameters": {"type": "object", "title": "mcp_generate_diagramArguments", "required": ["code"], "properties": {"code": {"type": "string", "title": "Code", "description": "Python code using the diagrams package DSL. The runtime already imports everything needed so you can start immediately using `with Diagram(`"}, "timeout": {"type": "integer", "title": "Timeout", "default": 90, "description": "The timeout for diagram generation in seconds. Default is 90 seconds."}, "filename": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Filename", "default": null, "description": "The filename to save the diagram to. If not provided, a random name will be generated."}, "workspace_dir": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Workspace Dir", "default": null, "description": "The user''s current workspace directory. CRITICAL: Client must always send the current workspace directory when calling this tool! If provided, diagrams will be saved to a ''generated-diagrams'' subdirectory."}}}, "description": "Generate a diagram from Python code using the diagrams package.\n\nThis tool accepts Python code as a string that uses the diagrams package DSL\nand generates both PNG and editable .drawio files. The code is executed with\nshow=False to prevent automatic display.\n\nUSAGE INSTRUCTIONS:\nNever import. Start writing code immediately with `with Diagram(` and use the icons you found with list_icons.\n1. First use get_diagram_examples to understand the syntax and capabilities\n2. Then use list_icons to discover all available icons. These are the only icons you can work with.\n3. You MUST use icon names exactly as they are in the list_icons response, case-sensitive.\n4. Write your diagram code following python diagrams examples. Do not import any additional icons or packages, the runtime already imports everything needed.\n5. Submit your code to this tool to generate the diagram\n6. The tool returns paths to both the PNG image and editable .drawio file\n7. For complex diagrams, consider using Clusters to organize components\n8. Diagrams should start with a user or end device on the left, with data flowing to the right.\n\nCODE REQUIREMENTS:\n- Must include a Diagram() definition with appropriate parameters\n- Can use any of the supported diagram components (AWS, K8s, etc.)\n- Can include custom styling with Edge attributes (color, style)\n- Can use Cluster to group related components\n- Can use custom icons with the Custom class\n\nCOMMON PATTERNS:\n- Basic: provider.service(\"label\")\n- Connections: service1 >> service2 >> service3\n- Grouping: with Cluster(\"name\"): [components]\n- Styling: service1 >> Edge(color=\"red\", style=\"dashed\") >> service2\n\nIMPORTANT FOR CLINE: Always send the current workspace directory when calling this tool!\nThe workspace_dir parameter should be set to the directory where the user is currently working\nso that diagrams are saved to a location accessible to the user.\n\nSupported diagram types:\n- AWS architecture diagrams\n- Sequence diagrams\n- Flow diagrams\n- Class diagrams\n- Kubernetes diagrams\n- On-premises diagrams\n- Custom diagrams with custom nodes\n\nReturns:\n    List containing:\n    - TextContent with success message and paths to both PNG and .drawio files\n    - ImageContent with the generated diagram (PNG) for immediate display\n\nOUTPUT FILES:\n    - PNG diagram: For immediate viewing and sharing\n    - .drawio file: Editable diagram that can be opened in diagrams.net/draw.io for further customization\n"}, {"name": "infrastructure-diagrams-get_diagram_examples", "parameters": {"type": "object", "$defs": {"DiagramType": {"enum": ["aws", "gcp", "azure", "k8s", "onprem", "hybrid", "multicloud", "sequence", "flow", "class", "custom", "all"], "type": "string", "title": "DiagramType", "description": "Enum for supported diagram types."}}, "title": "mcp_get_diagram_examplesArguments", "properties": {"diagram_type": {"$ref": "#/$defs/DiagramType", "default": "all", "description": "Type of diagram example to return. Options: aws, gcp, azure, k8s, onprem, hybrid, multicloud, sequence, flow, class, custom, all"}}}, "description": "Get example code for different types of diagrams.\n\nThis tool provides ready-to-use example code for various diagram types across all major cloud providers,\non-premises, hybrid, and multi-cloud architectures. Use these examples to understand the syntax and\ncapabilities of the diagrams package before creating your own custom diagrams.\n\nUSAGE INSTRUCTIONS:\n1. Select the diagram type you''re interested in (or ''all'' to see all examples)\n2. Study the returned examples to understand the structure and syntax\n3. Use these examples as templates for your own diagrams\n4. When ready, modify an example or write your own code and use generate_diagram\n\nEXAMPLE CATEGORIES:\n- aws: AWS cloud architecture diagrams (serverless, microservices, data pipelines, ML workflows)\n- gcp: Google Cloud Platform diagrams (Cloud Functions, BigQuery, Cloud Run, Vertex AI)\n- azure: Microsoft Azure diagrams (App Service, AKS, Synapse, Databricks)\n- k8s: Kubernetes architecture diagrams (pods, services, stateful sets, ingress)\n- onprem: On-premises infrastructure diagrams (servers, databases, networking)\n- hybrid: Hybrid cloud architectures (on-prem + cloud, VPN, disaster recovery)\n- multicloud: Multi-cloud architectures spanning AWS, GCP, and Azure\n- sequence: Process and interaction flow diagrams\n- flow: Decision trees and workflow diagrams\n- class: Object relationship and inheritance diagrams\n- custom: Custom diagrams with custom icons from URLs\n- all: All available examples across all categories\n\nEach example demonstrates different features of the diagrams package:\n- Basic connections between components\n- Grouping with Clusters\n- Advanced styling with Edge attributes\n- Different layout directions\n- Multiple component instances\n- Custom icons and nodes\n- Cross-provider architectures\n\nParameters:\n    diagram_type (str): Type of diagram example to return\n\nReturns:\n    Dictionary with example code for the requested diagram type(s), organized by example name\n"}, {"name": "infrastructure-diagrams-list_icons", "parameters": {"type": "object", "title": "mcp_list_diagram_iconsArguments", "properties": {"service_filter": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Service Filter", "default": null, "description": "Filter icons by service name (e.g., \"compute\", \"database\", \"network\")"}, "provider_filter": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Provider Filter", "default": null, "description": "Filter icons by provider name (e.g., \"aws\", \"gcp\", \"k8s\")"}}}, "description": "List available icons from the diagrams package, with optional filtering.\n\nThis tool dynamically inspects the diagrams package to find available\nproviders, services, and icons that can be used in diagrams.\n\nUSAGE INSTRUCTIONS:\n1. Call without filters to get a list of available providers\n2. Call with provider_filter to get all services and icons for that provider\n3. Call with both provider_filter and service_filter to get icons for a specific service\n\nExample workflow:\n- First call: list_icons() → Returns all available providers\n- Second call: list_icons(provider_filter=\"aws\") → Returns all AWS services and icons\n- Third call: list_icons(provider_filter=\"aws\", service_filter=\"compute\") → Returns AWS compute icons\n\nThis approach is more efficient than loading all icons at once, especially when you only need\nicons from specific providers or services.\n\nReturns:\n    Dictionary with available providers, services, and icons organized hierarchically\n"}, {"name": "infrastructure-diagrams-parse_k8s_manifest", "parameters": {"type": "object", "title": "mcp_parse_k8s_manifestArguments", "required": ["input_source"], "properties": {"input_source": {"type": "string", "title": "Input Source", "description": "File path to YAML file/directory, OR inline YAML content (multi-document supported with --- separators)"}}}, "description": "Parse Kubernetes YAML manifests and extract resources and their relationships.\n\nThis tool parses K8s manifests and returns structured data about resources and connections.\nAfter receiving the parsed data, use list_icons to find appropriate icons, then generate_diagram.\n\nSUPPORTED INPUTS:\n- Single YAML file path: \"/path/to/deployment.yaml\"\n- Directory path: \"/path/to/k8s-manifests/\" (parses all .yaml/.yml files)\n- Inline YAML content: Paste the YAML directly (supports multi-document with ---)\n\nSUPPORTED RESOURCES:\n- Workloads: Pod, Deployment, StatefulSet, DaemonSet, ReplicaSet, Job, CronJob\n- Networking: Service, Ingress, NetworkPolicy\n- Config: ConfigMap, Secret\n- Storage: PersistentVolume, PersistentVolumeClaim, StorageClass\n- RBAC: ServiceAccount, Role, RoleBinding, ClusterRole, ClusterRoleBinding\n- Cluster: Namespace, HPA, LimitRange, ResourceQuota\n\nRELATIONSHIP DETECTION:\n- Service -> Pod (via label selectors)\n- Deployment -> ReplicaSet -> Pod (via ownerReferences)\n- Pod -> ConfigMap/Secret (via volume mounts and envFrom)\n- Pod -> PVC (via volume claims)\n- Ingress -> Service (via backend rules)\n- HPA -> Deployment/StatefulSet (via scaleTargetRef)\n\nReturns:\n    Structured data with resources, relationships, and namespaces.\n    Use this data with list_icons and generate_diagram to create the visual diagram.\n"}, {"name": "infrastructure-diagrams-parse_helm_chart", "parameters": {"type": "object", "title": "mcp_parse_helm_chartArguments", "required": ["chart_path"], "properties": {"namespace": {"type": "string", "title": "Namespace", "default": "default", "description": "Target namespace for templating"}, "chart_path": {"type": "string", "title": "Chart Path", "description": "Path to Helm chart directory (containing Chart.yaml) or .tgz file"}, "values_file": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Values File", "default": null, "description": "Path to values.yaml override file"}, "release_name": {"type": "string", "title": "Release Name", "default": "release", "description": "Helm release name for templating"}, "values_inline": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Values Inline", "default": null, "description": "Inline YAML values to override chart defaults (as a YAML string)"}}}, "description": "Parse a Helm chart and extract K8s resources and their relationships.\n\nThis tool parses Helm charts and returns structured data about resources and connections.\nAfter receiving the parsed data, use list_icons to find appropriate icons, then generate_diagram.\n\nINPUTS:\n- chart_path: Directory containing Chart.yaml, or path to .tgz packaged chart\n- values_file: Optional values.yaml override file\n- values_inline: Optional inline YAML values as a string\n\nHELM CLI:\n- If `helm` is available on PATH, uses `helm template` for accurate rendering\n- If unavailable, falls back to basic Go template parsing (less accurate)\n\nReturns:\n    Structured data with chart info, resources, relationships, and namespaces.\n    Use this data with list_icons and generate_diagram to create the visual diagram.\n"}, {"name": "infrastructure-diagrams-parse_terraform", "parameters": {"type": "object", "title": "mcp_parse_terraformArguments", "required": ["input_source"], "properties": {"input_source": {"type": "string", "title": "Input Source", "description": "Path to .tf file, directory containing .tf files, OR inline HCL content"}}}, "description": "Parse Terraform configurations and extract resources and their relationships.\n\nThis tool parses Terraform HCL files and returns structured data about resources and connections.\nAfter receiving the parsed data, use list_icons to find appropriate icons, then generate_diagram.\n\nSUPPORTED INPUTS:\n- Single .tf file: \"/path/to/main.tf\"\n- Directory: \"/path/to/terraform/\" (parses all .tf files)\n- Inline HCL: Paste Terraform code directly\n\nSUPPORTED PROVIDERS:\n- AWS (aws_*): EC2, Lambda, S3, RDS, VPC, EKS, etc.\n- GCP (google_*): Compute Engine, Cloud Run, GKE, BigQuery, etc.\n- Azure (azurerm_*): VMs, AKS, Storage, SQL, etc.\n- Kubernetes (kubernetes_*): Deployments, Services, ConfigMaps, etc.\n\nRELATIONSHIP DETECTION:\n- Explicit: depends_on declarations\n- Implicit: References like aws_instance.web.id, var.vpc_id, module.vpc.output\n\nReturns:\n    Structured data with providers, resources, modules, data sources, and relationships.\n    Use this data with list_icons and generate_diagram to create the visual diagram.\n"}], "meta": {"title": "mcphub-diagrams", "avatar": "MCP_AVATAR", "description": "mcphub-diagrams MCP server has 6 tools"}, "type": "mcp", "identifier": "mcphub-diagrams"}', NULL, '{"mcp": {"url": "http://mcphub:3000/mcp/infrastructure-diagrams", "auth": {"type": "none"}, "type": "http"}}', '2026-04-29 10:04:28.967549+00', '2026-04-29 10:04:28.967549+00', '2026-04-29 10:04:28.967549+00');
